use crate::{Compiler, ConfigValue, DefinitionKind, E, Json, Result, json, unsupported};
use std::collections::HashSet;

impl Compiler<'_> {
    pub(super) fn node_symmetry(&self) -> Result<Option<Json>> {
        let Some(name) = &self.config.symmetry else {
            return Ok(None);
        };
        if !self.extends("TLC")
            || self
                .module
                .constants
                .iter()
                .chain(&self.module.variables)
                .any(|declaration| declaration.name == "Permutations")
            || self
                .module
                .definitions
                .iter()
                .any(|definition| definition.name == "Permutations")
        {
            return unsupported("SYMMETRY requires TLC.Permutations");
        }
        let Some(definition) = self
            .module
            .definitions
            .iter()
            .find(|definition| definition.name == *name)
        else {
            return unsupported("undefined SYMMETRY operator");
        };
        if definition.is_recursive
            || !matches!(&definition.head, DefinitionKind::Operator { params } if params.is_empty())
        {
            return unsupported("SYMMETRY must be a zero-argument operator");
        }
        let E::Apply { operator, args } = &definition.body.node else {
            return unsupported("SYMMETRY requires Permutations(Nodes)");
        };
        if operator != "Permutations" || args.len() != 1 {
            return unsupported("SYMMETRY requires one complete permutation group");
        }
        let E::Identifier { name } = &args[0].node else {
            return unsupported("SYMMETRY requires a directly assigned constant set");
        };
        let Some(ConfigValue::Set { elements }) = self.constants.get(name) else {
            return unsupported("SYMMETRY requires a finite constant set");
        };
        if !(2..=64).contains(&elements.len()) {
            return unsupported("SYMMETRY requires 2 to 64 model values");
        }
        let mut names = Vec::new();
        for element in elements {
            let ConfigValue::ModelValue { name } = element else {
                return unsupported("SYMMETRY requires untyped model values");
            };
            if name.as_bytes().get(1) == Some(&b'_')
                || rtlc::Value::ModelValue(name.clone()).normalize().is_err()
            {
                return unsupported("SYMMETRY requires valid untyped model values");
            }
            names.push(name.clone());
        }
        if names.iter().collect::<HashSet<_>>().len() != names.len() {
            return unsupported("SYMMETRY model values must be distinct");
        }
        names.sort();
        Ok(Some(json!({"modelValues":names})))
    }
}

fn measurements(criterion: &mut Criterion) {
    let cases: Vec<Value> =
        serde_json::from_str(include_str!("../tests/quint-generated.json")).unwrap();
    let bounds = SafetyBounds {
        max_depth: 64,
        max_states: 10000,
        max_work: 1000000,
        max_temporal_nodes: None,
    };
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let source = case["source"].as_str().unwrap();
        let configuration = case["config"].as_str().unwrap();
        let module = rtla::parse_module(source).unwrap();
        let config = rtla::parse_config(configuration).unwrap();
        let programs: Vec<_> = [(1, IrVersion::V1), (2, IrVersion::V2)]
            .into_iter()
            .map(|(version, ir_version)| {
                let options = CompileOptions {
                    irVersion: ir_version,
                };
                let program = compile_with_options(&module, &config, options).unwrap();
                assert_eq!(program.version, version);
                let result = program.check(bounds).unwrap();
                assert_eq!(result.status, case["expectedStatus"]);
                assert_eq!(result.states as u64, case["expectedStates"]);
                assert_eq!(result.generated as u64, case["expectedGenerated"]);
                assert!(result.states > 0);
                assert!(result.reason.is_none());
                println!(
                    "IDEALIS_QUINT_PROGRAM {}",
                    json!({
                        "name": name,
                        "version": version,
                        "irBytes": serde_json::to_vec(&program).unwrap().len(),
                        "definitions": program.definitions.as_ref().map_or(0, Vec::len),
                        "states": result.states,
                        "generated": result.generated,
                        "work": result.work,
                    })
                );
                (version, options, program)
            })
            .collect();
        criterion.bench_function(&format!("quint-parse/{name}"), |bencher| {
            bencher.iter(|| {
                (
                    rtla::parse_module(black_box(source)).unwrap(),
                    rtla::parse_config(black_box(configuration)).unwrap(),
                )
            });
        });
        for (version, options, program) in programs {
            criterion.bench_function(&format!("quint-compile/{name}/v{version}"), |bencher| {
                bencher.iter(|| {
                    compile_with_options(black_box(&module), black_box(&config), options).unwrap()
                });
            });
            criterion.bench_function(&format!("quint-check/{name}/v{version}"), |bencher| {
                bencher.iter(|| black_box(&program).check(black_box(bounds)).unwrap());
            });
            criterion.bench_function(&format!("quint-end-to-end/{name}/v{version}"), |bencher| {
                bencher.iter(|| {
                    let module = rtla::parse_module(black_box(source)).unwrap();
                    let config = rtla::parse_config(black_box(configuration)).unwrap();
                    compile_with_options(&module, &config, options)
                        .unwrap()
                        .check(black_box(bounds))
                        .unwrap()
                });
            });
        }
    }
}

fn instantiate(
    &mut self,
    instance: &rtla::ast::Instance,
    result: &mut Linked,
    imports: &mut BTreeSet<String>,
) -> Result<()> {
    let mut template = self.module(&instance.module)?;
    if !instance.params.is_empty() {
        let mut definitions: Vec<_> = template.definitions.values().cloned().collect();
        let functions =
            crate::functions::expand(&mut definitions, &mut || Ok(self.rewrite.fresh()))?;
        if !functions.is_empty() {
            for definition in &mut definitions {
                crate::functions::rewrite_tree(&mut definition.body, &functions, 0)?;
                template
                    .origins
                    .entry(definition.name.clone())
                    .or_insert_with(|| (instance.module.clone(), definition.name.clone()));
            }
            template.definitions = definitions
                .into_iter()
                .map(|definition| (definition.name.clone(), definition))
                .collect();
        }
    }
    if instance.name.is_none() {
        imports.extend(template.extends.clone());
        if template.constants.is_empty()
            && template.variables.is_empty()
            && instance.substitutions.is_empty()
        {
            let mut shared = template.clone();
            shared.assumptions.clear();
            for symbol in shared.symbols.values_mut() {
                symbol.local |= instance.is_local;
            }
            result.merge(&shared)?;
            for (name, symbol) in &template.symbols {
                if !symbol.local {
                    result.insert(
                        name,
                        Symbol {
                            local: instance.is_local,
                            ..symbol.clone()
                        },
                    )?;
                }
            }
            return Ok(());
        }
    }
    let mut replacements = BTreeMap::new();
    for substitution in &instance.substitutions {
        if !template
            .symbols
            .get(&substitution.name)
            .is_some_and(|symbol| symbol.kind != Kind::Definition && !symbol.captured)
        {
            return unsupported(format!("unknown INSTANCE parameter {}", substitution.name));
        }
        if replacements
            .insert(substitution.name.clone(), substitution.expression.clone())
            .is_some()
        {
            return unsupported("duplicate INSTANCE substitution");
        }
    }
    let mut names = result.names(instance.location);
    let mut params = vec![];
    for parameter in &instance.params {
        if names.contains_key(&parameter.name) {
            return unsupported(format!("conflicting INSTANCE parameter {}", parameter.name));
        }
        let fresh = self.rewrite.fresh();
        names.insert(
            parameter.name.clone(),
            identifier(&fresh, parameter.location),
        );
        let mut parameter = parameter.clone();
        parameter.name = fresh;
        params.push(parameter);
    }
    self.rewrite.namespaces = result
        .namespaces
        .iter()
        .map(|(name, namespace)| (name.clone(), namespace.arity))
        .collect();
    let mut mapping = Names::new();
    for (name, symbol) in &template.symbols {
        if symbol.kind == Kind::Definition || symbol.captured {
            continue;
        }
        let mut expression = replacements
            .remove(name)
            .unwrap_or_else(|| identifier(name, instance.location));
        let arity = match &expression.node {
            E::Identifier { name } => result
                .symbols
                .get(name)
                .map(|symbol| symbol.arity)
                .or_else(|| {
                    instance
                        .params
                        .iter()
                        .find(|param| param.name == *name)
                        .map(|param| param.arity)
                })
                .or_else(|| crate::symbols::standard_arity(name)),
            E::Lambda { params, .. } => Some(params.len()),
            _ => Some(0),
        };
        if symbol.arity != 0 && arity != Some(symbol.arity)
            || symbol.arity == 0 && arity.is_some_and(|arity| arity != 0)
        {
            return unsupported(format!(
                "INSTANCE parameter {name} expects operator arity {}",
                symbol.arity
            ));
        }
        if symbol.kind == Kind::Variable
            && !matches!(&expression.node, E::Identifier { name } if result.symbols.get(name).is_some_and(|symbol| symbol.kind == Kind::Variable || symbol.kind == Kind::Lexical && symbol.arity == 0) || instance.params.iter().any(|param| param.name == *name && param.arity == 0))
        {
            return unsupported("INSTANCE variable substitution requires a state variable");
        }
        self.rewrite.strict = true;
        self.rewrite.imports = imports.clone();
        self.rewrite.expression(&mut expression, &names)?;
        self.rewrite.strict = false;
        if matches!(&expression.node, E::Identifier { name } if !result.symbols.values().any(|symbol| symbol.id == *name) && !params.iter().any(|param| param.name == *name) && name != "TRUE" && name != "FALSE" && name != "BOOLEAN")
        {
            return unsupported(format!("missing INSTANCE substitution {name}"));
        }
        mapping.insert(symbol.id.clone(), expression);
    }
    for id in template.definitions.keys() {
        let name = self.rewrite.fresh();
        let expression = if params.is_empty() {
            identifier(&name, instance.location)
        } else {
            Expression {
                location: instance.location,
                node: E::Apply {
                    operator: name,
                    args: params
                        .iter()
                        .map(|param| identifier(&param.name, param.location))
                        .collect(),
                },
            }
        };
        mapping.insert(id.clone(), expression);
    }
    for (id, definition) in &template.definitions {
        let name = match &mapping[id].node {
            E::Identifier { name } | E::Apply { operator: name, .. } => name,
            _ => unreachable!(),
        };
        let mut definition = definition.clone();
        definition.name = name.clone();
        self.rewrite.definition(&mut definition, &mapping)?;
        if !params.is_empty() {
            let body = crate::definition_body(&definition);
            let mut leading = params.clone();
            if let DefinitionKind::Operator { params } = definition.head {
                leading.extend(params);
            }
            definition.head = DefinitionKind::Operator { params: leading };
            definition.body = body;
        }
        result.definitions.insert(name.clone(), definition);
        result
            .origins
            .insert(name.clone(), template.origins[id].clone());
    }
    for (name, symbol) in &template.symbols {
        if symbol.local || symbol.captured || symbol.kind != Kind::Definition {
            continue;
        }
        let id = match &mapping[&symbol.id].node {
            E::Identifier { name } | E::Apply { operator: name, .. } => name,
            _ => unreachable!(),
        };
        let public = instance
            .name
            .as_ref()
            .map_or_else(|| name.clone(), |prefix| format!("{prefix}!{name}"));
        result.insert(
            &public,
            Symbol {
                id: id.clone(),
                arity: symbol.arity + params.len(),
                local: instance.is_local,
                ..symbol.clone()
            },
        )?;
    }
    if let Some(name) = &instance.name {
        result.namespace(
            name,
            Namespace {
                id: self.rewrite.fresh(),
                arity: params.len(),
                local: instance.is_local,
            },
        )?;
    }
    for (name, namespace) in &template.namespaces {
        if namespace.local {
            continue;
        }
        let public = instance
            .name
            .as_ref()
            .map_or_else(|| name.clone(), |prefix| format!("{prefix}!{name}"));
        result.namespace(
            &public,
            Namespace {
                id: self.rewrite.fresh(),
                local: instance.is_local,
                ..namespace.clone()
            },
        )?;
    }
    result.extends.extend(template.extends);
    result.limit()?;
    Ok(())
}

use crate::{Result, unsupported};
use rtla::ast::{
    Bound, Definition, DefinitionKind, ExceptPath, Expression, ExpressionKind as E, Pattern,
};
use std::collections::{BTreeMap, BTreeSet};

pub(crate) type Names = BTreeMap<String, Expression>;

pub(crate) fn identifier(name: &str, location: rtla::ast::Location) -> Expression {
    Expression {
        node: E::Identifier { name: name.into() },
        location,
    }
}

pub(crate) struct Rewriter {
    pub next: usize,
    pub strict: bool,
    pub imports: BTreeSet<String>,
    pub labels: BTreeMap<String, String>,
    pub depth: usize,
    pub namespaces: BTreeMap<String, usize>,
    pub translated: BTreeSet<String>,
}

impl Rewriter {
    fn qualifier_arguments(&self, name: &str) -> Result<()> {
        for (index, _) in name.match_indices('!') {
            if self
                .namespaces
                .get(&name[..index])
                .is_some_and(|arity| *arity != 0)
            {
                return unsupported(format!(
                    "missing arguments for module namespace {}",
                    &name[..index]
                ));
            }
        }
        Ok(())
    }

    fn namespace_selection(
        &mut self,
        value: &Expression,
        names: &Names,
    ) -> Result<Option<Expression>> {
        let E::Selection {
            expression,
            selectors,
        } = &value.node
        else {
            return Ok(None);
        };
        let (path, args) = match &expression.node {
            E::Identifier { name } => (name, vec![]),
            E::Apply { operator, args } => (operator, args.clone()),
            _ => return Ok(None),
        };
        let Some(arity) = self.namespaces.get(path) else {
            return Ok(None);
        };
        self.qualifier_arguments(path)?;
        if args.len() != *arity {
            return unsupported(format!("module namespace {path} expects {arity} arguments"));
        }
        let mut path = path.clone();
        let mut arguments = args;
        for (index, selector) in selectors.iter().enumerate() {
            let rtla::ast::Selector::Name { name, args } = selector else {
                return unsupported("expected a member name after module namespace");
            };
            path.push('!');
            path.push_str(name);
            arguments.extend(args.clone());
            if let Some(arity) = self.namespaces.get(&path) {
                if args.len() != *arity {
                    return unsupported(format!(
                        "module namespace {path} expects {arity} arguments"
                    ));
                }
                continue;
            }
            let Some(Expression {
                node: E::Identifier { name },
                ..
            }) = names.get(&path)
            else {
                return unsupported(format!("unknown module member {path}"));
            };
            let mut result = Expression {
                location: value.location,
                node: E::Apply {
                    operator: name.clone(),
                    args: arguments,
                },
            };
            if index + 1 < selectors.len() {
                result = Expression {
                    location: value.location,
                    node: E::Selection {
                        expression: Box::new(result),
                        selectors: selectors[index + 1..].to_vec(),
                    },
                };
            }
            self.expression(&mut result, names)?;
            return Ok(Some(result));
        }
        unsupported("module namespace is not an executable expression")
    }
    fn selection(
        &self,
        name: &str,
        args: Vec<Expression>,
        names: &Names,
        location: rtla::ast::Location,
    ) -> Option<Expression> {
        for (index, _) in name.match_indices('!').rev() {
            if let Some(expression) = names.get(&name[..index]) {
                let mut selectors: Vec<_> = name[index + 1..]
                    .split('!')
                    .map(|name| rtla::ast::Selector::Name {
                        name: name.into(),
                        args: vec![],
                    })
                    .collect();
                if let Some(rtla::ast::Selector::Name { args: actuals, .. }) = selectors.last_mut()
                {
                    *actuals = args;
                }
                return Some(Expression {
                    location,
                    node: E::Selection {
                        expression: Box::new(expression.clone()),
                        selectors,
                    },
                });
            }
        }
        None
    }
    fn imported(&self, operator: &str) -> Result<()> {
        if !self.strict {
            return Ok(());
        }
        let permitted = match operator {
            "+" | "-" | "*" | "\\div" | "%" | "^" | "<" | "<=" | "\\leq" | ">" | ">=" | "\\geq"
            | ".." | "Nat" => ["Naturals", "Integers", "Sequences", "FiniteSets"]
                .iter()
                .any(|name| self.imports.contains(*name)),
            "Int" | "-." => self.imports.contains("Integers"),
            "Seq" | "Len" | "Head" | "Tail" | "Append" | "SubSeq" | "SelectSeq" | "\\o" => {
                self.imports.contains("Sequences")
            }
            "Cardinality" => self.imports.contains("FiniteSets"),
            "SortSeq" | "Assert" => self.imports.contains("TLC"),
            "ApaFoldSet" | "ApaFoldSeqLeft" | ":=" => self.imports.contains("Apalache"),
            "Variant" | "VariantTag" | "VariantGetUnsafe" => self.imports.contains("Variants"),
            _ => true,
        };
        if !permitted {
            return unsupported(format!(
                "operator {operator} is not imported in its defining module"
            ));
        }
        Ok(())
    }
    pub fn fresh(&mut self) -> String {
        let name = format!("$linked{}", self.next);
        self.next += 1;
        name
    }

    fn pattern(
        &mut self,
        pattern: &mut Pattern,
        names: &mut Names,
        location: rtla::ast::Location,
    ) -> Result<()> {
        let entries = match pattern {
            Pattern::Name { name } => std::slice::from_mut(name),
            Pattern::Tuple { names } => names.as_mut_slice(),
        };
        for name in entries {
            if self.strict && names.contains_key(name) {
                return unsupported(format!("duplicate bound name {name}"));
            }
            let fresh = self.fresh();
            names.insert(name.clone(), identifier(&fresh, location));
            *name = fresh;
        }
        Ok(())
    }

    fn bounds(&mut self, bounds: &mut [Bound], names: &mut Names) -> Result<()> {
        for bound in bounds {
            self.expression(&mut bound.set, names)?;
            self.pattern(&mut bound.pattern, names, bound.set.location)?;
        }
        Ok(())
    }

    pub fn definition(&mut self, definition: &mut Definition, names: &Names) -> Result<()> {
        let mut names = names.clone();
        match &mut definition.head {
            DefinitionKind::Operator { params } => {
                for param in params {
                    if self.strict && names.contains_key(&param.name) {
                        return unsupported(format!("duplicate lexical parameter {}", param.name));
                    }
                    let fresh = self.fresh();
                    names.insert(param.name.clone(), identifier(&fresh, param.location));
                    param.name = fresh;
                }
            }
            DefinitionKind::Function { bounds } => self.bounds(bounds, &mut names)?,
        }
        self.expression(&mut definition.body, &names)
    }

    pub fn expression(&mut self, value: &mut Expression, names: &Names) -> Result<()> {
        if self.depth >= 64 {
            return unsupported("module AST depth exceeds 64");
        }
        self.depth += 1;
        let result = self.expression_inner(value, names);
        self.depth -= 1;
        result
    }

    fn let_definitions(
        &mut self,
        definitions: &mut [Definition],
        body: &mut Expression,
        names: &Names,
    ) -> Result<()> {
        let mut names = names.clone();
        for definition in definitions.iter_mut() {
            let standard = match definition.name.as_str() {
                "SelectSeq" => self.imports.contains("Sequences"),
                "SortSeq" | "Assert" => self.imports.contains("TLC"),
                _ => false,
            };
            if self.strict && (names.contains_key(&definition.name) || standard) {
                return unsupported(format!("duplicate LET definition {}", definition.name));
            }
            let fresh = self.fresh();
            if self.translated.contains(&definition.name) {
                self.translated.insert(fresh.clone());
            }
            let label = self
                .labels
                .get(&definition.name)
                .unwrap_or(&definition.name)
                .clone();
            self.labels.insert(fresh.clone(), label);
            names.insert(
                definition.name.clone(),
                identifier(&fresh, definition.location),
            );
            definition.name = fresh;
        }
        for definition in definitions {
            let strict = self.strict;
            self.strict &= !self.translated.contains(&definition.name);
            let result = self.definition(definition, &names);
            self.strict = strict;
            result?;
        }
        self.expression(body, &names)?;
        Ok(())
    }

    fn expression_inner(&mut self, value: &mut Expression, names: &Names) -> Result<()> {
        if let Some(result) = self.namespace_selection(value, names)? {
            *value = result;
            return Ok(());
        }
        match &mut value.node {
            E::Identifier { name } => {
                if let Some(replacement) = names.get(name) {
                    *value = replacement.clone();
                } else if let Some(selection) = self.selection(name, vec![], names, value.location)
                {
                    *value = selection;
                } else if self.strict
                    && !["TRUE", "FALSE", "BOOLEAN", "STRING", "Nat", "Int"]
                        .contains(&name.as_str())
                    && !matches!(
                        name.as_str(),
                        "DOMAIN"
                            | "SUBSET"
                            | "UNION"
                            | "ENABLED"
                            | "UNCHANGED"
                            | "Len"
                            | "Head"
                            | "Tail"
                            | "Append"
                            | "Cardinality"
                    )
                    && name.starts_with(char::is_alphabetic)
                {
                    return unsupported(format!("unresolved module identifier {name}"));
                } else {
                    self.imported(name)?;
                }
            }
            E::Apply { operator, args } => {
                self.qualifier_arguments(operator)?;
                for argument in args.iter_mut() {
                    self.expression(argument, names)?;
                }
                if let Some(replacement) = names.get(operator) {
                    if let E::Identifier { name } = &replacement.node {
                        *operator = name.clone();
                    } else if let E::Apply {
                        operator: target,
                        args: leading,
                    } = &replacement.node
                    {
                        let mut arguments = leading.clone();
                        arguments.append(args);
                        *operator = target.clone();
                        *args = arguments;
                    } else if let E::Lambda { params, body } = &replacement.node {
                        if params.len() != args.len() {
                            return unsupported(
                                "INSTANCE operator replacement has the wrong arity",
                            );
                        }
                        let name = self.fresh();
                        let call = Expression {
                            location: value.location,
                            node: E::Apply {
                                operator: name.clone(),
                                args: args.clone(),
                            },
                        };
                        let definition = Definition {
                            name,
                            head: DefinitionKind::Operator {
                                params: params.clone(),
                            },
                            body: *body.clone(),
                            is_local: false,
                            is_recursive: false,
                            location: value.location,
                        };
                        value.node = E::Let {
                            definitions: vec![definition],
                            body: Box::new(call),
                        };
                    } else if args.is_empty() {
                        *value = replacement.clone();
                    } else {
                        return unsupported("INSTANCE replacement is not an operator");
                    }
                } else if let Some(selection) =
                    self.selection(operator, args.clone(), names, value.location)
                {
                    *value = selection;
                } else if self.strict
                    && operator.starts_with(char::is_alphabetic)
                    && ![
                        "Cardinality",
                        "DOMAIN",
                        "SUBSET",
                        "UNION",
                        "Len",
                        "Head",
                        "Tail",
                        "Append",
                        "SubSeq",
                        "SelectSeq",
                        "SortSeq",
                        "Assert",
                        "Seq",
                        "ApaFoldSet",
                        "ApaFoldSeqLeft",
                        "Variant",
                        "VariantTag",
                        "VariantGetUnsafe",
                    ]
                    .contains(&operator.as_str())
                {
                    return unsupported(format!("unresolved module operator {operator}"));
                } else {
                    self.imported(operator)?;
                }
            }
            E::Lambda { params, body } => {
                let mut names = names.clone();
                for param in params {
                    if self.strict && names.contains_key(&param.name) {
                        return unsupported(format!("duplicate lexical parameter {}", param.name));
                    }
                    let fresh = self.fresh();
                    names.insert(param.name.clone(), identifier(&fresh, param.location));
                    param.name = fresh;
                }
                self.expression(body, &names)?;
            }
            E::LetModule {
                definitions,
                instances,
                body,
                ..
            } => {
                if instances
                    .iter()
                    .any(|instance| instance.module != "$linked")
                {
                    return unsupported("unresolved LET module definitions");
                }
                let previous = self.namespaces.clone();
                for instance in instances {
                    if let Some(name) = &instance.name {
                        self.namespaces.insert(name.clone(), instance.params.len());
                    }
                }
                let result = self.let_definitions(definitions, body, names);
                self.namespaces = previous;
                result?;
                value.node = E::Let {
                    definitions: definitions.clone(),
                    body: body.clone(),
                };
            }
            E::AssumeProve { .. } => {
                return unsupported("ASSUME/PROVE is a proof statement, not an executable value");
            }
            E::Selection {
                expression,
                selectors,
            } => {
                self.expression(expression, names)?;
                for selector in selectors {
                    if let rtla::ast::Selector::Name { args, .. }
                    | rtla::ast::Selector::Arguments { args } = selector
                    {
                        for argument in args {
                            self.expression(argument, names)?;
                        }
                    }
                }
            }
            E::And { operands, .. } | E::Or { operands, .. } => {
                for operand in operands {
                    self.expression(operand, names)?;
                }
            }
            E::Prime { expression }
            | E::Unchanged { expression }
            | E::Enabled { expression }
            | E::Always { expression }
            | E::Eventually { expression } => self.expression(expression, names)?,
            E::If {
                condition,
                consequent,
                alternative,
            } => {
                self.expression(condition, names)?;
                self.expression(consequent, names)?;
                self.expression(alternative, names)?;
            }
            E::Case { arms, other } => {
                for arm in arms {
                    self.expression(&mut arm.condition, names)?;
                    self.expression(&mut arm.body, names)?;
                }
                if let Some(other) = other {
                    self.expression(other, names)?;
                }
            }
            E::Let { definitions, body } => self.let_definitions(definitions, body, names)?,
            E::Forall { bounds, body }
            | E::Exists { bounds, body }
            | E::FunctionConstruction { bounds, body } => {
                let mut names = names.clone();
                self.bounds(bounds, &mut names)?;
                self.expression(body, &names)?;
            }
            E::UnboundedQuantifier { .. } => return unsupported("unbounded module quantification"),
            E::Choose { pattern, set, body } => {
                if let Some(set) = set {
                    self.expression(set, names)?;
                }
                let mut names = names.clone();
                self.pattern(pattern, &mut names, value.location)?;
                self.expression(body, &names)?;
            }
            E::SetEnumeration { elements } | E::Tuple { elements } => {
                for element in elements {
                    self.expression(element, names)?;
                }
            }
            E::SetFilter { bound, predicate } => {
                let mut names = names.clone();
                self.bounds(std::slice::from_mut(bound), &mut names)?;
                self.expression(predicate, &names)?;
            }
            E::SetMap { expression, bounds } => {
                let mut names = names.clone();
                self.bounds(bounds, &mut names)?;
                self.expression(expression, &names)?;
            }
            E::FunctionSet { domain, range } => {
                self.expression(domain, names)?;
                self.expression(range, names)?;
            }
            E::Record { fields } | E::RecordSet { fields } => {
                for field in fields {
                    self.expression(&mut field.value, names)?;
                }
            }
            E::Except { function, updates } => {
                self.expression(function, names)?;
                for update in updates {
                    for path in &mut update.path {
                        if let ExceptPath::Index { args } = path {
                            for argument in args {
                                self.expression(argument, names)?;
                            }
                        }
                    }
                    self.expression(&mut update.value, names)?;
                }
            }
            E::FunctionApplication { function, args } => {
                self.expression(function, names)?;
                for argument in args {
                    self.expression(argument, names)?;
                }
            }
            E::Bracket { args } => {
                for argument in args {
                    self.expression(argument, names)?;
                }
            }
            E::FieldAccess { record, .. } => self.expression(record, names)?,
            E::Product { factors } => {
                for factor in factors {
                    self.expression(factor, names)?;
                }
            }
            E::BoxAction { action, subscript }
            | E::AngleAction { action, subscript }
            | E::WeakFairness { action, subscript }
            | E::StrongFairness { action, subscript } => {
                self.expression(action, names)?;
                self.expression(subscript, names)?;
            }
            E::Label { body, params, .. } => {
                for param in params {
                    if let Some(replacement) = names.get(param) {
                        let E::Identifier { name } = &replacement.node else {
                            return unsupported("label parameter is not a lexical name");
                        };
                        *param = name.clone();
                    }
                }
                self.expression(body, names)?;
            }
            E::Number { .. }
            | E::Integer { .. }
            | E::Decimal { .. }
            | E::String { .. }
            | E::ExceptAt => {}
        }
        Ok(())
    }
}

pub(crate) fn resolve(
    root: &Module,
    config: &Config,
    modules: &[Module],
) -> Result<(Module, Config, BTreeMap<String, String>)> {
    if modules.len() > 256 {
        return unsupported("source bundle exceeds 256 modules");
    }
    let mut linker = Linker {
        declarations: BTreeMap::new(),
        lexical_scopes: BTreeMap::new(),
        introductions: BTreeMap::new(),
        sources: BTreeMap::new(),
        cache: BTreeMap::new(),
        visiting: vec![],
        rewrite: Rewriter {
            next: 0,
            strict: false,
            imports: BTreeSet::new(),
            labels: BTreeMap::new(),
            depth: 0,
            namespaces: BTreeMap::new(),
            translated: BTreeSet::new(),
        },
    };
    let sources = nested::flatten(root, modules)?;
    linker.lexical_scopes = sources.scopes;
    for module in &sources.modules {
        crate::symbols::validate(module)?;
        if STANDARD.contains(&module.name.as_str())
            || linker.sources.insert(module.name.clone(), module).is_some()
        {
            return unsupported(format!("duplicate or reserved module {}", module.name));
        }
        for (kind, declarations) in [
            (Kind::Constant, &module.constants),
            (Kind::Variable, &module.variables),
        ] {
            for declaration in declarations {
                let symbol = Symbol {
                    captured: false,
                    id: linker.rewrite.fresh(),
                    kind,
                    arity: declaration.arity,
                    local: false,
                };
                if linker
                    .declarations
                    .insert((module.name.clone(), declaration.name.clone()), symbol)
                    .is_some()
                {
                    return unsupported(format!("conflicting module symbol {}", declaration.name));
                }
            }
        }
        for definition in &module.definitions {
            let arity = match &definition.head {
                DefinitionKind::Operator { params } => params.len(),
                DefinitionKind::Function { .. } => 0,
            };
            let symbol = Symbol {
                captured: false,
                id: linker.rewrite.fresh(),
                kind: Kind::Definition,
                arity,
                local: definition.is_local,
            };
            if linker
                .declarations
                .insert((module.name.clone(), definition.name.clone()), symbol)
                .is_some()
            {
                return unsupported(format!("conflicting module symbol {}", definition.name));
            }
        }
    }
    let mut linked = linker.module(&root.name)?;
    let config = linker.configure(&mut linked, config, root.location)?;
    let mut names = Names::new();
    let mut variables = vec![];
    for (name, symbol) in &linked.symbols {
        if symbol.kind == Kind::Variable {
            names.insert(symbol.id.clone(), identifier(name, root.location));
            let mut declaration = linked.variables[&symbol.id].clone();
            declaration.name = name.clone();
            variables.push(declaration);
        }
    }
    for definition in linked.definitions.values_mut() {
        linker.rewrite.definition(definition, &names)?;
    }
    for assumption in linked.assumptions.values_mut() {
        linker
            .rewrite
            .expression(&mut assumption.expression, &names)?;
    }
    for (name, symbol) in &linked.symbols {
        if let Some(definition) = linked.definitions.get(&symbol.id) {
            let mut alias = definition.clone();
            alias.name = name.clone();
            alias.body = match &alias.head {
                DefinitionKind::Operator { params } if !params.is_empty() => Expression {
                    node: E::Apply {
                        operator: symbol.id.clone(),
                        args: params
                            .iter()
                            .map(|param| identifier(&param.name, param.location))
                            .collect(),
                    },
                    location: alias.location,
                },
                _ => identifier(&symbol.id, alias.location),
            };
            if matches!(alias.head, DefinitionKind::Function { .. }) {
                alias.head = DefinitionKind::Operator { params: vec![] };
            }
            linked.definitions.insert(name.clone(), alias);
        }
    }
    linked.limit()?;
    let mut action_names = linker.rewrite.labels;
    action_names.extend(
        linked
            .origins
            .iter()
            .map(|(id, (module, name))| (id.clone(), format!("{module}!{name}"))),
    );
    for (name, symbol) in &linked.symbols {
        if linked.definitions.contains_key(&symbol.id) {
            action_names.insert(symbol.id.clone(), name.clone());
        }
    }
    Ok((
        Module {
            name: root.name.clone(),
            extends: linked.extends.into_iter().collect(),
            constants: linked.constants.into_values().collect(),
            variables,
            definitions: linked.definitions.into_values().collect(),
            instances: vec![],
            recursive: vec![],
            modules: vec![],
            directives: vec![],
            assumptions: linked.assumptions.into_values().collect(),
            theorems: vec![],
            location: root.location,
        },
        config,
        action_names,
    ))
}

/// Compile the selected finite TLA+ fragment. Parsing and execution remain separate.
pub fn compile(module: &Module, config: &Config) -> Result<rtlc::SafetyProgram> {
    compile_with_options(module, config, CompileOptions::default())
}

impl Compiler<'_> {
    fn target_context(&mut self, entry: &Entry) -> Context {
        let mut context = self.root(Phase::Next);
        context.origin = entry.id;
        context.scope = entry.scope;
        context.locals = entry.locals.clone();
        context.order = entry.order.clone();
        context.binding_ids = entry.binding_ids.clone();
        context.projection = entry.projection.clone();
        context.static_targets = entry.static_targets.clone();
        context.target_actuals = entry.target_actuals.clone();
        context
    }
    fn resolve_target(&mut self, value: &Expression, context: &Context) -> Result<Target> {
        self.resolve_target_within(value, context, usize::MAX)
    }
    fn resolve_target_within(
        &mut self,
        value: &Expression,
        context: &Context,
        leaf_limit: usize,
    ) -> Result<Target> {
        enum Task {
            Expression(Expression, Box<Context>, HashSet<usize>),
            Tuple(usize),
        }
        let mut tasks = vec![Task::Expression(
            value.clone(),
            Box::new(context.clone()),
            HashSet::new(),
        )];
        let mut results = vec![];
        let mut leaves = 0usize;
        let mut visited = 0;
        while let Some(task) = tasks.pop() {
            if visited == TARGET_EXPANSION_LIMIT {
                return unsupported(format!(
                    "target expansion exceeds {TARGET_EXPANSION_LIMIT} nodes"
                ));
            }
            visited += 1;
            match task {
                Task::Tuple(count) => {
                    let elements = results.split_off(results.len() - count);
                    results.push(Target::Tuple(elements));
                }
                Task::Expression(value, context, active) => {
                    context.check_nesting()?;
                    let (name, args) = match &value.node {
                        E::Tuple { elements: _ } => {
                            let elements = source_children(&value);
                            let mut child = context.clone();
                            child.depth += 1;
                            tasks.push(Task::Tuple(elements.len()));
                            tasks.extend(elements.into_iter().rev().map(|value| {
                                Task::Expression(value, child.clone(), active.clone())
                            }));
                            continue;
                        }
                        E::Label {
                            name: _,
                            params: _,
                            body: _,
                        } => {
                            let body =
                                source_children(&value).pop().ok_or_else(|| CompileError {
                                    message: "generative UNCHANGED requires state variables".into(),
                                })?;
                            let mut child = context;
                            child.depth += 1;
                            tasks.push(Task::Expression(body, child, active));
                            continue;
                        }
                        E::Let {
                            definitions,
                            body: _,
                        } => {
                            let inner = self.let_context(definitions, &context)?;
                            let body =
                                source_children(&value).pop().ok_or_else(|| CompileError {
                                    message: "generative UNCHANGED requires state variables".into(),
                                })?;
                            tasks.push(Task::Expression(body, Box::new(inner), active));
                            continue;
                        }
                        E::Identifier { name } => {
                            if let Some(binding) = context.binding_ids.get(name) {
                                if let Some((actual, caller, ancestors)) =
                                    context.target_actuals.get(binding)
                                {
                                    tasks.push(Task::Expression(
                                        actual.clone(),
                                        Box::new(caller.as_ref().clone()),
                                        ancestors.clone(),
                                    ));
                                } else if let Some(target) = context.static_targets.get(binding) {
                                    leaves = leaves.saturating_add(target_leaves(target));
                                    if leaves > leaf_limit {
                                        return unsupported("Safety branch exceeds 256 steps");
                                    }
                                    results.push(target.clone());
                                } else if context.locals.get(name).is_some_and(|value| {
                                    matches!(
                                        value,
                                        ir::Expression::Parameter { .. }
                                            | ir::Expression::Capture { .. }
                                    )
                                }) {
                                    leaves = leaves.saturating_add(1);
                                    if leaves > leaf_limit {
                                        return unsupported("Safety branch exceeds 256 steps");
                                    }
                                    results.push(Target::Binding(*binding));
                                } else {
                                    return unsupported(
                                        "generative UNCHANGED requires state variables",
                                    );
                                }
                                continue;
                            }
                            if let Some(slot) = self.slots.get(name) {
                                leaves = leaves.saturating_add(1);
                                if leaves > leaf_limit {
                                    return unsupported("Safety branch exceeds 256 steps");
                                }
                                results.push(Target::Slot(*slot));
                                continue;
                            }
                            (name.clone(), vec![])
                        }
                        E::Apply { operator, args: _ } => (
                            operator.clone(),
                            analysis::analysis_children(analysis::Node::SourceCall(&value))
                                .into_iter()
                                .filter_map(|edge| match (edge.descriptor.role, edge.node) {
                                    ("call-actual", analysis::Node::Source(actual)) => {
                                        Some(actual.clone())
                                    }
                                    _ => None,
                                })
                                .collect(),
                        ),
                        _ => return unsupported("generative UNCHANGED requires state variables"),
                    };
                    let entry =
                        self.scopes[context.scope]
                            .get(&name)
                            .cloned()
                            .ok_or_else(|| CompileError {
                                message: "generative UNCHANGED requires state variables".into(),
                            })?;
                    let position = entry.id;
                    if entry.definition.is_recursive || active.contains(&position) {
                        return unsupported("recursive operator definitions");
                    }
                    let DefinitionKind::Operator { params } = &entry.definition.head else {
                        return unsupported("generative UNCHANGED requires state variables");
                    };
                    if params.len() != args.len()
                        || params.iter().any(|parameter| parameter.arity != 0)
                    {
                        return unsupported(format!("operator {name}"));
                    }
                    let mut inner = self.target_context(&entry);
                    inner.depth = context.depth + 1;
                    for (binding, target) in &context.static_targets {
                        if entry.projection.contains_key(binding) {
                            inner.static_targets.insert(*binding, target.clone());
                        }
                    }
                    for (slot, (parameter, actual)) in params.iter().zip(args).enumerate() {
                        let binding = self.binding_id(position, 0, slot);
                        inner.binding_ids.insert(parameter.name.clone(), binding);
                        inner
                            .locals
                            .insert(parameter.name.clone(), ir::Expression::Parameter { slot });
                        inner
                            .target_actuals
                            .insert(binding, (actual, Rc::new(*context.clone()), active.clone()));
                    }
                    let mut nested_active = active;
                    nested_active.insert(position);
                    tasks.push(Task::Expression(
                        entry.definition.body.clone(),
                        Box::new(inner),
                        nested_active,
                    ));
                }
            }
        }
        results.pop().ok_or_else(|| CompileError {
            message: "generative UNCHANGED requires state variables".into(),
        })
    }
    fn target_bindings(target: &Target, output: &mut Vec<usize>) {
        match target {
            Target::Binding(binding) => {
                if !output.contains(binding) {
                    output.push(*binding);
                }
            }
            Target::Tuple(elements) => {
                for element in elements {
                    Self::target_bindings(element, output);
                }
            }
            Target::Slot(_) => {}
        }
    }
    fn target_json(target: &Target) -> Result<Json> {
        match target {
            Target::Slot(slot) => Ok(json!({"op":"read","slot":slot,"next":false})),
            Target::Tuple(elements) => Ok(
                json!({"op":"tuple","values":elements.iter().map(Self::target_json).collect::<Result<Vec<_>>>()?}),
            ),
            Target::Binding(_) => unsupported("generative UNCHANGED requires state variables"),
        }
    }
    fn requirements(&mut self, name: &str, context: &Context, action: bool) -> Result<Vec<usize>> {
        let position = self.scopes[context.scope][name].id;
        if let Some(result) = self.target_requirements.get(&(position, action)) {
            return Ok(result.clone());
        }
        let (mut result, recursive) = self.requirements_pass(name, context, action, false)?;
        if recursive {
            loop {
                let before = self.target_requirements.clone();
                result = self.requirements_pass(name, context, action, true)?.0;
                if before == self.target_requirements {
                    break;
                }
            }
        }
        Ok(result)
    }
    fn requirements_pass(
        &mut self,
        name: &str,
        context: &Context,
        action: bool,
        refresh: bool,
    ) -> Result<(Vec<usize>, bool)> {
        enum Task {
            Expression(Expression, Context, bool, (usize, bool)),
            Call(
                String,
                Vec<Expression>,
                Context,
                bool,
                Option<(usize, bool)>,
            ),
            Compose(
                (usize, bool),
                Vec<Expression>,
                Context,
                Option<(usize, bool)>,
            ),
            Finish((usize, bool)),
        }
        let mut tasks = vec![Task::Call(
            name.into(),
            vec![],
            context.clone(),
            action,
            None,
        )];
        let mut working: HashMap<(usize, bool), Vec<usize>> = HashMap::new();
        let mut active = HashSet::new();
        let mut visited = HashSet::new();
        let mut recursive = false;
        let mut result = vec![];
        while let Some(task) = tasks.pop() {
            match task {
                Task::Finish(key) => {
                    self.target_requirements
                        .insert(key, working.remove(&key).unwrap_or_default());
                    active.remove(&key);
                }
                Task::Compose(key, args, context, owner) => {
                    let entry = self.scopes[context.scope]
                        .values()
                        .find(|entry| entry.id == key.0)
                        .cloned()
                        .ok_or_else(|| CompileError {
                            message: "lexical capture".into(),
                        })?;
                    let requirements = working
                        .get(&key)
                        .or_else(|| self.target_requirements.get(&key))
                        .cloned()
                        .unwrap_or_default();
                    let mut mapped = vec![];
                    for binding in requirements {
                        let parameter =
                            if let DefinitionKind::Operator { params } = &entry.definition.head {
                                params.iter().enumerate().find_map(|(slot, _)| {
                                    (self.binding_id(key.0, 0, slot) == binding).then_some(slot)
                                })
                            } else {
                                None
                            };
                        if let Some(slot) = parameter {
                            if key.1 && entry.definition.is_recursive {
                                return unsupported(
                                    "recursive operator parameters cannot be primed",
                                );
                            }
                            if let Some(actual) = args.get(slot) {
                                let target = self.resolve_target(actual, &context)?;
                                Self::target_bindings(&target, &mut mapped);
                            } else if owner.is_none() {
                                if !mapped.contains(&binding) {
                                    mapped.push(binding);
                                }
                            } else {
                                return unsupported(format!("operator {}", entry.definition.name));
                            }
                        } else if !mapped.contains(&binding) {
                            mapped.push(binding);
                        }
                    }
                    if let Some(owner) = owner {
                        let output = working.get_mut(&owner).unwrap();
                        for binding in mapped {
                            if !output.contains(&binding) {
                                output.push(binding);
                            }
                        }
                    } else {
                        result = mapped;
                    }
                }
                Task::Call(name, args, context, action, owner) => {
                    let entry =
                        self.scopes[context.scope]
                            .get(&name)
                            .cloned()
                            .ok_or_else(|| CompileError {
                                message: format!("operator {name}"),
                            })?;
                    let key = (entry.id, action);
                    if entry.definition.is_recursive && !action {
                        self.target_requirements.entry(key).or_default();
                        tasks.push(Task::Compose(key, args, context.clone(), owner));
                        continue;
                    }
                    recursive |= entry.definition.is_recursive;
                    if active.contains(&key) {
                        if !entry.definition.is_recursive {
                            return unsupported(
                                "recursive operator definitions require RECURSIVE declarations",
                            );
                        }
                        tasks.push(Task::Compose(key, args, context, owner));
                        continue;
                    }
                    tasks.push(Task::Compose(key, args, context.clone(), owner));
                    if refresh {
                        if !visited.insert(key) {
                            continue;
                        }
                    } else if self.target_requirements.contains_key(&key) {
                        continue;
                    }
                    active.insert(key);
                    working.insert(
                        key,
                        self.target_requirements
                            .get(&key)
                            .cloned()
                            .unwrap_or_default(),
                    );
                    let mut inner = self.target_context(&entry);
                    inner.static_targets.clear();
                    inner.target_actuals.clear();
                    for (name, binding) in &entry.binding_ids {
                        inner
                            .locals
                            .insert(name.clone(), ir::Expression::Capture { slot: *binding });
                    }
                    if let DefinitionKind::Operator { params } = &entry.definition.head {
                        for (slot, parameter) in params.iter().enumerate() {
                            let binding = self.binding_id(key.0, 0, slot);
                            inner.binding_ids.insert(parameter.name.clone(), binding);
                            inner
                                .locals
                                .insert(parameter.name.clone(), ir::Expression::Parameter { slot });
                        }
                    }
                    tasks.push(Task::Finish(key));
                    tasks.push(Task::Expression(
                        definition_body(&entry.definition),
                        inner,
                        action,
                        key,
                    ));
                }
                Task::Expression(value, context, action, owner) => {
                    match &value.node {
                        E::Identifier { name }
                            if self.has(&context, name) && !context.locals.contains_key(name) =>
                        {
                            tasks.push(Task::Call(
                                name.clone(),
                                vec![],
                                context,
                                action,
                                Some(owner),
                            ));
                            continue;
                        }
                        E::Apply { operator, args: _ } if self.has(&context, operator) => {
                            let args =
                                analysis::analysis_children(analysis::Node::SourceCall(&value))
                                    .into_iter()
                                    .filter_map(|edge| match (edge.descriptor.role, edge.node) {
                                        ("call-actual", analysis::Node::Source(actual)) => {
                                            Some(actual.clone())
                                        }
                                        _ => None,
                                    })
                                    .collect::<Vec<_>>();
                            for actual in args.iter().rev() {
                                tasks.push(Task::Expression(
                                    actual.clone(),
                                    context.clone(),
                                    false,
                                    owner,
                                ));
                            }
                            tasks.push(Task::Call(
                                operator.clone(),
                                args,
                                context,
                                action,
                                Some(owner),
                            ));
                            continue;
                        }
                        E::Unchanged { expression: _ }
                        | E::BoxAction {
                            action: _,
                            subscript: _,
                        }
                        | E::AngleAction {
                            action: _,
                            subscript: _,
                        } if action => {
                            for edge in analysis::analysis_children(analysis::Node::Source(&value))
                                .into_iter()
                                .rev()
                            {
                                let analysis::Node::Source(child) = edge.node else {
                                    continue;
                                };
                                match edge.descriptor.role {
                                    "generative-target" | "subscript" => {
                                        let leaf_limit =
                                            if matches!(value.node, E::Unchanged { .. }) {
                                                256
                                            } else {
                                                usize::MAX
                                            };
                                        let target = self
                                            .resolve_target_within(child, &context, leaf_limit)?;
                                        Self::target_bindings(
                                            &target,
                                            working.get_mut(&owner).unwrap(),
                                        );
                                    }
                                    "action-body" => tasks.push(Task::Expression(
                                        child.clone(),
                                        context.clone(),
                                        true,
                                        owner,
                                    )),
                                    _ => {}
                                }
                            }
                            continue;
                        }
                        _ => {}
                    }
                    for (child, inner, descriptor) in self
                        .requirement_children(&value, &context)?
                        .into_iter()
                        .rev()
                    {
                        let child_action = descriptor.action == "start"
                            || action && descriptor.action == "inherit";
                        tasks.push(Task::Expression(child, inner, child_action, owner));
                    }
                }
            }
        }
        Ok((result, recursive))
    }
    fn membership_demands(
        &mut self,
        name: &str,
        context: &Context,
        purpose: bool,
    ) -> Result<Vec<usize>> {
        enum Task {
            Expression(Expression, Context, bool, (usize, bool)),
            Call(
                String,
                Vec<Expression>,
                Context,
                bool,
                Option<(usize, bool)>,
            ),
            Compose(
                (usize, bool),
                Vec<Expression>,
                Context,
                Option<(usize, bool)>,
            ),
            Finish((usize, bool)),
        }
        let mut tasks = vec![Task::Call(
            name.into(),
            vec![],
            context.clone(),
            purpose,
            None,
        )];
        let mut working: HashMap<(usize, bool), Vec<usize>> = HashMap::new();
        let mut active = HashSet::new();
        let mut result = vec![];
        while let Some(task) = tasks.pop() {
            match task {
                Task::Finish(key) => {
                    self.membership_requirements
                        .insert(key, working.remove(&key).unwrap_or_default());
                    active.remove(&key);
                }
                Task::Compose(key, args, context, owner) => {
                    let required = self.membership_requirements[&key].clone();
                    if let Some(owner) = owner {
                        let entry = self.scopes[context.scope]
                            .values()
                            .find(|entry| entry.id == key.0)
                            .cloned()
                            .ok_or_else(|| CompileError {
                                message: "lexical capture".into(),
                            })?;
                        let mut expressions = vec![];
                        for binding in required {
                            let parameter = if let DefinitionKind::Operator { params } =
                                &entry.definition.head
                            {
                                params.iter().enumerate().find_map(|(slot, _)| {
                                    (self.binding_id(key.0, 0, slot) == binding).then_some(slot)
                                })
                            } else {
                                None
                            };
                            if let Some(slot) = parameter {
                                if let Some(actual) = args.get(slot) {
                                    expressions.push(actual.clone());
                                } else {
                                    return unsupported(format!(
                                        "operator {}",
                                        entry.definition.name
                                    ));
                                }
                            } else {
                                let output = working.get_mut(&owner).unwrap();
                                if !output.contains(&binding) {
                                    output.push(binding);
                                }
                            }
                        }
                        tasks.extend(
                            expressions
                                .into_iter()
                                .rev()
                                .map(|value| Task::Expression(value, context.clone(), true, owner)),
                        );
                    } else {
                        result = required;
                    }
                }
                Task::Call(name, args, context, purpose, owner) => {
                    let entry =
                        self.scopes[context.scope]
                            .get(&name)
                            .cloned()
                            .ok_or_else(|| CompileError {
                                message: format!("operator {name}"),
                            })?;
                    let key = (entry.id, purpose);
                    if entry.definition.is_recursive {
                        self.membership_requirements.entry(key).or_default();
                        tasks.push(Task::Compose(key, args, context, owner));
                        continue;
                    }
                    if active.contains(&key) {
                        return unsupported(
                            "recursive operator definitions require RECURSIVE declarations",
                        );
                    }
                    tasks.push(Task::Compose(key, args, context, owner));
                    if self.membership_requirements.contains_key(&key) {
                        continue;
                    }
                    active.insert(key);
                    working.insert(key, vec![]);
                    let mut inner = self.target_context(&entry);
                    for (name, binding) in &entry.binding_ids {
                        inner
                            .locals
                            .insert(name.clone(), ir::Expression::Capture { slot: *binding });
                    }
                    if let DefinitionKind::Operator { params } = &entry.definition.head {
                        for (slot, parameter) in params.iter().enumerate() {
                            let binding = self.binding_id(key.0, 0, slot);
                            inner.binding_ids.insert(parameter.name.clone(), binding);
                            inner
                                .locals
                                .insert(parameter.name.clone(), ir::Expression::Parameter { slot });
                        }
                    }
                    tasks.push(Task::Finish(key));
                    tasks.push(Task::Expression(
                        definition_body(&entry.definition),
                        inner,
                        purpose,
                        key,
                    ));
                }
                Task::Expression(value, context, purpose, owner) => {
                    match &value.node {
                        E::Identifier { name } => {
                            if purpose
                                && let Some(binding) = context.binding_ids.get(name)
                                && context.locals.get(name).is_some_and(|value| {
                                    matches!(
                                        value,
                                        ir::Expression::Parameter { .. }
                                            | ir::Expression::Capture { .. }
                                    )
                                })
                            {
                                let output = working.get_mut(&owner).unwrap();
                                if !output.contains(binding) {
                                    output.push(*binding);
                                }
                            }
                            if self.has(&context, name) && !context.locals.contains_key(name) {
                                tasks.push(Task::Call(
                                    name.clone(),
                                    vec![],
                                    context,
                                    purpose,
                                    Some(owner),
                                ));
                            }
                            continue;
                        }
                        E::Apply { operator, args: _ } if self.has(&context, operator) => {
                            let args =
                                analysis::analysis_children(analysis::Node::SourceCall(&value))
                                    .into_iter()
                                    .filter_map(|edge| match (edge.descriptor.role, edge.node) {
                                        ("call-actual", analysis::Node::Source(actual)) => {
                                            Some(actual.clone())
                                        }
                                        _ => None,
                                    })
                                    .collect::<Vec<_>>();
                            for actual in args.iter().rev() {
                                tasks.push(Task::Expression(
                                    actual.clone(),
                                    context.clone(),
                                    false,
                                    owner,
                                ));
                            }
                            tasks.push(Task::Call(
                                operator.clone(),
                                args,
                                context,
                                purpose,
                                Some(owner),
                            ));
                            continue;
                        }
                        _ => {}
                    }
                    for (child, inner, descriptor) in self
                        .requirement_children(&value, &context)?
                        .into_iter()
                        .rev()
                    {
                        let child_purpose = descriptor.membership == "start"
                            || purpose && descriptor.membership == "inherit";
                        tasks.push(Task::Expression(child, inner, child_purpose, owner));
                    }
                }
            }
        }
        Ok(result)
    }
    fn requirement_children(
        &mut self,
        value: &Expression,
        context: &Context,
    ) -> Result<Vec<(Expression, Context, analysis::Descriptor)>> {
        let scoped = match &value.node {
            E::Let {
                definitions,
                body: _,
            } => Some(self.let_context(definitions, context)?),
            E::Forall { bounds, body: _ }
            | E::Exists { bounds, body: _ }
            | E::FunctionConstruction { bounds, body: _ }
            | E::SetMap {
                bounds,
                expression: _,
            } => Some(self.requirement_bind(bounds, context)),
            E::SetFilter {
                bound,
                predicate: _,
            } => Some(self.requirement_bind(std::slice::from_ref(bound), context)),
            E::Choose {
                pattern,
                set: Some(set),
                body: _,
            } => Some(self.requirement_bind(
                &[ast::Bound {
                    pattern: pattern.clone(),
                    set: *set.clone(),
                }],
                context,
            )),
            _ => None,
        };
        Ok(analysis::analysis_children(analysis::Node::Source(value))
            .into_iter()
            .filter_map(|edge| {
                let analysis::Node::Source(child) = edge.node else {
                    return None;
                };
                let inner =
                    if edge.descriptor.scope == "binder" || matches!(value.node, E::Let { .. }) {
                        scoped.as_ref().unwrap_or(context)
                    } else {
                        context
                    };
                Some((child.clone(), inner.clone(), edge.descriptor))
            })
            .collect())
    }
    fn requirement_bind(&mut self, bounds: &[ast::Bound], context: &Context) -> Context {
        let mut inner = context.clone();
        for bound in bounds {
            let names = match &bound.pattern {
                Pattern::Name { name } => vec![name],
                Pattern::Tuple { names } => names.iter().collect(),
            };
            for (slot, name) in names.iter().enumerate() {
                let binding =
                    self.named_binding_at(context.origin, bound.set.location.start, 1, slot, name);
                inner.binding_ids.insert((*name).clone(), binding);
                inner
                    .locals
                    .insert((*name).clone(), ir::Expression::Bound { slot: 0 });
            }
        }
        inner
    }

use crate::analysis::{Node, analysis_children};
use crate::unsupported;
use crate::{CompileError, Compiler, Context, E, Expression, Phase, Result, Target, typed};
use rtla::ast::{self, ConfigValue, DefinitionKind, Pattern};
use rtlc::ir::{self, Domain, Expression as I, Scalar};
use std::collections::BTreeMap;
fn boolean(value: bool) -> I {
    I::Literal {
        value: Scalar::Bool(value),
    }
}
fn integer(value: i64) -> Result<I> {
    Ok(I::Literal {
        value: Scalar::Int(i32::try_from(value).map_err(|_| CompileError {
            message: "integer outside signed 32 bits".into(),
        })?),
    })
}
fn string(value: &str) -> I {
    I::Data {
        value: rtlc::Value::String(value.into()),
    }
}
fn literal(value: &ConfigValue) -> Result<I> {
    Ok(match value {
        ConfigValue::Number { value } => integer(*value)?,
        ConfigValue::Boolean { value } => boolean(*value),
        ConfigValue::String { value } => string(value),
        ConfigValue::Set { elements } => I::Set {
            values: elements.iter().map(literal).collect::<Result<_>>()?,
        },
        ConfigValue::ModelValue { name } => I::Data {
            value: rtlc::Value::ModelValue(name.clone()),
        },
    })
}
fn not(argument: I) -> I {
    I::Not {
        argument: Box::new(argument),
    }
}
fn unmatched(value: &Expression) -> I {
    I::UnmatchedCase {
        location: format!(
            "line {}, column {}",
            value.location.line, value.location.column
        ),
    }
}
impl Compiler<'_> {
    pub(super) fn expression_ir(&mut self, value: &Expression, context: &Context) -> Result<I> {
        let child = context.nested()?;
        Ok(match &value.node {
            E::Number { value } => integer(i64::try_from(*value).map_err(|_| CompileError {
                message: "integer outside signed 32 bits".into(),
            })?)?,
            E::String { value } => {
                if value.chars().any(|character| character as u32 > 255) {
                    return unsupported("TLC 1.7.4 string literal outside byte range");
                }
                string(value)
            }
            E::Identifier { name } => {
                if let Some(local) = context.locals.get(name) {
                    return Ok(local.clone());
                }
                if let Some(constant) = self.constants.get(name) {
                    return literal(constant);
                }
                if name == "TRUE" || name == "FALSE" {
                    return Ok(boolean(name == "TRUE"));
                }
                if name == "BOOLEAN" {
                    return Ok(I::Set {
                        values: vec![boolean(false), boolean(true)],
                    });
                }
                if let Some(slot) = self.slots.get(name) {
                    if context.phase == Phase::Constant {
                        return unsupported("variable in constant expression");
                    }
                    return Ok(I::Read {
                        slot: *slot,
                        next: context.phase == Phase::Initial,
                    });
                }
                self.shared_purpose_ir(name, &[], context, false)?
            }
            E::Let { definitions, body } => {
                let expanded = self.let_context(definitions, context)?;
                self.expression_ir(body, &expanded)?
            }
            E::Label { body, .. } => self.expression_ir(body, &child)?,
            E::Prime { expression } if context.phase == Phase::Next => {
                let inner = self.expression_ir(expression, &child)?;
                if let I::Read { slot, next: false } = inner {
                    I::Read { slot, next: true }
                } else {
                    self.prime_ir(inner)?
                }
            }
            E::Unchanged { expression } if context.phase == Phase::Next => {
                let inner = self.expression_ir(expression, &child)?;
                I::Eq {
                    left: Box::new(inner.clone()),
                    right: Box::new(self.prime_ir(inner)?),
                }
            }
            E::Enabled { expression } => I::Enabled {
                branches: self.action_ir(
                    expression,
                    &Context {
                        phase: Phase::Next,
                        ..child
                    },
                    "ENABLED",
                )?,
                subscript: None,
            },
            E::ExceptAt => context.locals.get("@").cloned().unwrap_or(I::Old),
            E::SetEnumeration { elements } | E::Tuple { elements } => {
                let values = self.expressions_ir(elements, &child)?;
                if matches!(value.node, E::Tuple { .. }) {
                    I::Tuple { values }
                } else {
                    I::Set { values }
                }
            }
            E::Record { fields } | E::RecordSet { fields } => {
                let fields = fields
                    .iter()
                    .map(|field| {
                        Ok((
                            field.name.clone(),
                            self.expression_ir(&field.value, &child)?,
                        ))
                    })
                    .collect::<Result<_>>()?;
                if matches!(value.node, E::Record { .. }) {
                    I::Record { fields }
                } else {
                    I::RecordSet { fields }
                }
            }
            E::FunctionSet { domain, range } => I::FunctionSet {
                left: Box::new(self.expression_ir(domain, &child)?),
                right: Box::new(self.expression_ir(range, &child)?),
            },
            E::FunctionApplication { function, args } => {
                let key = self.key_ir(args, &child)?;
                I::At {
                    target: Box::new(self.expression_ir(function, &child)?),
                    key: Box::new(key),
                }
            }
            E::FieldAccess { record, field } => I::At {
                target: Box::new(self.expression_ir(record, &child)?),
                key: Box::new(string(field)),
            },
            E::Except { function, updates } => {
                let mut lowered = vec![];
                for update in updates {
                    let mut path = vec![];
                    for part in &update.path {
                        path.push(match part {
                            ast::ExceptPath::Field { name } => string(name),
                            ast::ExceptPath::Index { args } => self.key_ir(args, &child)?,
                        });
                    }
                    let mut old = child.clone();
                    old.locals.insert("@".into(), I::Old);
                    old.order.retain(|name| name != "@");
                    old.order.push("@".into());
                    let binding =
                        self.binding_at(context.origin, update.value.location.start, 2, 0);
                    old.binding_ids.insert("@".into(), binding);
                    old.projection.insert(binding, I::Old);
                    lowered.push(ir::Update {
                        path,
                        value: self.expression_ir(&update.value, &old)?,
                    });
                }
                I::Update {
                    target: Box::new(self.expression_ir(function, &child)?),
                    updates: lowered,
                }
            }
            E::Forall { bounds, body }
            | E::Exists { bounds, body }
            | E::FunctionConstruction { bounds, body } => {
                let (bounds, bound) = self.bind_ir(bounds, &child)?;
                let body = Box::new(self.expression_ir(body, &bound)?);
                match value.node {
                    E::Forall { .. } => I::Forall { bounds, body },
                    E::Exists { .. } => I::Exists { bounds, body },
                    _ => I::Function { bounds, body },
                }
            }
            E::SetMap { bounds, expression } => {
                let (bounds, bound) = self.bind_ir(bounds, &child)?;
                I::MapSet {
                    bounds,
                    body: Box::new(self.expression_ir(expression, &bound)?),
                }
            }
            E::SetFilter { bound, predicate } => {
                let (bounds, bound) = self.bind_ir(std::slice::from_ref(bound), &child)?;
                I::Filter {
                    bounds,
                    body: Box::new(self.expression_ir(predicate, &bound)?),
                }
            }
            E::Choose {
                pattern,
                set: Some(set),
                body,
            } => {
                let (mut bounds, bound) = self.bind_ir(
                    &[ast::Bound {
                        pattern: pattern.clone(),
                        set: *set.clone(),
                    }],
                    &child,
                )?;
                I::Choose {
                    binding: bounds.remove(0),
                    body: Box::new(self.expression_ir(body, &bound)?),
                }
            }
            E::If {
                condition,
                consequent,
                alternative,
            } => I::If {
                condition: Box::new(self.expression_ir(condition, &child)?),
                consequent: Box::new(self.expression_ir(consequent, &child)?),
                alternative: Box::new(self.expression_ir(alternative, &child)?),
            },
            E::Case { arms, other } => {
                let mut result = if let Some(other) = other {
                    self.expression_ir(other, &child)?
                } else if !arms.is_empty() {
                    unmatched(value)
                } else {
                    return unsupported("empty CASE");
                };
                for arm in arms.iter().rev() {
                    result = I::If {
                        condition: Box::new(self.expression_ir(&arm.condition, &child)?),
                        consequent: Box::new(self.expression_ir(&arm.body, &child)?),
                        alternative: Box::new(result),
                    };
                }
                result
            }
            E::And { operands, .. } | E::Or { operands, .. } => {
                let and = matches!(value.node, E::And { .. });
                let mut operands = operands.iter();
                let mut result = if let Some(first) = operands.next() {
                    self.expression_ir(first, &child)?
                } else {
                    boolean(and)
                };
                for operand in operands {
                    let left = Box::new(result);
                    let right = Box::new(self.expression_ir(operand, &child)?);
                    result = if and {
                        I::And { left, right }
                    } else {
                        I::Or { left, right }
                    };
                }
                result
            }
            E::BoxAction { action, subscript } | E::AngleAction { action, subscript } => {
                let boxed = matches!(value.node, E::BoxAction { .. });
                let subscript = self.expression_ir(subscript, &child)?;
                let unchanged = I::Eq {
                    left: Box::new(subscript.clone()),
                    right: Box::new(self.prime_ir(subscript)?),
                };
                let left = Box::new(self.expression_ir(action, &child)?);
                if boxed {
                    I::Or {
                        left,
                        right: Box::new(unchanged),
                    }
                } else {
                    I::And {
                        left,
                        right: Box::new(not(unchanged)),
                    }
                }
            }
            E::Apply { operator, args } => self.apply_ir(operator, args, context, &child)?,
            _ => {
                return unsupported(format!(
                    "expression at {}:{}",
                    value.location.line, value.location.column
                ));
            }
        })
    }
    fn expressions_ir(&mut self, values: &[Expression], context: &Context) -> Result<Vec<I>> {
        values
            .iter()
            .map(|value| self.expression_ir(value, context))
            .collect()
    }
    fn key_ir(&mut self, args: &[Expression], context: &Context) -> Result<I> {
        if args.len() == 1 {
            self.expression_ir(&args[0], context)
        } else {
            Ok(I::Tuple {
                values: self.expressions_ir(args, context)?,
            })
        }
    }
    pub(super) fn prime_ir(&mut self, value: I) -> Result<I> {
        self.lower_pending()?;
        if typed::level_summary(Node::Expression(&value), &self.level_cache.borrow()).base > 1 {
            return unsupported("prime of an action expression");
        }
        Ok(I::Prime {
            argument: Box::new(value),
        })
    }
    pub(super) fn shared_ir(
        &mut self,
        name: &str,
        args: &[Expression],
        context: &Context,
    ) -> Result<I> {
        self.shared_purpose_ir(name, args, context, false)
    }
    fn shared_purpose_ir(
        &mut self,
        name: &str,
        args: &[Expression],
        context: &Context,
        membership: bool,
    ) -> Result<I> {
        let child = context.nested()?;
        let demanded = self.membership_demands(name, context, membership)?;
        let position = self.scopes[context.scope][name].id;
        let arguments = args
            .iter()
            .enumerate()
            .map(|(slot, argument)| {
                if membership || demanded.contains(&self.binding_id(position, 0, slot)) {
                    self.membership_ir(argument, &child)
                } else {
                    self.expression_ir(argument, &child)
                }
            })
            .collect::<Result<_>>()?;
        let targets = self.call_targets(name, args, context)?;
        self.shared_arguments_ir(name, arguments, context, membership, targets)
    }
    pub(super) fn bind_ir(
        &mut self,
        bounds: &[ast::Bound],
        context: &Context,
    ) -> Result<(Vec<ir::Binding>, Context)> {
        let mut child = context.clone();
        let mut bindings = vec![];
        for bound in bounds {
            if child.bound >= 40 {
                return unsupported("more than 40 bound variables");
            }
            let slot = child.bound;
            let mut binding = ir::Binding {
                slot,
                tuple_size: None,
                domain: self.domain_ir(&bound.set, context, true)?,
            };
            let names = match &bound.pattern {
                Pattern::Name { name } => vec![name],
                Pattern::Tuple { names } => {
                    binding.tuple_size = Some(names.len());
                    names.iter().collect()
                }
            };
            for (index, name) in names.iter().enumerate() {
                child.order.retain(|item| item != *name);
                child.order.push((*name).clone());
                let binding_id =
                    self.named_binding_at(context.origin, bound.set.location.start, 1, index, name);
                child.binding_ids.insert((*name).clone(), binding_id);
                let value = if matches!(bound.pattern, Pattern::Tuple { .. }) {
                    I::At {
                        target: Box::new(I::Bound { slot }),
                        key: Box::new(integer(index as i64 + 1)?),
                    }
                } else {
                    I::Bound { slot }
                };
                child.projection.insert(binding_id, value.clone());
                child.locals.insert((*name).clone(), value);
            }
            child = child.nested()?;
            child.bound = slot + 1;
            bindings.push(binding);
        }
        Ok((bindings, child))
    }
    pub(super) fn domain_ir(
        &mut self,
        value: &Expression,
        context: &Context,
        choice: bool,
    ) -> Result<Domain> {
        Ok(match &value.node {
            E::SetEnumeration { elements } => Domain::Set {
                values: self.expressions_ir(elements, &context.nested()?)?,
            },
            E::Apply { operator, args } if operator == ".." && args.len() == 2 => {
                if !self.arithmetic() {
                    return unsupported("range requires Naturals");
                }
                let child = context.nested()?;
                Domain::Range {
                    lower: Box::new(self.expression_ir(&args[0], &child)?),
                    upper: Box::new(self.expression_ir(&args[1], &child)?),
                }
            }
            E::Identifier { name } if name == "BOOLEAN" => Domain::Set {
                values: vec![boolean(false), boolean(true)],
            },
            E::Identifier { name } if name == "Nat" || name == "Int" => {
                if choice || !self.arithmetic() || name == "Int" && !self.extends("Integers") {
                    return unsupported("infinite enumeration");
                }
                Domain::Range {
                    lower: Box::new(integer(if name == "Nat" { 0 } else { i32::MIN as i64 })?),
                    upper: Box::new(integer(i32::MAX as i64)?),
                }
            }
            E::Identifier { name }
                if self.has(context, name) && !context.locals.contains_key(name) =>
            {
                Domain::Value {
                    value: Box::new(self.shared_ir(name, &[], context)?),
                }
            }
            _ => Domain::Value {
                value: Box::new(self.expression_ir(value, context)?),
            },
        })
    }
    pub(super) fn membership_ir(&mut self, value: &Expression, context: &Context) -> Result<I> {
        let child = context.nested()?;
        Ok(match &value.node {
            E::Let { definitions, body } => {
                let inner = self.let_context(definitions, context)?;
                self.membership_ir(body, &inner)?
            }
            E::Label { body, .. } => self.membership_ir(body, &child)?,
            E::If {
                condition,
                consequent,
                alternative,
            } => I::If {
                condition: Box::new(self.expression_ir(condition, &child)?),
                consequent: Box::new(self.membership_ir(consequent, &child)?),
                alternative: Box::new(self.membership_ir(alternative, &child)?),
            },
            E::Case { arms, other } if !arms.is_empty() => {
                let mut result = if let Some(other) = other {
                    self.membership_ir(other, &child)?
                } else {
                    unmatched(value)
                };
                for arm in arms.iter().rev() {
                    result = I::If {
                        condition: Box::new(self.expression_ir(&arm.condition, &child)?),
                        consequent: Box::new(self.membership_ir(&arm.body, &child)?),
                        alternative: Box::new(result),
                    };
                }
                result
            }
            E::Identifier { name } if name == "Nat" || name == "Int" => {
                if !self.arithmetic() || name == "Int" && !self.extends("Integers") {
                    return unsupported("infinite enumeration");
                }
                I::MapSet {
                    bounds: vec![ir::Binding {
                        slot: context.bound,
                        tuple_size: None,
                        domain: Domain::Range {
                            lower: Box::new(integer(if name == "Nat" {
                                0
                            } else {
                                i32::MIN as i64
                            })?),
                            upper: Box::new(integer(i32::MAX as i64)?),
                        },
                    }],
                    body: Box::new(I::Bound {
                        slot: context.bound,
                    }),
                }
            }
            E::Identifier { name }
                if self.has(context, name) && !context.locals.contains_key(name) =>
            {
                self.shared_purpose_ir(name, &[], context, true)?
            }
            E::Apply { operator, args } if self.has(context, operator) => {
                self.shared_purpose_ir(operator, args, context, true)?
            }
            E::Apply { operator, args }
                if operator == "Seq" && args.len() == 1 && self.extends("Sequences") =>
            {
                I::SequenceSet {
                    argument: Box::new(self.membership_ir(&args[0], &child)?),
                }
            }
            E::FunctionSet { domain, range } => I::FunctionSet {
                left: Box::new(self.expression_ir(domain, &child)?),
                right: Box::new(self.membership_ir(range, &child)?),
            },
            E::RecordSet { fields } => I::RecordSet {
                fields: fields
                    .iter()
                    .map(|field| {
                        Ok((
                            field.name.clone(),
                            self.membership_ir(&field.value, &child)?,
                        ))
                    })
                    .collect::<Result<_>>()?,
            },
            _ => self.expression_ir(value, context)?,
        })
    }
    fn membership_test_ir(&mut self, left: I, value: &Expression, context: &Context) -> Result<I> {
        if match &value.node {
            E::Identifier { name } => self.has(context, name) || context.locals.contains_key(name),
            E::Apply { operator, .. } => self.has(context, operator),
            _ => false,
        } {
            return Ok(I::FunctionIn {
                left: Box::new(left),
                right: Box::new(self.membership_ir(value, context)?),
            });
        }
        Ok(match &value.node {
            E::Apply { operator, args }
                if operator == "Seq" && args.len() == 1 && self.extends("Sequences") =>
            {
                I::SequenceIn {
                    left: Box::new(left),
                    right: Box::new(self.membership_ir(&args[0], &context.nested()?)?),
                }
            }
            E::RecordSet { .. } | E::FunctionSet { .. } => I::FunctionIn {
                left: Box::new(left),
                right: Box::new(self.membership_ir(value, &context.nested()?)?),
            },
            E::Apply { operator, args } if operator == "SUBSET" && args.len() == 1 => {
                I::FunctionIn {
                    left: Box::new(left),
                    right: Box::new(I::Powerset {
                        argument: Box::new(self.expression_ir(&args[0], context)?),
                    }),
                }
            }
            _ => I::In {
                value: Box::new(left),
                domain: self.domain_ir(value, context, false)?,
            },
        })
    }
    fn fold_ir(
        &mut self,
        sequence: bool,
        args: &[Expression],
        context: &Context,
        child: &Context,
    ) -> Result<I> {
        let E::Identifier { name } = &args[0].node else {
            return unsupported("fold operator argument");
        };
        if context.locals.contains_key(name) {
            return unsupported(format!("fold operator {name}"));
        }
        let entry = self.scopes[context.scope]
            .get(name)
            .cloned()
            .ok_or_else(|| CompileError {
                message: format!("operator {name}"),
            })?;
        if !entry.definition.is_recursive && context.call_ids.contains(&entry.id) {
            return unsupported(format!("fold operator {name}"));
        }
        let DefinitionKind::Operator { params } = &entry.definition.head else {
            return unsupported(format!("fold operator {name}"));
        };
        if params.len() != 2 || params.iter().any(|param| param.arity != 0) {
            return unsupported(format!("fold operator {name}"));
        }
        let accumulator = context.bound;
        if accumulator + 2 > 40 {
            return unsupported("more than 40 bound variables");
        }
        let initial = Box::new(self.expression_ir(&args[1], child)?);
        let collection = Box::new(self.expression_ir(&args[2], child)?);
        let body = Box::new(self.shared_arguments_ir(
            name,
            vec![
                I::Bound { slot: accumulator },
                I::Bound {
                    slot: accumulator + 1,
                },
            ],
            context,
            false,
            BTreeMap::new(),
        )?);
        Ok(I::Fold {
            accumulator,
            initial,
            collection,
            body,
            order: if sequence {
                ir::FoldOrder::SequenceLeft
            } else {
                ir::FoldOrder::SetMembers
            },
        })
    }
    fn apply_ir(
        &mut self,
        operator: &str,
        args: &[Expression],
        context: &Context,
        child: &Context,
    ) -> Result<I> {
        if self.has(context, operator) {
            return self.shared_ir(operator, args, context);
        }
        if (operator == "SelectSeq" && self.extends("Sequences"))
            || (operator == "SortSeq" && self.extends("TLC"))
        {
            if args.len() != 2 {
                return unsupported(format!("operator arity {operator}"));
            }
            let arity = if operator == "SortSeq" { 2 } else { 1 };
            let E::Identifier { name } = &args[1].node else {
                return unsupported("callback operator argument");
            };
            if context.locals.contains_key(name) || context.bound + arity > 40 {
                return unsupported(format!("callback operator {name}"));
            }
            let body = Box::new(
                self.shared_arguments_ir(
                    name,
                    (0..arity)
                        .map(|index| I::Bound {
                            slot: context.bound + index,
                        })
                        .collect(),
                    context,
                    false,
                    BTreeMap::new(),
                )?,
            );
            let sequence = Box::new(self.expression_ir(&args[0], child)?);
            return Ok(if arity == 1 {
                I::SelectSeq {
                    slot: context.bound,
                    sequence,
                    body,
                }
            } else {
                I::SortSeq {
                    slot: context.bound,
                    sequence,
                    body,
                }
            });
        }
        if operator == "Assert" && self.extends("TLC") {
            if args.len() != 2 {
                return unsupported("operator arity Assert");
            }
            return Ok(I::Assert {
                condition: Box::new(self.expression_ir(&args[0], child)?),
                message: Box::new(self.expression_ir(&args[1], child)?),
            });
        }
        if self.extends("Apalache") && ["ApaFoldSet", "ApaFoldSeqLeft"].contains(&operator) {
            if args.len() != 3 {
                return unsupported("fold arity");
            }
            return self.fold_ir(operator == "ApaFoldSeqLeft", args, context, child);
        }
        if self.extends("Variants") {
            match operator {
                "Variant" if args.len() == 2 => {
                    if context.bound >= 256 {
                        return unsupported("too many bound variables");
                    }
                    let tag = self.expression_ir(&args[0], child)?;
                    let payload = self.expression_ir(
                        &args[1],
                        &Context {
                            bound: context.bound + 1,
                            ..child.clone()
                        },
                    )?;
                    return Ok(I::Function {
                        bounds: vec![ir::Binding {
                            slot: context.bound,
                            tuple_size: None,
                            domain: Domain::Set { values: vec![tag] },
                        }],
                        body: Box::new(payload),
                    });
                }
                "VariantTag" if args.len() == 1 => {
                    return Ok(I::VariantTag {
                        argument: Box::new(self.expression_ir(&args[0], child)?),
                    });
                }
                "VariantGetUnsafe" if args.len() == 2 => {
                    return Ok(I::At {
                        target: Box::new(self.expression_ir(&args[1], child)?),
                        key: Box::new(self.expression_ir(&args[0], child)?),
                    });
                }
                _ => {}
            }
        }
        if args.len() == 1 && ["-.", "-"].contains(&operator) {
            if !self.extends("Integers") {
                return unsupported("unary minus requires Integers");
            }
            if matches!(args[0].node, E::Number { value: 2147483648 }) {
                return integer(i32::MIN as i64);
            }
        }
        if args.len() == 1 && ["~", "\\lnot", "-.", "-"].contains(&operator) {
            let argument = Box::new(self.expression_ir(&args[0], child)?);
            return Ok(if ["~", "\\lnot"].contains(&operator) {
                I::Not { argument }
            } else {
                I::Neg { argument }
            });
        }
        if args.len() == 1
            && [
                "DOMAIN",
                "Cardinality",
                "Len",
                "Head",
                "Tail",
                "SUBSET",
                "UNION",
            ]
            .contains(&operator)
        {
            if ["Len", "Head", "Tail"].contains(&operator) && !self.extends("Sequences") {
                return unsupported("sequence operator requires Sequences");
            }
            if operator == "Cardinality" && !self.extends("FiniteSets") {
                return unsupported("Cardinality requires FiniteSets");
            }
            let argument = Box::new(self.expression_ir(&args[0], child)?);
            return Ok(match operator {
                "DOMAIN" => I::Domain { argument },
                "Cardinality" => I::Cardinality { argument },
                "Len" => I::Len { argument },
                "Head" => I::Head { argument },
                "Tail" => I::Tail { argument },
                "SUBSET" => I::Powerset { argument },
                "UNION" => I::Union { argument },
                _ => unreachable!(),
            });
        }
        if args.len() == 2 && ["\\in", "\\notin"].contains(&operator) {
            let left = self.expression_ir(&args[0], child)?;
            let membership = self.membership_test_ir(left, &args[1], child)?;
            return Ok(if operator == "\\notin" {
                not(membership)
            } else {
                membership
            });
        }
        if operator == "<=>" && args.len() == 2 {
            return Ok(I::Eq {
                left: Box::new(not(self.expression_ir(&args[0], child)?)),
                right: Box::new(not(self.expression_ir(&args[1], child)?)),
            });
        }
        if operator == ".." && args.len() == 2 {
            let value = Expression {
                node: E::Apply {
                    operator: operator.into(),
                    args: args.to_vec(),
                },
                location: args[0].location,
            };
            return Ok(I::MapSet {
                bounds: vec![ir::Binding {
                    slot: context.bound,
                    tuple_size: None,
                    domain: self.domain_ir(&value, child, true)?,
                }],
                body: Box::new(I::Bound {
                    slot: context.bound,
                }),
            });
        }
        if operator == "Append" && args.len() == 2 && self.extends("Sequences") {
            return Ok(I::Append {
                left: Box::new(self.expression_ir(&args[0], child)?),
                right: Box::new(self.expression_ir(&args[1], child)?),
            });
        }
        if operator == "SubSeq" && args.len() == 3 && self.extends("Sequences") {
            return Ok(I::Subseq {
                sequence: Box::new(self.expression_ir(&args[0], child)?),
                from: Box::new(self.expression_ir(&args[1], child)?),
                to: Box::new(self.expression_ir(&args[2], child)?),
            });
        }
        let op = match operator {
            "+" => "add",
            "-" => "sub",
            "*" => "mul",
            "\\div" => "div",
            "%" => "mod",
            "^" => "pow",
            "=" => "eq",
            ":=" if self.extends("Apalache") => "eq",
            "#" | "/=" => "ne",
            "<" => "lt",
            "<=" | "\\leq" => "le",
            ">" => "gt",
            ">=" | "\\geq" => "ge",
            "=>" => "implies",
            "\\cup" | "\\union" => "cup",
            "\\cap" | "\\intersect" => "cap",
            "\\" => "difference",
            "\\subseteq" => "subset-eq",
            "\\o" => "concat",
            _ => return unsupported(format!("operator {operator}")),
        };
        if args.len() != 2 {
            return unsupported(format!("operator arity {operator}"));
        }
        if [
            "add", "sub", "mul", "div", "mod", "pow", "lt", "le", "gt", "ge",
        ]
        .contains(&op)
            && !self.arithmetic()
        {
            return unsupported("arithmetic requires Naturals");
        }
        if op == "concat" && !self.extends("Sequences") {
            return unsupported("concatenation requires Sequences");
        }
        let left = Box::new(self.expression_ir(&args[0], child)?);
        let right = Box::new(self.expression_ir(&args[1], child)?);
        Ok(match op {
            "add" => I::Add { left, right },
            "sub" => I::Sub { left, right },
            "mul" => I::Mul { left, right },
            "div" => I::Div { left, right },
            "mod" => I::Mod { left, right },
            "pow" => I::Pow { left, right },
            "eq" => I::Eq { left, right },
            "ne" => I::Ne { left, right },
            "lt" => I::Lt { left, right },
            "le" => I::Le { left, right },
            "gt" => I::Gt { left, right },
            "ge" => I::Ge { left, right },
            "implies" => I::Implies { left, right },
            "cup" => I::Cup { left, right },
            "cap" => I::Cap { left, right },
            "difference" => I::Difference { left, right },
            "subset-eq" => I::SubsetEq { left, right },
            "concat" => I::Concat { left, right },
            _ => unreachable!(),
        })
    }
    pub(super) fn target_ir(target: &Target) -> Result<I> {
        Ok(match target {
            Target::Slot(slot) => I::Read {
                slot: *slot,
                next: false,
            },
            Target::Tuple(values) => I::Tuple {
                values: values.iter().map(Self::target_ir).collect::<Result<_>>()?,
            },
            Target::Binding(_) => {
                return unsupported("generative UNCHANGED requires state variables");
            }
        })
    }
    pub(super) fn variable_reads_ir(
        &mut self,
        value: I,
        message: &str,
        depth: usize,
    ) -> Result<Vec<I>> {
        if self.target_nesting >= 40 {
            return unsupported("expression or operator nesting exceeds 40");
        }
        self.target_nesting += 1;
        self.lower_pending()?;
        struct Frame {
            definition: Option<usize>,
            arguments: Vec<I>,
            captures: Vec<I>,
            parent: Option<usize>,
            depth: usize,
        }
        let mut frames: Vec<Frame> = vec![];
        let mut pending: Vec<(I, Option<usize>, usize)> = vec![(value, None, depth)];
        let mut reads = vec![];
        let mut visited = 0;
        while let Some((value, frame, depth)) = pending.pop() {
            if visited == crate::TARGET_EXPANSION_LIMIT {
                return unsupported(format!(
                    "target expansion exceeds {} nodes",
                    crate::TARGET_EXPANSION_LIMIT
                ));
            }
            visited += 1;
            if depth >= 40 {
                return unsupported("expression or operator nesting exceeds 40");
            }
            let children = analysis_children(Node::Expression(&value));
            match &value {
                I::Tuple { .. } => pending.extend(children.into_iter().rev().filter_map(|edge| {
                    if let Node::Expression(value) = edge.node {
                        Some((value.clone(), frame, depth + 1))
                    } else {
                        None
                    }
                })),
                I::Read { next: false, .. } => reads.push(value),
                I::Call { definition, .. } => {
                    let mut ancestor = frame;
                    while let Some(index) = ancestor {
                        if frames[index].definition == Some(*definition) {
                            return unsupported("recursive operator definitions");
                        }
                        ancestor = frames[index].parent;
                    }
                    self.lower_definition(*definition)?;
                    let next = frames.len();
                    frames.push(Frame {
                        definition: Some(*definition),
                        arguments: children
                            .iter()
                            .filter(|edge| edge.descriptor.role == "call-actual")
                            .filter_map(|edge| {
                                if let Node::Expression(value) = edge.node {
                                    Some(value.clone())
                                } else {
                                    None
                                }
                            })
                            .collect(),
                        captures: children
                            .iter()
                            .filter(|edge| edge.descriptor.role == "call-capture")
                            .filter_map(|edge| {
                                if let Node::Expression(value) = edge.node {
                                    Some(value.clone())
                                } else {
                                    None
                                }
                            })
                            .collect(),
                        parent: frame,
                        depth,
                    });
                    let ir::DefinitionBody::Expression(body) =
                        &self.shared[*definition].definition.as_ref().unwrap().body
                    else {
                        return unsupported("generative UNCHANGED requires state variables");
                    };
                    pending.push((body.clone(), Some(next), depth + 1));
                }
                I::Frame { .. } => {
                    let next = frames.len();
                    frames.push(Frame {
                        definition: None,
                        arguments: children
                            .iter()
                            .filter(|edge| edge.descriptor.role == "frame-actual")
                            .filter_map(|edge| {
                                if let Node::Expression(value) = edge.node {
                                    Some(value.clone())
                                } else {
                                    None
                                }
                            })
                            .collect(),
                        captures: children
                            .iter()
                            .filter(|edge| edge.descriptor.role == "frame-capture")
                            .filter_map(|edge| {
                                if let Node::Expression(value) = edge.node {
                                    Some(value.clone())
                                } else {
                                    None
                                }
                            })
                            .collect(),
                        parent: frame,
                        depth,
                    });
                    for edge in children
                        .into_iter()
                        .filter(|edge| edge.descriptor.role == "frame-body")
                    {
                        if let Node::Expression(value) = edge.node {
                            pending.push((value.clone(), Some(next), depth + 1));
                        }
                    }
                }
                I::Parameter { slot } | I::Capture { slot } => {
                    let frame =
                        frame
                            .and_then(|id| frames.get(id))
                            .ok_or_else(|| CompileError {
                                message: message.into(),
                            })?;
                    let actuals = if matches!(value, I::Parameter { .. }) {
                        &frame.arguments
                    } else {
                        &frame.captures
                    };
                    let actual = actuals.get(*slot).ok_or_else(|| CompileError {
                        message: message.into(),
                    })?;
                    pending.push((actual.clone(), frame.parent, frame.depth + 1));
                }
                _ => return unsupported(message),
            }
        }
        self.target_nesting -= 1;
        Ok(reads)
    }
}

fn branch(name: &str, steps: Vec<Step>) -> ir::Branch {
    ir::Branch {
        name: name.into(),
        steps,
    }
}
fn guard(expression: I) -> Step {
    Step::Guard { expression }
}
fn not(argument: I) -> I {
    I::Not {
        argument: Box::new(argument),
    }
}
fn atom(expression: I) -> T {
    T::Atom { expression }
}
fn atom_parts(mut formula: T) -> std::result::Result<I, T> {
    if let T::Atom { expression } = &mut formula {
        Ok(std::mem::replace(expression, I::Old))
    } else {
        typed::atom_expression(&formula).ok_or(formula)
    }
}
fn negate(formula: T) -> T {
    match atom_parts(formula) {
        Ok(expression) => atom(not(expression)),
        Err(formula) => T::Not {
            formula: Box::new(formula),
        },
    }
}
fn connective(and: bool, left: I, right: I) -> I {
    if and {
        I::And {
            left: Box::new(left),
            right: Box::new(right),
        }
    } else {
        I::Or {
            left: Box::new(left),
            right: Box::new(right),
        }
    }
}
fn structural(and: bool, left: T, right: T) -> T {
    if and {
        T::And {
            left: Box::new(left),
            right: Box::new(right),
        }
    } else {
        T::Or {
            left: Box::new(left),
            right: Box::new(right),
        }
    }
}
fn combine(and: bool, left: T, right: T) -> T {
    match typed::atom_expression(&right) {
        Some(right_expression) => match atom_parts(left) {
            Ok(left_expression) => atom(connective(and, left_expression, right_expression)),
            Err(left) => structural(and, left, right),
        },
        None => structural(and, left, right),
    }
}
fn frame_actuals(frame: &AnonymousFrame) -> Result<(Vec<I>, Vec<I>)> {
    for value in frame.arguments.iter().chain(&frame.captures) {
        typed::check_depth_from(Node::Expression(value), 1)?;
    }
    Ok((frame.arguments.clone(), frame.captures.clone()))
}
fn frame_step(frame: &AnonymousFrame, branches: Vec<ir::Branch>) -> Result<Step> {
    for branch in &branches {
        typed::check_depth_from(Node::Branch(branch), 1)?;
    }
    let (arguments, captures) = frame_actuals(frame)?;
    let mut step = Step::Frame {
        parameter_count: arguments.len(),
        capture_count: captures.len(),
        local_scope: 0,
        arguments,
        captures,
        branches,
    };
    typed::compact_anonymous(NodeMut::Step(&mut step));
    Ok(step)
}
fn frame_expression(frame: &AnonymousFrame, body: I) -> Result<I> {
    typed::check_depth_from(Node::Expression(&body), 1)?;
    let (arguments, captures) = frame_actuals(frame)?;
    let mut expression = I::Frame {
        parameter_count: arguments.len(),
        capture_count: captures.len(),
        local_scope: typed::local_scope(Node::Expression(&body)),
        arguments,
        captures,
        body: Box::new(body),
    };
    typed::compact_anonymous(NodeMut::Expression(&mut expression));
    Ok(expression)
}
fn frame_formula(frame: &AnonymousFrame, formula: T) -> Result<T> {
    typed::check_depth_from(Node::Temporal(&formula), 1)?;
    let (arguments, captures) = frame_actuals(frame)?;
    let mut formula = T::Frame {
        parameter_count: arguments.len(),
        capture_count: captures.len(),
        local_scope: 0,
        arguments,
        captures,
        formula: Box::new(formula),
    };
    typed::compact_anonymous(NodeMut::Temporal(&mut formula));
    Ok(formula)
}
fn unchanged(value: I) -> Result<Vec<Step>> {
    let children = analysis_children(Node::Expression(&value));
    match &value {
        I::Tuple { .. } => children.into_iter().try_fold(vec![], |mut steps, edge| {
            if let Node::Expression(value) = edge.node {
                steps.extend(unchanged(value.clone())?);
            }
            Ok(steps)
        }),
        I::Read { slot, next: false } => Ok(vec![Step::Assign { slot: *slot, value }]),
        _ => unsupported("generative UNCHANGED requires state variables"),
    }
}
impl Compiler<'_> {
    fn target_reads_ir(&mut self, value: &Expression, context: &Context) -> Result<Vec<I>> {
        let target = Self::target_ir(&self.resolve_target_within(value, context, 256)?)?;
        self.variable_reads_ir(target, "generative UNCHANGED requires state variables", 0)
    }
    pub(super) fn action_ir(
        &mut self,
        value: &Expression,
        context: &Context,
        name: &str,
    ) -> Result<Vec<ir::Branch>> {
        let child = context.nested()?;
        match &value.node {
            E::BoxAction { action, subscript } | E::AngleAction { action, subscript }
                if context.phase == Phase::Next =>
            {
                let target = Self::target_ir(&self.resolve_target(subscript, context)?)?;
                let mut branches = self.action_ir(action, &child, name)?;
                if matches!(value.node, E::BoxAction { .. }) {
                    let mut steps = vec![];
                    for read in self.variable_reads_ir(
                        target,
                        "generative UNCHANGED requires state variables",
                        0,
                    )? {
                        steps.extend(unchanged(read)?);
                    }
                    branches.push(branch(name, steps));
                } else {
                    let next = self.prime_ir(target.clone())?;
                    let expression = I::Ne {
                        left: Box::new(target),
                        right: Box::new(next),
                    };
                    for branch in &mut branches {
                        branch.steps.push(guard(expression.clone()));
                    }
