            Node::Expression(I::Bound { slot })
            | Node::Binding(ir::Binding { slot, .. })
            | Node::Step(Step::Bind { slot, .. }) => slot + 1,
            Node::Expression(I::Fold { accumulator, .. }) => accumulator + 2,
            _ => 0,
        });
        pending.extend(
            analysis_children(node)
                .into_iter()
                .filter(|edge| edge.descriptor.scope != "frame")
                .map(|edge| edge.node),
        );
    }
