        .filter(|slot| used.contains(slot))
        .enumerate()
        .map(|(new, old)| (old, new))
        .collect();
    let changed = *count != mapping.len();
    remap_captures(body.reborrow(), &mapping);
    let mut slot = 0;
    captures.retain(|_| {
        let keep = mapping.contains_key(&slot);
        slot += 1;
