                let expression = if self.version == IrVersion::V2 {
                    self.shared_call(&name, &[], &self.root(phase), false)?
                } else {
                    let (body, context) = self.operator(&name, phase)?;
                    self.expression(&body, &context)?
                };
                predicates.push(json!({"name":name,"expression":expression}));
            }
            result[key] = json!(predicates);
        }
        if !initial_properties.is_empty() {
            result["initialProperties"] = json!(initial_properties);
        }
        if !action_properties.is_empty() {
            result["actionProperties"] = json!(action_properties);
        }
        if !properties.is_empty() {
            result["properties"] = json!(properties);
            result["fairness"] = json!(fairness);
        }
        serde_json::from_value(result).map_err(|error| CompileError {
            message: format!("invalid generated IR: {error}"),
        })
    }
}
fn read_slots(value: &Json, slots: &mut HashSet<u64>) -> Result<()> {
    if value["op"] == "tuple" {
        for inner in value["values"].as_array().into_iter().flatten() {
            read_slots(inner, slots)?;
        }
        return Ok(());
    }
    if value["op"] != "read" || value["next"] != false {
        return unsupported("SPECIFICATION subscript must list state variables");
    }
    if let Some(slot) = value["slot"].as_u64() {
        slots.insert(slot);
    }
    Ok(())
}
fn validate_temporal(formula: &Json, path: &[String], direct: bool) -> Result<()> {
    match formula["kind"].as_str() {
        Some("atom") => {
            let tail = path
                .iter()
                .rev()
                .take(2)
                .map(String::as_str)
                .collect::<Vec<_>>();
            if level(&formula["expression"]) > 1
                && !(direct && path.len() == 1)
                && tail != ["eventually", "always"]
                && tail != ["always", "eventually"]
            {
                return unsupported("temporal actions require []<>A or <>[]A");
            }
            Ok(())
        }
        Some("and" | "or") => {
            validate_temporal(&formula["left"], path, direct)?;
            validate_temporal(&formula["right"], path, direct)
        }
        Some(kind) => {
            let mut path = path.to_vec();
            if !["not", "forall", "exists"].contains(&kind) {
                path.push(kind.into());
            }
            validate_temporal(&formula["formula"], &path, direct)
        }
        None => unsupported("invalid temporal formula"),
    }
}

fn prime(&mut self, value: Json) -> Result<Json> {
    prime(value)
}
fn validate_temporal(&self, formula: &Json, path: &[String], direct: bool) -> Result<()> {
    validate_temporal(formula, path, direct)
}
fn shared_call(
    &mut self,
    name: &str,
    args: &[Expression],
    context: &Context,
    membership: bool,
) -> Result<Json> {
    let child = context.nested()?;
    let demanded = self.membership_demands(name, context, membership)?;
    let position = self.scopes[context.scope][name].id;
    let arguments = args
        .iter()
        .enumerate()
        .map(|(slot, argument)| {
            if membership || demanded.contains(&self.binding_id(position, 0, slot)) {
                self.membership_set(argument, &child)
            } else {
                self.expression(argument, &child)
            }
        })
        .collect::<Result<Vec<_>>>()?;
    let targets = self.call_targets(name, args, context)?;
    self.shared_arguments(name, arguments, context, membership, targets)
}
fn call_targets(
    &mut self,
    name: &str,
    args: &[Expression],
    context: &Context,
) -> Result<BTreeMap<usize, Target>> {
    self.call_targets_purpose(name, args, context, false)
}
fn call_targets_purpose(
    &mut self,
    name: &str,
    args: &[Expression],
    context: &Context,
    action: bool,
) -> Result<BTreeMap<usize, Target>> {
    let entry = self.scopes[context.scope]
        .get(name)
        .cloned()
        .ok_or_else(|| CompileError {
            message: format!("operator {name}"),
        })?;
    let position = entry.id;
    let required = self.requirements(name, context, action)?;
    let mut targets = BTreeMap::new();
    for binding in required {
        let parameter = if let DefinitionKind::Operator { params } = &entry.definition.head {
            params.iter().enumerate().find_map(|(slot, _)| {
                (self.binding_id(position, 0, slot) == binding).then_some(slot)
            })
        } else {
            None
        };
        let target = if let Some(slot) = parameter {
            self.resolve_target(
                args.get(slot).ok_or_else(|| CompileError {
                    message: format!("operator {name}"),
                })?,
                context,
            )?
        } else if let Some((actual, caller, _)) = context
            .target_actuals
            .get(&binding)
            .or_else(|| entry.target_actuals.get(&binding))
        {
            self.resolve_target(actual, caller)?
        } else {
            context
                .static_targets
                .get(&binding)
                .or_else(|| entry.static_targets.get(&binding))
                .cloned()
                .ok_or_else(|| CompileError {
                    message: "generative UNCHANGED requires state variables".into(),
                })?
        };
        Self::target_json(&target)?;
        targets.insert(binding, target);
    }
    Ok(targets)
}
fn shared_arguments(
    &mut self,
    name: &str,
    arguments: Vec<Json>,
    context: &Context,
    membership: bool,
    targets: BTreeMap<usize, Target>,
) -> Result<Json> {
    Ok(json!(
        self.shared_arguments_ir(
            name,
            arguments
                .into_iter()
                .map(decode_expression)
                .collect::<Result<_>>()?,
            context,
            membership,
            targets
        )?
    ))
}
fn shared_arguments_ir(
    &mut self,
    name: &str,
    arguments: Vec<ir::Expression>,
    context: &Context,
    membership: bool,
    targets: BTreeMap<usize, Target>,
) -> Result<ir::Expression> {
    self.shared_body_ir(
        name,
        arguments,
        context,
        membership,
        targets,
        ir::BodyKind::Expression,
    )
}
fn shared_body_ir(
    &mut self,
    name: &str,
    arguments: Vec<ir::Expression>,
    context: &Context,
    membership: bool,
    mut targets: BTreeMap<usize, Target>,
    kind: ir::BodyKind,
) -> Result<ir::Expression> {
    let entry = self.scopes[context.scope]
        .get(name)
        .map(|entry| entry.as_ref().clone())
        .ok_or_else(|| CompileError {
            message: format!("operator {name}"),
        })?;
    let position = entry.id;
    let (body, params) = match &entry.definition.head {
        DefinitionKind::Operator { params } => {
            if params.len() != arguments.len()
                || params.iter().any(|parameter| parameter.arity != 0)
            {
                return unsupported(format!("operator {name}"));
            }
            (
                entry.definition.body.clone(),
                params
                    .iter()
                    .map(|parameter| parameter.name.clone())
                    .collect::<Vec<_>>(),
            )
        }
        DefinitionKind::Function { bounds } => {
            if !arguments.is_empty() {
                return unsupported(format!("function operator {name}"));
            }
            (
                Expression {
                    node: E::FunctionConstruction {
                        bounds: bounds.clone(),
                        body: Box::new(entry.definition.body.clone()),
                    },
                    location: entry.definition.location,
                },
                vec![],
            )
        }
    };
    let phase = match context.phase {
        Phase::Constant => 0,
        Phase::Initial => 1,
        Phase::State => 2,
        Phase::Next => 3,
    };
    let required = self.requirements(name, context, kind == ir::BodyKind::Action)?;
    for binding in &required {
        if !targets.contains_key(binding)
            && let Some(target) = context
                .static_targets
                .get(binding)
                .or_else(|| entry.static_targets.get(binding))
        {
            targets.insert(*binding, target.clone());
        }
    }
    let signature = required
        .iter()
        .map(|binding| {
            targets.get(binding).cloned().ok_or_else(|| CompileError {
                message: "generative UNCHANGED requires state variables".into(),
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let key = (position, phase, membership, signature, kind);
    let id = if let Some(id) = self.shared.iter().position(|shared| shared.key == key) {
        id
    } else {
        let id = self.shared.len();
        let candidates: Vec<_> = entry.projection.keys().copied().collect();
        let mut inner = self.root(context.phase);
        inner.origin = entry.id;
        inner.scope = entry.scope;
        inner.static_targets = targets;
        for (slot, binding) in candidates.iter().enumerate() {
            inner
                .projection
                .insert(*binding, ir::Expression::Capture { slot });
        }
        for name in &entry.order {
            let binding = entry.binding_ids[name];
            inner
                .locals
                .insert(name.clone(), inner.projection[&binding].clone());
            inner.binding_ids.insert(name.clone(), binding);
            inner.order.push(name.clone());
        }
        for (slot, name) in params.iter().enumerate() {
            let value = ir::Expression::Parameter { slot };
            inner.locals.insert(name.clone(), value.clone());
            inner.order.retain(|other| other != name);
            inner.order.push(name.clone());
            let binding = self.binding_id(position, 0, slot);
            inner.binding_ids.insert(name.clone(), binding);
            inner.projection.insert(binding, value);
        }
        self.shared.push(Shared {
            recursive: entry.definition.is_recursive,
            key,
            captures: candidates.clone(),
            definition: None,
            parameter_count: params.len(),
            pending: Some((body, inner, membership)),
        });
        id
    };
    let capture_bindings = self.shared[id].captures.clone();
    let mut captures = vec![];
    for binding in capture_bindings {
        let value = context
            .projection
            .get(&binding)
            .or_else(|| entry.projection.get(&binding))
            .cloned()
            .ok_or_else(|| CompileError {
                message: "lexical capture".into(),
            })?;
        captures.push(value);
    }
    Ok(ir::Expression::Call {
        definition: id,
        arguments,
        captures,
    })
}
fn lower_definition(&mut self, id: usize) -> Result<()> {
    if let Some((body, context, membership)) = self.shared[id].pending.take() {
        let body = if self.shared[id].key.4 == ir::BodyKind::Temporal {
            ir::DefinitionBody::Temporal(Box::new(self.temporal_ir(&body, &context)?))
        } else if self.shared[id].key.4 == ir::BodyKind::Action {
            ir::DefinitionBody::Action(self.action_ir(&body, &context, "<action>")?)
        } else if membership {
            self.membership_ir(&body, &context)?.into()
        } else {
            self.expression_ir(&body, &context)?.into()
        };
        typed::check_depth(Node::Body(&body))?;
        self.shared[id].definition = Some(ir::Definition {
            recursive: self.shared[id].recursive,
            id,
            parameter_count: self.shared[id].parameter_count,
            capture_count: self.shared[id].captures.len(),
            body_kind: self.shared[id].key.4,
            local_scope: typed::local_scope(Node::Body(&body)),
            body,
        });
    }
    Ok(())
}
fn lower_pending(&mut self) -> Result<()> {
    if self.draining {
        return Ok(());
    }
    self.draining = true;
    let mut id = 0;
    while id < self.shared.len() {
        self.lower_definition(id)?;
        id += 1;
    }
    self.draining = false;
    self.level_cache.borrow_mut().clear();
    let order = self.definition_order()?;
    self.prepare_levels(&order);
    Ok(())
}
fn finish_shared(&mut self, mut program: ir::SafetyProgram) -> Result<ir::SafetyProgram> {
    self.lower_pending()?;
    typed::check_depth(Node::Program(&program))?;
    let order = self.definition_order()?;
    self.prepare_levels(&order);
    loop {
        let mut anonymous_changed = typed::compact_anonymous(NodeMut::Program(&mut program));
        for entry in &mut self.shared {
            anonymous_changed |= typed::compact_anonymous(NodeMut::Body(
                &mut entry.definition.as_mut().unwrap().body,
            ));
        }
        let mappings: Vec<HashMap<_, _>> = self
            .shared
            .iter()
            .map(|entry| {
                let used =
                    typed::capture_slots(Node::Body(&entry.definition.as_ref().unwrap().body));
                (0..entry.captures.len())
                    .filter(|slot| used.contains(slot))
                    .enumerate()
                    .map(|(new, old)| (old, new))
                    .collect()
            })
            .collect();
        if self
            .shared
            .iter()
            .zip(&mappings)
            .all(|(entry, mapping)| entry.captures.len() == mapping.len())
            && !anonymous_changed
        {
            break;
        }
        for (id, entry) in self.shared.iter_mut().enumerate() {
            let mut slot = 0;
            entry.captures.retain(|_| {
                let keep = mappings[id].contains_key(&slot);
                slot += 1;
                keep
            });
            let definition = entry.definition.as_mut().unwrap();
            typed::remap_captures(NodeMut::Body(&mut definition.body), &mappings[id]);
            definition.capture_count = entry.captures.len();
            typed::trim_call_captures(NodeMut::Body(&mut definition.body), &mappings);
        }
        typed::trim_call_captures(NodeMut::Program(&mut program), &mappings);
    }
    self.prepare_levels(&order);
    for entry in &self.shared {
        typed::check_primes(
            Node::Body(&entry.definition.as_ref().unwrap().body),
            &self.level_cache.borrow(),
        )?;
    }
    typed::check_primes(Node::Program(&program), &self.level_cache.borrow())?;
    typed::check_shared_expansion(
        &program,
        &self
            .shared
            .iter()
            .map(|entry| entry.definition.as_ref().unwrap())
            .collect::<Vec<_>>(),
        &order,
    )?;
    let mut reached = HashSet::new();
    let mut pending: Vec<_> = typed::call_ids(Node::Program(&program))
        .into_iter()
        .collect();
    while let Some(id) = pending.pop() {
        if reached.insert(id) {
            pending.extend(typed::call_ids(Node::Body(
                &self.shared[id].definition.as_ref().unwrap().body,
            )));
        }
    }
    let mut order: Vec<_> = (0..self.shared.len())
        .filter(|id| self.shared[*id].key.4 != ir::BodyKind::Temporal || reached.contains(id))
        .collect();
    order.sort_by(|left, right| self.shared[*left].key.cmp(&self.shared[*right].key));
    let mapping: HashMap<_, _> = order
        .iter()
        .enumerate()
        .map(|(new, old)| (*old, new))
        .collect();
    typed::remap_calls(NodeMut::Program(&mut program), &mapping);
    program.definitions = Some(
        order
            .iter()
            .enumerate()
            .map(|(new, old)| {
                let mut definition = self.shared[*old].definition.take().unwrap();
                definition.id = new;
                typed::remap_calls(NodeMut::Definition(&mut definition), &mapping);
                definition
            })
            .collect(),
    );
    typed::check_depth(Node::Program(&program))?;
    Ok(program)
}
fn definition_order(&self) -> Result<Vec<usize>> {
    let edges: Vec<Vec<_>> = self
        .shared
        .iter()
        .map(|entry| {
            let mut calls = HashSet::new();
            calls.extend(typed::call_ids(Node::Body(
                &entry.definition.as_ref().unwrap().body,
            )));
            calls.into_iter().collect()
        })
        .collect();
    let mut states = vec![0_u8; self.shared.len()];
    let mut order = vec![];
    for root in 0..self.shared.len() {
        if states[root] != 0 {
            continue;
        }
        states[root] = 1;
        let mut pending = vec![(root, 0)];
        while let Some((id, edge)) = pending.last_mut() {
            if let Some(&callee) = edges[*id].get(*edge) {
                *edge += 1;
                match states[callee] {
                    0 => {
                        states[callee] = 1;
                        pending.push((callee, 0));
                    }
                    1 => {
                        let start = pending.iter().position(|(id, _)| *id == callee).unwrap();
                        if pending[start..]
                            .iter()
                            .any(|(id, _)| !self.shared[*id].recursive)
                        {
                            return unsupported(
                                "recursive operator definitions require RECURSIVE declarations",
                            );
                        }
                    }
                    _ => {}
                }
            } else {
                states[*id] = 2;
                order.push(*id);
                pending.pop();
            }
        }
    }
    Ok(order)
}
fn root(&self, phase: Phase) -> Context {
    Context {
        origin: 0,
        phase,
        locals: BTreeMap::new(),
        calls: vec![],
        call_ids: vec![],
        depth: 0,
        bound: 0,
        scope: 0,
        order: vec![],
        binding_ids: BTreeMap::new(),
        projection: BTreeMap::new(),
        static_targets: BTreeMap::new(),
        target_actuals: BTreeMap::new(),
        frame: None,
        temporal_frames: vec![],
    }
}
fn has(&self, context: &Context, name: &str) -> bool {
    self.scopes[context.scope].contains_key(name)
}
fn extends(&self, name: &str) -> bool {
    self.module.extends.iter().any(|item| item == name)
}
fn arithmetic(&self) -> bool {
    self.module.extends.iter().any(|name| {
        ["Naturals", "Integers", "Sequences", "FiniteSets"].contains(&name.as_str())
    })
}
fn call(
    &mut self,
    name: &str,
    args: &[Expression],
    context: &Context,
) -> Result<(Expression, Context)> {
    let entry = self.scopes[context.scope]
        .get(name)
        .map(|entry| entry.as_ref().clone())
        .ok_or_else(|| CompileError {
            message: format!("operator {name}"),
        })?;
    if self.version == IrVersion::V1 && args.iter().any(free_old) && self.rebinds_old(&entry) {
        return unsupported("EXCEPT @ arguments across a nested EXCEPT require safety IR v2");
    }
    if entry.definition.is_recursive
        || if self.version == IrVersion::V1 {
            context.calls.iter().any(|item| item == name)
        } else {
            context.call_ids.contains(&entry.id)
        }
    {
        return unsupported(format!("operator {name}"));
    }
    let position = entry.id;
    if self.version == IrVersion::V2 {
        let mut inner = self.target_context(&entry);
        inner.phase = context.phase;
        inner.temporal_frames = context.temporal_frames.clone();
        inner.depth = context.nested()?.depth;
        inner.bound = 0;
        inner.calls = context.calls.clone();
        inner.call_ids = context.call_ids.clone();
        inner.calls.push(name.into());
        inner.call_ids.push(position);
        inner.locals.clear();
        inner.projection.clear();
        inner.static_targets.extend(context.static_targets.clone());
        inner.target_actuals.extend(context.target_actuals.clone());
        let candidates: Vec<_> = entry.projection.keys().copied().collect();
        let captures = candidates
            .iter()
            .map(|binding| {
                context
                    .projection
                    .get(binding)
                    .or_else(|| entry.projection.get(binding))
                    .cloned()
                    .ok_or_else(|| CompileError {
                        message: "lexical capture".into(),
                    })
            })
            .collect::<Result<Vec<_>>>()?;
        for (slot, binding) in candidates.iter().enumerate() {
            inner
                .projection
                .insert(*binding, ir::Expression::Capture { slot });
            if let Some(target) = context.static_targets.get(binding) {
                inner.static_targets.insert(*binding, target.clone());
            }
            if let Some(actual) = context.target_actuals.get(binding) {
                inner.target_actuals.insert(*binding, actual.clone());
            }
        }
        for name in &entry.order {
            inner.locals.insert(
                name.clone(),
                inner.projection[&entry.binding_ids[name]].clone(),
            );
        }
        let mut arguments = vec![];
        let body = match &entry.definition.head {
            DefinitionKind::Operator { params } => {
                if params.len() != args.len()
                    || params.iter().any(|parameter| parameter.arity != 0)
                {
                    return unsupported(format!("operator {name}"));
                }
                let demanded = self.membership_demands(name, context, false)?;
                for (slot, (parameter, actual)) in params.iter().zip(args).enumerate() {
                    let binding = self.binding_id(position, 0, slot);
                    arguments.push(if demanded.contains(&binding) {
                        self.membership_ir(actual, context)?
                    } else {
                        self.expression_ir(actual, context)?
                    });
                    let parameter_value = ir::Expression::Parameter { slot };
                    inner
                        .locals
                        .insert(parameter.name.clone(), parameter_value.clone());
                    inner.binding_ids.insert(parameter.name.clone(), binding);
                    inner.projection.insert(binding, parameter_value);
                    inner.order.retain(|name| name != &parameter.name);
                    inner.order.push(parameter.name.clone());
                    inner.target_actuals.insert(
                        binding,
                        (actual.clone(), Rc::new(context.clone()), HashSet::new()),
                    );
                }
                entry.definition.body.clone()
            }
            DefinitionKind::Function { bounds } => {
                if !args.is_empty() {
                    return unsupported(format!("function operator {name}"));
                }
                Expression {
                    node: E::FunctionConstruction {
                        bounds: bounds.clone(),
                        body: Box::new(entry.definition.body.clone()),
                    },
                    location: entry.definition.location,
                }
            }
        };
        if !arguments.is_empty() || !captures.is_empty() || context.bound > 0 {
            for value in arguments.iter().chain(&captures) {
                typed::check_depth_from(Node::Expression(value), 1)?;
            }
            inner.frame = Some(AnonymousFrame {
                arguments,
                captures,
            });
        }
        if let Some(frame) = &inner.frame {
            inner.temporal_frames.push(frame.clone());
        }
        return Ok((body, inner));
    }
    let mut locals = entry.locals;
    if self.version == IrVersion::V2 {
        for (name, binding) in &entry.binding_ids {
            if let Some(value) = context.projection.get(binding) {
                locals.insert(name.clone(), value.clone());
            }
        }
    }
    let mut projection: BTreeMap<_, _> = entry
        .projection
        .iter()
        .map(|(binding, value)| {
            (
                *binding,
                context.projection.get(binding).unwrap_or(value).clone(),
            )
        })
        .collect();
    let mut binding_ids = entry.binding_ids;
    let mut order = entry.order;
    let body = match &entry.definition.head {
        DefinitionKind::Operator { params } => {
            if params.len() != args.len() || params.iter().any(|param| param.arity != 0) {
                return unsupported(format!("operator {name}"));
            }
            for (slot, (param, argument)) in params.iter().zip(args).enumerate() {
                locals.insert(
                    param.name.clone(),
                    decode_expression(self.expression(argument, context)?)?,
                );
                order.retain(|name| name != &param.name);
                order.push(param.name.clone());
                let binding = self.binding_id(position, 0, slot);
                binding_ids.insert(param.name.clone(), binding);
                projection.insert(binding, locals[&param.name].clone());
            }
            entry.definition.body.clone()
        }
        DefinitionKind::Function { bounds } => {
            if !args.is_empty() {
                return unsupported(format!("function operator {name}"));
            }
            Expression {
                node: E::FunctionConstruction {
                    bounds: bounds.clone(),
                    body: Box::new(entry.definition.body.clone()),
                },
                location: entry.definition.location,
            }
        }
    };
    let mut child = context.nested()?;
    child.origin = entry.id;
    child.locals = locals;
    child.order = order;
    child.binding_ids = binding_ids;
    child.projection = projection;
    child.scope = entry.scope;
    child.calls.push(name.into());
    child.call_ids.push(position);
    Ok((body, child))
}
fn rebinds_old(&self, entry: &Entry) -> bool {
    let mut visited = HashSet::new();
    let mut pending = vec![(Node::SourceDefinition(&entry.definition), entry.scope)];
    while let Some((node, scope)) = pending.pop() {
        if matches!(
            node,
            Node::Source(Expression {
                node: E::Except { .. },
                ..
            })
        ) {
            return true;
        }
        if let Node::Source(Expression {
            node: E::Identifier { name } | E::Apply { operator: name, .. },
            ..
        }) = node
            && let Some(callee) = self.scopes[scope].get(name)
            && visited.insert(callee.id)
        {
            pending.push((Node::SourceDefinition(&callee.definition), callee.scope));
        }
        pending.extend(
            analysis::analysis_children(node)
                .into_iter()
                .map(|edge| (edge.node, scope)),
        );
    }
    false
}
fn let_context(&mut self, definitions: &[Definition], context: &Context) -> Result<Context> {
    for definition in definitions {
        let imported = match definition.name.as_str() {
            "SelectSeq" => self.extends("Sequences"),
            "SortSeq" | "Assert" => self.extends("TLC"),
            _ => false,
        };
        if imported {
            return unsupported(format!("duplicate LET definition {}", definition.name));
        }
    }
    if definitions
        .iter()
        .map(|definition| &definition.name)
        .collect::<HashSet<_>>()
        .len()
        != definitions.len()
    {
        return unsupported("duplicate LET definitions");
    }
    let scope = self.scopes.len();
    let mut entries = self.scopes[context.scope].clone();
    for definition in definitions {
        entries.insert(
            definition.name.clone(),
            Rc::new(Entry {
                id: self.declaration_ids[&(definition.location.start, definition.name.clone())],
                definition: Rc::new(definition.clone()),
                locals: context.locals.clone(),
                scope,
                order: context.order.clone(),
                binding_ids: context.binding_ids.clone(),
                projection: context.projection.clone(),
                static_targets: context.static_targets.clone(),
                target_actuals: context.target_actuals.clone(),
            }),
        );
    }
    self.scopes.push(entries);
    Ok(Context {
        scope,
        ..context.nested()?
    })
}
fn bind(&mut self, bounds: &[ast::Bound], context: &Context) -> Result<(Vec<Json>, Context)> {
    let mut child = context.clone();
    let mut bindings = vec![];
    for bound in bounds {
        if child.bound >= 40 {
            return unsupported("more than 40 bound variables");
        }
        let slot = child.bound;
        let mut binding = json!({"slot":slot,"domain":self.domain(&bound.set,context,true)?});
        match &bound.pattern {
            Pattern::Name { name } => {
                child.order.retain(|item| item != name);
                child.order.push(name.clone());
                let binding_id =
                    self.named_binding_at(context.origin, bound.set.location.start, 1, 0, name);
                child.binding_ids.insert(name.clone(), binding_id);
                child
                    .projection
                    .insert(binding_id, ir::Expression::Bound { slot });
                child
                    .locals
                    .insert(name.clone(), ir::Expression::Bound { slot });
            }
            Pattern::Tuple { names } => {
                binding["tupleSize"] = json!(names.len());
                for (index, name) in names.iter().enumerate() {
                    child.order.retain(|item| item != name);
                    child.order.push(name.clone());
                    let binding_id = self.named_binding_at(
                        context.origin,
                        bound.set.location.start,
                        1,
                        index,
                        name,
                    );
                    child.binding_ids.insert(name.clone(), binding_id);
                    child.projection.insert(
                        binding_id,
                        ir::Expression::At {
                            target: Box::new(ir::Expression::Bound { slot }),
                            key: Box::new(decode_expression(integer(index as i64 + 1)?)?),
                        },
                    );
                    child.locals.insert(
                        name.clone(),
                        ir::Expression::At {
                            target: Box::new(ir::Expression::Bound { slot }),
                            key: Box::new(decode_expression(integer(index as i64 + 1)?)?),
                        },
                    );
                }
            }
        }
        child = child.nested()?;
        child.bound = slot + 1;
        bindings.push(binding);
    }
    Ok((bindings, child))
}
fn domain(&mut self, value: &Expression, context: &Context, choice: bool) -> Result<Json> {
    if self.version == IrVersion::V2 {
        return Ok(json!(self.domain_ir(value, context, choice)?));
    }
    match &value.node {
        E::SetEnumeration { elements } => {
            Ok(json!({"kind":"set","values":self.expressions(elements,&context.nested()?)?}))
        }
        E::Apply { operator, args } if operator == ".." && args.len() == 2 => {
            if !self.arithmetic() {
                return unsupported("range requires Naturals");
            }
            let child = context.nested()?;
            Ok(
                json!({"kind":"range","lower":self.expression(&args[0],&child)?,"upper":self.expression(&args[1],&child)?}),
            )
        }
        E::Identifier { name } if name == "BOOLEAN" => {
            Ok(json!({"kind":"set","values":[boolean(false),boolean(true)]}))
        }
        E::Identifier { name } if name == "Nat" || name == "Int" => {
            if choice || !self.arithmetic() || (name == "Int" && !self.extends("Integers")) {
                return unsupported("infinite enumeration");
            }
            Ok(
                json!({"kind":"range","lower":integer(if name == "Nat" {0} else {i32::MIN as i64})?,"upper":integer(i32::MAX as i64)?}),
            )
        }
        E::Identifier { name }
            if self.has(context, name) && !context.locals.contains_key(name) =>
        {
            if self.version == IrVersion::V2 {
                return Ok(
                    json!({"kind":"value","value":self.shared_call(name, &[], context, false)?}),
                );
            }
            let (body, child) = self.call(name, &[], context)?;
            self.domain(&body, &child, choice)
        }
        _ => Ok(json!({"kind":"value","value":self.expression(value,context)?})),
    }
}
fn expressions(&mut self, values: &[Expression], context: &Context) -> Result<Vec<Json>> {
    values
        .iter()
        .map(|value| self.expression(value, context))
        .collect()
}
fn variable_reads(&mut self, value: Json, message: &str) -> Result<Vec<Json>> {
    if self.version == IrVersion::V1 {
        return Ok(vec![value]);
    }
    if self.target_nesting >= 40 {
        return unsupported("expression or operator nesting exceeds 40");
    }
    self.target_nesting += 1;
    self.lower_pending()?;
    struct Frame {
        definition: usize,
        arguments: Vec<Json>,
        captures: Vec<Json>,
        parent: Option<usize>,
    }
    let mut frames: Vec<Frame> = vec![];
    let mut pending: Vec<(Json, Option<usize>)> = vec![(value, None)];
    let mut reads = vec![];
    while let Some((value, frame)) = pending.pop() {
        match value["op"].as_str() {
            Some("tuple") => {
                pending.extend(
                    value["values"]
                        .as_array()
                        .into_iter()
                        .flatten()
                        .rev()
                        .map(|value| (value.clone(), frame)),
                );
            }
            Some("read") if value["next"] == false => reads.push(value),
            Some("call") => {
                let id = value["definition"].as_u64().unwrap_or(0) as usize;
                let mut ancestor = frame;
                while let Some(index) = ancestor {
                    if frames[index].definition == id {
                        return unsupported("recursive operator definitions");
                    }
                    ancestor = frames[index].parent;
                }
                self.lower_definition(id)?;
                let next = frames.len();
                frames.push(Frame {
                    definition: id,
                    arguments: value["arguments"].as_array().cloned().unwrap_or_default(),
                    captures: value["captures"].as_array().cloned().unwrap_or_default(),
                    parent: frame,
                });
                pending.push((
                    json!(self.shared[id].definition.as_ref().unwrap().body),
                    Some(next),
                ));
            }
            Some("parameter" | "capture") => {
                let Some(frame) = frame.and_then(|id| frames.get(id)) else {
                    return unsupported(message);
                };
                let slot = value["slot"].as_u64().unwrap_or(0) as usize;
                let actuals = if value["op"] == "parameter" {
                    &frame.arguments
                } else {
                    &frame.captures
                };
                let Some(actual) = actuals.get(slot) else {
                    return unsupported(message);
                };
                pending.push((actual.clone(), frame.parent));
            }
            _ => return unsupported(message),
        }
    }
    self.target_nesting -= 1;
    Ok(reads)
}
fn expression(&mut self, value: &Expression, context: &Context) -> Result<Json> {
    if self.version == IrVersion::V2 {
        return Ok(json!(self.expression_ir(value, context)?));
    }
    let child = context.nested()?;
    match &value.node {
        E::Number { value } => integer(i64::try_from(*value).map_err(|_| CompileError {
            message: "integer outside signed 32 bits".into(),
        })?),
        E::String { value } => {
            if value.chars().any(|character| character as u32 > 255) {
                return unsupported("TLC 1.7.4 string literal outside byte range");
            }
            Ok(string(value))
        }
        E::Identifier { name } => {
            if let Some(local) = context.locals.get(name) {
                return Ok(json!(local));
            }
            if let Some(constant) = self.constants.get(name) {
                return literal(constant);
            }
            if name == "TRUE" || name == "FALSE" {
                return Ok(boolean(name == "TRUE"));
            }
            if name == "BOOLEAN" {
                return Ok(json!({"op":"set","values":[boolean(false),boolean(true)]}));
            }
            if let Some(slot) = self.slots.get(name) {
                if context.phase == Phase::Constant {
                    return unsupported("variable in constant expression");
                }
                return Ok(
                    json!({"op":"read","slot":slot,"next":context.phase == Phase::Initial}),
                );
            }
            if self.version == IrVersion::V2 {
                return self.shared_call(name, &[], context, false);
            }
            let (body, expanded) = self.call(name, &[], context)?;
            self.expression(&body, &expanded)
        }
        E::Let { definitions, body } => {
            let expanded = self.let_context(definitions, context)?;
            self.expression(body, &expanded)
        }
        E::Label { body, .. } => self.expression(body, &child),
        E::Prime { expression } if context.phase == Phase::Next => {
            let mut inner = self.expression(expression, &child)?;
            if inner["op"] == "read" && inner["next"] == false {
                inner["next"] = json!(true);
                Ok(inner)
            } else {
                self.prime(inner)
            }
        }
        E::Unchanged { expression } if context.phase == Phase::Next => {
            let inner = self.expression(expression, &child)?;
            Ok(json!({"op":"eq","left":inner,"right":self.prime(inner.clone())?}))
        }
        E::Enabled { expression } => {
            let next = Context {
                phase: Phase::Next,
                ..child
            };
            Ok(json!({"op":"enabled","branches":self.action(expression,&next,"ENABLED")?}))
        }
        E::ExceptAt => Ok(json!(
            context
                .locals
                .get("@")
                .cloned()
                .unwrap_or(ir::Expression::Old)
        )),
        E::SetEnumeration { elements } | E::Tuple { elements } => Ok(
            json!({"op":if matches!(value.node,E::Tuple{..}) {"tuple"} else {"set"},"values":self.expressions(elements,&child)?}),
        ),
        E::Record { fields } | E::RecordSet { fields } => {
            let fields = fields
                .iter()
                .map(|field| Ok(json!([field.name, self.expression(&field.value, &child)?])))
                .collect::<Result<Vec<_>>>()?;
            Ok(
                json!({"op":if matches!(value.node,E::Record{..}) {"record"} else {"record-set"},"fields":fields}),
            )
        }
        E::FunctionSet { domain, range } => Ok(
            json!({"op":"function-set","left":self.expression(domain,&child)?,"right":self.expression(range,&child)?}),
        ),
        E::FunctionApplication { function, args } => {
            let key = self.key(args, &child)?;
            Ok(json!({"op":"at","target":self.expression(function,&child)?,"key":key}))
        }
        E::FieldAccess { record, field } => {
            Ok(json!({"op":"at","target":self.expression(record,&child)?,"key":string(field)}))
        }
        E::Except { function, updates } => {
            let mut lowered = vec![];
            for update in updates {
                let mut path = vec![];
                for part in &update.path {
                    path.push(match part {
                        ast::ExceptPath::Field { name } => string(name),
                        ast::ExceptPath::Index { args } => self.key(args, &child)?,
                    });
                }
                let mut old = child.clone();
                if self.version == IrVersion::V2 {
                    old.locals.insert("@".into(), ir::Expression::Old);
                    old.order.retain(|name| name != "@");
                    old.order.push("@".into());
                    let binding =
                        self.binding_at(context.origin, update.value.location.start, 2, 0);
                    old.binding_ids.insert("@".into(), binding);
                    old.projection.insert(binding, ir::Expression::Old);
                }
                lowered.push(json!({"path":path,"value":self.expression(&update.value,&old)?}));
            }
            Ok(
                json!({"op":"update","target":self.expression(function,&child)?,"updates":lowered}),
            )
        }
        E::Forall { bounds, body }
        | E::Exists { bounds, body }
        | E::FunctionConstruction { bounds, body } => {
            let (bindings, bound) = self.bind(bounds, &child)?;
            let op = match value.node {
                E::Forall { .. } => "forall",
                E::Exists { .. } => "exists",
                _ => "function",
            };
            Ok(json!({"op":op,"bounds":bindings,"body":self.expression(body,&bound)?}))
        }
        E::SetMap { bounds, expression } => {
            let (bindings, bound) = self.bind(bounds, &child)?;
            Ok(
                json!({"op":"map-set","bounds":bindings,"body":self.expression(expression,&bound)?}),
            )
        }
        E::SetFilter { bound, predicate } => {
            let (bindings, bound) = self.bind(std::slice::from_ref(bound), &child)?;
            Ok(
                json!({"op":"filter","bounds":bindings,"body":self.expression(predicate,&bound)?}),
            )
        }
        E::Choose {
            pattern,
            set: Some(set),
            body,
        } => {
            let bound = ast::Bound {
                pattern: pattern.clone(),
                set: *set.clone(),
            };
            let (bindings, context) = self.bind(&[bound], &child)?;
            Ok(
                json!({"op":"choose","binding":bindings[0],"body":self.expression(body,&context)?}),
            )
        }
        E::If {
            condition,
            consequent,
            alternative,
        } => Ok(
            json!({"op":"if","condition":self.expression(condition,&child)?,"consequent":self.expression(consequent,&child)?,"alternative":self.expression(alternative,&child)?}),
        ),
        E::Case { arms, other } => {
            let mut result = if let Some(other) = other {
                self.expression(other, &child)?
            } else if !arms.is_empty() {
                unmatched_case(&value.location)
            } else {
                return unsupported("empty CASE");
            };
            for arm in arms.iter().rev() {
                result = json!({"op":"if","condition":self.expression(&arm.condition,&child)?,"consequent":self.expression(&arm.body,&child)?,"alternative":result});
            }
            Ok(result)
        }
        E::And { operands, .. } | E::Or { operands, .. } => {
            let and = matches!(value.node, E::And { .. });
            let mut operands = operands.iter();
            let mut result = if self.version == IrVersion::V2 {
                if let Some(first) = operands.next() {
                    self.expression(first, &child)?
                } else {
                    boolean(and)
                }
            } else {
                boolean(and)
            };
            for operand in operands {
                result = json!({"op":if and {"and"} else {"or"},"left":result,"right":self.expression(operand,&child)?});
            }
            Ok(result)
        }
        E::BoxAction { action, subscript } | E::AngleAction { action, subscript } => {
            let boxed = matches!(value.node, E::BoxAction { .. });
            let subscript = self.expression(subscript, &child)?;
            let unchanged =
                json!({"op":"eq","left":subscript,"right":self.prime(subscript.clone())?});
            Ok(
                json!({"op":if boxed {"or"} else {"and"},"left":self.expression(action,&child)?,"right":if boxed {unchanged} else {json!({"op":"not","argument":unchanged})}}),
            )
        }
        E::Apply { operator, args } => self.apply(operator, args, context, &child),
        _ => unsupported(format!(
            "expression at {}:{}",
            value.location.line, value.location.column
        )),
    }
}
fn fold(
    &mut self,
    sequence: bool,
    args: &[Expression],
    context: &Context,
    child: &Context,
) -> Result<Json> {
    let initial = self.expression(&args[1], child)?;
    let collection = self.expression(&args[2], child)?;
    let body = self.callback(&args[0], 2, context, child)?;
    Ok(
        json!({"op":"fold", "accumulator":context.bound,"initial":initial,"collection":collection,"order":if sequence { "sequence-left" } else { "set-members" },"body":body}),
    )
}
fn callback(
    &mut self,
    argument: &Expression,
    arity: usize,
    context: &Context,
    child: &Context,
) -> Result<Json> {
    let E::Identifier { name } = &argument.node else {
        return unsupported("callback operator argument");
    };
    if context.locals.contains_key(name) {
        return unsupported(format!("callback operator {name}"));
    }
    let entry = self.scopes[context.scope]
        .get(name)
        .map(|entry| entry.as_ref().clone())
        .ok_or_else(|| CompileError {
            message: format!("operator {name}"),
        })?;
    if entry.definition.is_recursive
        || if self.version == IrVersion::V1 {
            context.calls.iter().any(|item| item == name)
        } else {
            context.call_ids.contains(&entry.id)
        }
    {
        return unsupported(format!("operator {name}"));
    }
    let DefinitionKind::Operator { params } = &entry.definition.head else {
        return unsupported(format!("callback operator {name}"));
    };
    if params.len() != arity || params.iter().any(|param| param.arity != 0) {
        return unsupported(format!("callback operator {name}"));
    }
    let accumulator = context.bound;
    if accumulator + arity > 40 {
        return unsupported("more than 40 bound variables");
    }
    let mut locals = entry.locals;
    for (index, param) in params.iter().enumerate() {
        locals.insert(
            param.name.clone(),
            ir::Expression::Bound {
                slot: accumulator + index,
            },
        );
    }
    let mut inner = child.nested()?;
    inner.origin = entry.id;
    inner.locals = locals;
    inner.scope = entry.scope;
    inner.calls.push(name.clone());
    inner.bound = accumulator + arity;
    self.expression(&entry.definition.body, &inner)
}
fn key(&mut self, args: &[Expression], context: &Context) -> Result<Json> {
    if args.len() == 1 {
        self.expression(&args[0], context)
    } else {
        Ok(json!({"op":"tuple","values":self.expressions(args,context)?}))
    }
}

use crate::analysis::{Node, analysis_children};
use crate::unsupported;
use crate::{CompileError, Compiler, Context, E, Expression, Phase, Result, Target, typed};
use rtla::ast::{self, ConfigValue, DefinitionKind, Pattern};
use rtlc::ir::{self, Domain, Expression as I, Scalar};
use std::collections::BTreeMap;
fn boolean(value: bool) -> I {
    I::Literal {
        value: Scalar::Bool(value),
    }
}
fn integer(value: i64) -> Result<I> {
    Ok(I::Literal {
        value: Scalar::Int(i32::try_from(value).map_err(|_| CompileError {
            message: "integer outside signed 32 bits".into(),
        })?),
    })
}
fn string(value: &str) -> I {
    I::Data {
        value: rtlc::Value::String(value.into()),
    }
}
fn literal(value: &ConfigValue) -> Result<I> {
    Ok(match value {
        ConfigValue::Number { value } => integer(*value)?,
        ConfigValue::Boolean { value } => boolean(*value),
        ConfigValue::String { value } => string(value),
        ConfigValue::Set { elements } => I::Set {
            values: elements.iter().map(literal).collect::<Result<_>>()?,
        },
        ConfigValue::ModelValue { name } => I::Data {
            value: rtlc::Value::ModelValue(name.clone()),
        },
    })
}
fn not(argument: I) -> I {
    I::Not {
        argument: Box::new(argument),
    }
}
fn unmatched(value: &Expression) -> I {
    I::UnmatchedCase {
        location: format!(
            "line {}, column {}",
            value.location.line, value.location.column
        ),
    }
}
impl Compiler<'_> {
    pub(super) fn expression_ir(&mut self, value: &Expression, context: &Context) -> Result<I> {
        let child = context.nested()?;
        Ok(match &value.node {
            E::Number { value } => integer(i64::try_from(*value).map_err(|_| CompileError {
                message: "integer outside signed 32 bits".into(),
            })?)?,
            E::String { value } => {
                if value.chars().any(|character| character as u32 > 255) {
                    return unsupported("TLC 1.7.4 string literal outside byte range");
                }
                string(value)
            }
            E::Identifier { name } => {
                if let Some(local) = context.locals.get(name) {
                    return Ok(local.clone());
                }
                if let Some(constant) = self.constants.get(name) {
                    return literal(constant);
                }
                if name == "TRUE" || name == "FALSE" {
                    return Ok(boolean(name == "TRUE"));
                }
                if name == "BOOLEAN" {
                    return Ok(I::Set {
                        values: vec![boolean(false), boolean(true)],
                    });
                }
                if let Some(slot) = self.slots.get(name) {
                    if context.phase == Phase::Constant {
                        return unsupported("variable in constant expression");
                    }
                    return Ok(I::Read {
                        slot: *slot,
                        next: context.phase == Phase::Initial,
                    });
                }
                self.shared_purpose_ir(name, &[], context, false)?
            }
            E::Let { definitions, body } => {
                let expanded = self.let_context(definitions, context)?;
                self.expression_ir(body, &expanded)?
            }
            E::Label { body, .. } => self.expression_ir(body, &child)?,
            E::Prime { expression } if context.phase == Phase::Next => {
                let inner = self.expression_ir(expression, &child)?;
                if let I::Read { slot, next: false } = inner {
                    I::Read { slot, next: true }
                } else {
                    self.prime_ir(inner)?
                }
            }
            E::Unchanged { expression } if context.phase == Phase::Next => {
                let inner = self.expression_ir(expression, &child)?;
                I::Eq {
                    left: Box::new(inner.clone()),
                    right: Box::new(self.prime_ir(inner)?),
                }
            }
            E::Enabled { expression } => I::Enabled {
                branches: self.action_ir(
                    expression,
                    &Context {
                        phase: Phase::Next,
                        ..child
                    },
                    "ENABLED",
                )?,
                subscript: None,
            },
            E::ExceptAt => context.locals.get("@").cloned().unwrap_or(I::Old),
            E::SetEnumeration { elements } | E::Tuple { elements } => {
                let values = self.expressions_ir(elements, &child)?;
                if matches!(value.node, E::Tuple { .. }) {
                    I::Tuple { values }
                } else {
                    I::Set { values }
                }
            }
            E::Record { fields } | E::RecordSet { fields } => {
                let fields = fields
                    .iter()
                    .map(|field| {
                        Ok((
                            field.name.clone(),
                            self.expression_ir(&field.value, &child)?,
                        ))
                    })
                    .collect::<Result<_>>()?;
                if matches!(value.node, E::Record { .. }) {
                    I::Record { fields }
                } else {
                    I::RecordSet { fields }
                }
            }
            E::FunctionSet { domain, range } => I::FunctionSet {
                left: Box::new(self.expression_ir(domain, &child)?),
                right: Box::new(self.expression_ir(range, &child)?),
            },
            E::FunctionApplication { function, args } => {
                let key = self.key_ir(args, &child)?;
                I::At {
                    target: Box::new(self.expression_ir(function, &child)?),
                    key: Box::new(key),
                }
            }
            E::FieldAccess { record, field } => I::At {
                target: Box::new(self.expression_ir(record, &child)?),
                key: Box::new(string(field)),
            },
            E::Except { function, updates } => {
                let mut lowered = vec![];
                for update in updates {
                    let mut path = vec![];
                    for part in &update.path {
                        path.push(match part {
                            ast::ExceptPath::Field { name } => string(name),
                            ast::ExceptPath::Index { args } => self.key_ir(args, &child)?,
                        });
                    }
                    let mut old = child.clone();
                    old.locals.insert("@".into(), I::Old);
                    old.order.retain(|name| name != "@");
                    old.order.push("@".into());
                    let binding =
                        self.binding_at(context.origin, update.value.location.start, 2, 0);
                    old.binding_ids.insert("@".into(), binding);
                    old.projection.insert(binding, I::Old);
                    lowered.push(ir::Update {
                        path,
                        value: self.expression_ir(&update.value, &old)?,
                    });
                }
                I::Update {
                    target: Box::new(self.expression_ir(function, &child)?),
                    updates: lowered,
                }
            }
            E::Forall { bounds, body }
            | E::Exists { bounds, body }
            | E::FunctionConstruction { bounds, body } => {
                let (bounds, bound) = self.bind_ir(bounds, &child)?;
                let body = Box::new(self.expression_ir(body, &bound)?);
                match value.node {
                    E::Forall { .. } => I::Forall { bounds, body },
                    E::Exists { .. } => I::Exists { bounds, body },
                    _ => I::Function { bounds, body },
                }
            }
            E::SetMap { bounds, expression } => {
                let (bounds, bound) = self.bind_ir(bounds, &child)?;
                I::MapSet {
                    bounds,
                    body: Box::new(self.expression_ir(expression, &bound)?),
                }
            }
            E::SetFilter { bound, predicate } => {
                let (bounds, bound) = self.bind_ir(std::slice::from_ref(bound), &child)?;
                I::Filter {
                    bounds,
                    body: Box::new(self.expression_ir(predicate, &bound)?),
                }
            }
            E::Choose {
                pattern,
                set: Some(set),
                body,
            } => {
                let (mut bounds, bound) = self.bind_ir(
                    &[ast::Bound {
                        pattern: pattern.clone(),
                        set: *set.clone(),
                    }],
                    &child,
                )?;
                I::Choose {
                    binding: bounds.remove(0),
                    body: Box::new(self.expression_ir(body, &bound)?),
                }
            }
            E::If {
                condition,
                consequent,
                alternative,
            } => I::If {
                condition: Box::new(self.expression_ir(condition, &child)?),
                consequent: Box::new(self.expression_ir(consequent, &child)?),
                alternative: Box::new(self.expression_ir(alternative, &child)?),
            },
            E::Case { arms, other } => {
                let mut result = if let Some(other) = other {
                    self.expression_ir(other, &child)?
                } else if !arms.is_empty() {
                    unmatched(value)
                } else {
                    return unsupported("empty CASE");
                };
                for arm in arms.iter().rev() {
                    result = I::If {
                        condition: Box::new(self.expression_ir(&arm.condition, &child)?),
                        consequent: Box::new(self.expression_ir(&arm.body, &child)?),
                        alternative: Box::new(result),
                    };
                }
                result
            }
            E::And { operands, .. } | E::Or { operands, .. } => {
                let and = matches!(value.node, E::And { .. });
                let mut operands = operands.iter();
                let mut result = if let Some(first) = operands.next() {
                    self.expression_ir(first, &child)?
                } else {
                    boolean(and)
                };
                for operand in operands {
                    let left = Box::new(result);
                    let right = Box::new(self.expression_ir(operand, &child)?);
                    result = if and {
                        I::And { left, right }
                    } else {
                        I::Or { left, right }
                    };
                }
                result
            }
            E::BoxAction { action, subscript } | E::AngleAction { action, subscript } => {
                let boxed = matches!(value.node, E::BoxAction { .. });
                let subscript = self.expression_ir(subscript, &child)?;
                let unchanged = I::Eq {
                    left: Box::new(subscript.clone()),
                    right: Box::new(self.prime_ir(subscript)?),
                };
                let left = Box::new(self.expression_ir(action, &child)?);
                if boxed {
                    I::Or {
                        left,
                        right: Box::new(unchanged),
                    }
                } else {
                    I::And {
                        left,
                        right: Box::new(not(unchanged)),
                    }
                }
            }
            E::Apply { operator, args } => self.apply_ir(operator, args, context, &child)?,
            _ => {
                return unsupported(format!(
                    "expression at {}:{}",
                    value.location.line, value.location.column
                ));
            }
        })
    }
    fn expressions_ir(&mut self, values: &[Expression], context: &Context) -> Result<Vec<I>> {
        values
            .iter()
            .map(|value| self.expression_ir(value, context))
            .collect()
    }
    fn key_ir(&mut self, args: &[Expression], context: &Context) -> Result<I> {
        if args.len() == 1 {
            self.expression_ir(&args[0], context)
        } else {
            Ok(I::Tuple {
                values: self.expressions_ir(args, context)?,
            })
        }
    }
    pub(super) fn prime_ir(&mut self, value: I) -> Result<I> {
        self.lower_pending()?;
        if typed::level_summary(Node::Expression(&value), &self.level_cache.borrow()).base > 1 {
            return unsupported("prime of an action expression");
        }
        Ok(I::Prime {
            argument: Box::new(value),
        })
    }
    pub(super) fn shared_ir(
        &mut self,
        name: &str,
        args: &[Expression],
        context: &Context,
    ) -> Result<I> {
        self.shared_purpose_ir(name, args, context, false)
    }
    fn shared_purpose_ir(
        &mut self,
        name: &str,
        args: &[Expression],
        context: &Context,
        membership: bool,
    ) -> Result<I> {
        let child = context.nested()?;
        let demanded = self.membership_demands(name, context, membership)?;
        let position = self.scopes[context.scope][name].id;
        let arguments = args
            .iter()
            .enumerate()
            .map(|(slot, argument)| {
                if membership || demanded.contains(&self.binding_id(position, 0, slot)) {
                    self.membership_ir(argument, &child)
                } else {
                    self.expression_ir(argument, &child)
                }
            })
            .collect::<Result<_>>()?;
        let targets = self.call_targets(name, args, context)?;
        self.shared_arguments_ir(name, arguments, context, membership, targets)
    }
    pub(super) fn bind_ir(
        &mut self,
        bounds: &[ast::Bound],
        context: &Context,
    ) -> Result<(Vec<ir::Binding>, Context)> {
        let mut child = context.clone();
        let mut bindings = vec![];
        for bound in bounds {
            if child.bound >= 40 {
                return unsupported("more than 40 bound variables");
            }
            let slot = child.bound;
            let mut binding = ir::Binding {
                slot,
                tuple_size: None,
                domain: self.domain_ir(&bound.set, context, true)?,
            };
            let names = match &bound.pattern {
                Pattern::Name { name } => vec![name],
                Pattern::Tuple { names } => {
                    binding.tuple_size = Some(names.len());
                    names.iter().collect()
                }
            };
            for (index, name) in names.iter().enumerate() {
                child.order.retain(|item| item != *name);
                child.order.push((*name).clone());
                let binding_id =
                    self.named_binding_at(context.origin, bound.set.location.start, 1, index, name);
                child.binding_ids.insert((*name).clone(), binding_id);
                let value = if matches!(bound.pattern, Pattern::Tuple { .. }) {
                    I::At {
                        target: Box::new(I::Bound { slot }),
                        key: Box::new(integer(index as i64 + 1)?),
                    }
                } else {
                    I::Bound { slot }
                };
                child.projection.insert(binding_id, value.clone());
                child.locals.insert((*name).clone(), value);
            }
            child = child.nested()?;
            child.bound = slot + 1;
            bindings.push(binding);
        }
        Ok((bindings, child))
    }
    pub(super) fn domain_ir(
        &mut self,
        value: &Expression,
        context: &Context,
        choice: bool,
    ) -> Result<Domain> {
        Ok(match &value.node {
            E::SetEnumeration { elements } => Domain::Set {
                values: self.expressions_ir(elements, &context.nested()?)?,
            },
            E::Apply { operator, args } if operator == ".." && args.len() == 2 => {
                if !self.arithmetic() {
                    return unsupported("range requires Naturals");
                }
                let child = context.nested()?;
                Domain::Range {
                    lower: Box::new(self.expression_ir(&args[0], &child)?),
                    upper: Box::new(self.expression_ir(&args[1], &child)?),
                }
            }
            E::Identifier { name } if name == "BOOLEAN" => Domain::Set {
                values: vec![boolean(false), boolean(true)],
            },
            E::Identifier { name } if name == "Nat" || name == "Int" => {
                if choice || !self.arithmetic() || name == "Int" && !self.extends("Integers") {
                    return unsupported("infinite enumeration");
                }
                Domain::Range {
                    lower: Box::new(integer(if name == "Nat" { 0 } else { i32::MIN as i64 })?),
                    upper: Box::new(integer(i32::MAX as i64)?),
                }
            }
            E::Identifier { name }
                if self.has(context, name) && !context.locals.contains_key(name) =>
            {
                Domain::Value {
                    value: Box::new(self.shared_ir(name, &[], context)?),
                }
            }
            _ => Domain::Value {
                value: Box::new(self.expression_ir(value, context)?),
            },
        })
    }
    pub(super) fn membership_ir(&mut self, value: &Expression, context: &Context) -> Result<I> {
        let child = context.nested()?;
        Ok(match &value.node {
            E::Let { definitions, body } => {
                let inner = self.let_context(definitions, context)?;
                self.membership_ir(body, &inner)?
            }
            E::Label { body, .. } => self.membership_ir(body, &child)?,
            E::If {
                condition,
                consequent,
                alternative,
            } => I::If {
                condition: Box::new(self.expression_ir(condition, &child)?),
                consequent: Box::new(self.membership_ir(consequent, &child)?),
                alternative: Box::new(self.membership_ir(alternative, &child)?),
            },
            E::Case { arms, other } if !arms.is_empty() => {
                let mut result = if let Some(other) = other {
                    self.membership_ir(other, &child)?
                } else {
                    unmatched(value)
                };
                for arm in arms.iter().rev() {
                    result = I::If {
                        condition: Box::new(self.expression_ir(&arm.condition, &child)?),
                        consequent: Box::new(self.membership_ir(&arm.body, &child)?),
                        alternative: Box::new(result),
                    };
                }
                result
            }
            E::Identifier { name } if name == "Nat" || name == "Int" => {
                if !self.arithmetic() || name == "Int" && !self.extends("Integers") {
                    return unsupported("infinite enumeration");
                }
                I::MapSet {
                    bounds: vec![ir::Binding {
                        slot: context.bound,
                        tuple_size: None,
                        domain: Domain::Range {
                            lower: Box::new(integer(if name == "Nat" {
                                0
                            } else {
                                i32::MIN as i64
                            })?),
                            upper: Box::new(integer(i32::MAX as i64)?),
                        },
                    }],
                    body: Box::new(I::Bound {
                        slot: context.bound,
                    }),
                }
            }
            E::Identifier { name }
                if self.has(context, name) && !context.locals.contains_key(name) =>
            {
                self.shared_purpose_ir(name, &[], context, true)?
            }
            E::Apply { operator, args } if self.has(context, operator) => {
                self.shared_purpose_ir(operator, args, context, true)?
            }
            E::Apply { operator, args }
                if operator == "Seq" && args.len() == 1 && self.extends("Sequences") =>
            {
                I::SequenceSet {
                    argument: Box::new(self.membership_ir(&args[0], &child)?),
                }
            }
            E::FunctionSet { domain, range } => I::FunctionSet {
                left: Box::new(self.expression_ir(domain, &child)?),
                right: Box::new(self.membership_ir(range, &child)?),
            },
            E::RecordSet { fields } => I::RecordSet {
                fields: fields
                    .iter()
                    .map(|field| {
                        Ok((
                            field.name.clone(),
                            self.membership_ir(&field.value, &child)?,
                        ))
                    })
                    .collect::<Result<_>>()?,
            },
            _ => self.expression_ir(value, context)?,
        })
    }
    fn membership_test_ir(&mut self, left: I, value: &Expression, context: &Context) -> Result<I> {
        if match &value.node {
            E::Identifier { name } => self.has(context, name) || context.locals.contains_key(name),
            E::Apply { operator, .. } => self.has(context, operator),
            _ => false,
        } {
            return Ok(I::FunctionIn {
                left: Box::new(left),
                right: Box::new(self.membership_ir(value, context)?),
            });
        }
        Ok(match &value.node {
            E::Apply { operator, args }
                if operator == "Seq" && args.len() == 1 && self.extends("Sequences") =>
            {
                I::SequenceIn {
                    left: Box::new(left),
                    right: Box::new(self.membership_ir(&args[0], &context.nested()?)?),
                }
            }
            E::RecordSet { .. } | E::FunctionSet { .. } => I::FunctionIn {
                left: Box::new(left),
                right: Box::new(self.membership_ir(value, &context.nested()?)?),
            },
            E::Apply { operator, args } if operator == "SUBSET" && args.len() == 1 => {
                I::FunctionIn {
                    left: Box::new(left),
                    right: Box::new(I::Powerset {
                        argument: Box::new(self.expression_ir(&args[0], context)?),
                    }),
                }
            }
            _ => I::In {
                value: Box::new(left),
                domain: self.domain_ir(value, context, false)?,
            },
        })
    }
    fn fold_ir(
        &mut self,
        sequence: bool,
        args: &[Expression],
        context: &Context,
        child: &Context,
    ) -> Result<I> {
        let E::Identifier { name } = &args[0].node else {
            return unsupported("fold operator argument");
        };
        if context.locals.contains_key(name) {
            return unsupported(format!("fold operator {name}"));
        }
        let entry = self.scopes[context.scope]
            .get(name)
            .cloned()
            .ok_or_else(|| CompileError {
                message: format!("operator {name}"),
            })?;
        if !entry.definition.is_recursive && context.call_ids.contains(&entry.id) {
            return unsupported(format!("fold operator {name}"));
        }
        let DefinitionKind::Operator { params } = &entry.definition.head else {
            return unsupported(format!("fold operator {name}"));
        };
        if params.len() != 2 || params.iter().any(|param| param.arity != 0) {
            return unsupported(format!("fold operator {name}"));
        }
        let accumulator = context.bound;
        if accumulator + 2 > 40 {
            return unsupported("more than 40 bound variables");
        }
        let initial = Box::new(self.expression_ir(&args[1], child)?);
        let collection = Box::new(self.expression_ir(&args[2], child)?);
        let body = Box::new(self.shared_arguments_ir(
            name,
            vec![
                I::Bound { slot: accumulator },
                I::Bound {
                    slot: accumulator + 1,
                },
            ],
            context,
            false,
            BTreeMap::new(),
        )?);
        Ok(I::Fold {
            accumulator,
            initial,
            collection,
            body,
            order: if sequence {
                ir::FoldOrder::SequenceLeft
            } else {
                ir::FoldOrder::SetMembers
            },
        })
    }
    fn apply_ir(
        &mut self,
        operator: &str,
        args: &[Expression],
        context: &Context,
        child: &Context,
    ) -> Result<I> {
        if self.has(context, operator) {
            return self.shared_ir(operator, args, context);
        }
        if (operator == "SelectSeq" && self.extends("Sequences"))
            || (operator == "SortSeq" && self.extends("TLC"))
        {
            if args.len() != 2 {
                return unsupported(format!("operator arity {operator}"));
            }
            let arity = if operator == "SortSeq" { 2 } else { 1 };
            let E::Identifier { name } = &args[1].node else {
                return unsupported("callback operator argument");
            };
            if context.locals.contains_key(name) || context.bound + arity > 40 {
                return unsupported(format!("callback operator {name}"));
            }
            let body = Box::new(
                self.shared_arguments_ir(
                    name,
                    (0..arity)
                        .map(|index| I::Bound {
                            slot: context.bound + index,
                        })
                        .collect(),
                    context,
                    false,
                    BTreeMap::new(),
                )?,
            );
            let sequence = Box::new(self.expression_ir(&args[0], child)?);
            return Ok(if arity == 1 {
                I::SelectSeq {
                    slot: context.bound,
                    sequence,
                    body,
                }
            } else {
                I::SortSeq {
                    slot: context.bound,
                    sequence,
                    body,
                }
            });
        }
        if operator == "Assert" && self.extends("TLC") {
            if args.len() != 2 {
                return unsupported("operator arity Assert");
            }
            return Ok(I::Assert {
                condition: Box::new(self.expression_ir(&args[0], child)?),
                message: Box::new(self.expression_ir(&args[1], child)?),
            });
        }
        if self.extends("Apalache") && ["ApaFoldSet", "ApaFoldSeqLeft"].contains(&operator) {
            if args.len() != 3 {
                return unsupported("fold arity");
            }
            return self.fold_ir(operator == "ApaFoldSeqLeft", args, context, child);
        }
        if self.extends("Variants") {
            match operator {
                "Variant" if args.len() == 2 => {
                    if context.bound >= 256 {
                        return unsupported("too many bound variables");
                    }
                    let tag = self.expression_ir(&args[0], child)?;
                    let payload = self.expression_ir(
                        &args[1],
                        &Context {
                            bound: context.bound + 1,
                            ..child.clone()
                        },
                    )?;
                    return Ok(I::Function {
                        bounds: vec![ir::Binding {
                            slot: context.bound,
                            tuple_size: None,
                            domain: Domain::Set { values: vec![tag] },
                        }],
                        body: Box::new(payload),
                    });
                }
                "VariantTag" if args.len() == 1 => {
                    return Ok(I::VariantTag {
                        argument: Box::new(self.expression_ir(&args[0], child)?),
                    });
                }
                "VariantGetUnsafe" if args.len() == 2 => {
                    return Ok(I::At {
                        target: Box::new(self.expression_ir(&args[1], child)?),
                        key: Box::new(self.expression_ir(&args[0], child)?),
                    });
                }
                _ => {}
            }
        }
        if args.len() == 1 && ["-.", "-"].contains(&operator) {
            if !self.extends("Integers") {
                return unsupported("unary minus requires Integers");
            }
            if matches!(args[0].node, E::Number { value: 2147483648 }) {
                return integer(i32::MIN as i64);
            }
        }
        if args.len() == 1 && ["~", "\\lnot", "-.", "-"].contains(&operator) {
            let argument = Box::new(self.expression_ir(&args[0], child)?);
            return Ok(if ["~", "\\lnot"].contains(&operator) {
                I::Not { argument }
            } else {
                I::Neg { argument }
            });
        }
        if args.len() == 1
            && [
                "DOMAIN",
                "Cardinality",
                "Len",
                "Head",
                "Tail",
                "SUBSET",
                "UNION",
            ]
            .contains(&operator)
        {
            if ["Len", "Head", "Tail"].contains(&operator) && !self.extends("Sequences") {
                return unsupported("sequence operator requires Sequences");
            }
            if operator == "Cardinality" && !self.extends("FiniteSets") {
                return unsupported("Cardinality requires FiniteSets");
            }
            let argument = Box::new(self.expression_ir(&args[0], child)?);
            return Ok(match operator {
                "DOMAIN" => I::Domain { argument },
                "Cardinality" => I::Cardinality { argument },
                "Len" => I::Len { argument },
                "Head" => I::Head { argument },
                "Tail" => I::Tail { argument },
                "SUBSET" => I::Powerset { argument },
                "UNION" => I::Union { argument },
                _ => unreachable!(),
            });
        }
        if args.len() == 2 && ["\\in", "\\notin"].contains(&operator) {
            let left = self.expression_ir(&args[0], child)?;
            let membership = self.membership_test_ir(left, &args[1], child)?;
            return Ok(if operator == "\\notin" {
                not(membership)
            } else {
                membership
            });
        }
        if operator == "<=>" && args.len() == 2 {
            return Ok(I::Eq {
                left: Box::new(not(self.expression_ir(&args[0], child)?)),
                right: Box::new(not(self.expression_ir(&args[1], child)?)),
            });
        }
        if operator == ".." && args.len() == 2 {
            let value = Expression {
                node: E::Apply {
                    operator: operator.into(),
                    args: args.to_vec(),
                },
                location: args[0].location,
            };
            return Ok(I::MapSet {
                bounds: vec![ir::Binding {
                    slot: context.bound,
                    tuple_size: None,
                    domain: self.domain_ir(&value, child, true)?,
                }],
                body: Box::new(I::Bound {
                    slot: context.bound,
                }),
            });
        }
        if operator == "Append" && args.len() == 2 && self.extends("Sequences") {
            return Ok(I::Append {
                left: Box::new(self.expression_ir(&args[0], child)?),
                right: Box::new(self.expression_ir(&args[1], child)?),
            });
        }
        if operator == "SubSeq" && args.len() == 3 && self.extends("Sequences") {
            return Ok(I::Subseq {
                sequence: Box::new(self.expression_ir(&args[0], child)?),
                from: Box::new(self.expression_ir(&args[1], child)?),
                to: Box::new(self.expression_ir(&args[2], child)?),
            });
        }
        let op = match operator {
            "+" => "add",
            "-" => "sub",
            "*" => "mul",
            "\\div" => "div",
            "%" => "mod",
            "^" => "pow",
            "=" => "eq",
            ":=" if self.extends("Apalache") => "eq",
            "#" | "/=" => "ne",
            "<" => "lt",
            "<=" | "\\leq" => "le",
            ">" => "gt",
            ">=" | "\\geq" => "ge",
            "=>" => "implies",
            "\\cup" | "\\union" => "cup",
            "\\cap" | "\\intersect" => "cap",
            "\\" => "difference",
            "\\subseteq" => "subset-eq",
            "\\o" => "concat",
            _ => return unsupported(format!("operator {operator}")),
        };
        if args.len() != 2 {
            return unsupported(format!("operator arity {operator}"));
        }
        if [
            "add", "sub", "mul", "div", "mod", "pow", "lt", "le", "gt", "ge",
        ]
        .contains(&op)
            && !self.arithmetic()
        {
            return unsupported("arithmetic requires Naturals");
        }
        if op == "concat" && !self.extends("Sequences") {
            return unsupported("concatenation requires Sequences");
        }
        let left = Box::new(self.expression_ir(&args[0], child)?);
        let right = Box::new(self.expression_ir(&args[1], child)?);
        Ok(match op {
            "add" => I::Add { left, right },
            "sub" => I::Sub { left, right },
            "mul" => I::Mul { left, right },
            "div" => I::Div { left, right },
            "mod" => I::Mod { left, right },
            "pow" => I::Pow { left, right },
            "eq" => I::Eq { left, right },
            "ne" => I::Ne { left, right },
            "lt" => I::Lt { left, right },
            "le" => I::Le { left, right },
            "gt" => I::Gt { left, right },
            "ge" => I::Ge { left, right },
            "implies" => I::Implies { left, right },
            "cup" => I::Cup { left, right },
            "cap" => I::Cap { left, right },
            "difference" => I::Difference { left, right },
            "subset-eq" => I::SubsetEq { left, right },
            "concat" => I::Concat { left, right },
            _ => unreachable!(),
        })
    }
    pub(super) fn target_ir(target: &Target) -> Result<I> {
        Ok(match target {
            Target::Slot(slot) => I::Read {
                slot: *slot,
                next: false,
            },
            Target::Tuple(values) => I::Tuple {
                values: values.iter().map(Self::target_ir).collect::<Result<_>>()?,
            },
            Target::Binding(_) => {
                return unsupported("generative UNCHANGED requires state variables");
            }
        })
    }
    pub(super) fn variable_reads_ir(
        &mut self,
        value: I,
        message: &str,
        depth: usize,
    ) -> Result<Vec<I>> {
        if self.target_nesting >= 40 {
            return unsupported("expression or operator nesting exceeds 40");
        }
        self.target_nesting += 1;
        self.lower_pending()?;
        struct Frame {
            definition: Option<usize>,
            arguments: Vec<I>,
            captures: Vec<I>,
            parent: Option<usize>,
            depth: usize,
        }
        let mut frames: Vec<Frame> = vec![];
        let mut pending: Vec<(I, Option<usize>, usize)> = vec![(value, None, depth)];
        let mut reads = vec![];
        let mut visited = 0;
        while let Some((value, frame, depth)) = pending.pop() {
            if visited == crate::TARGET_EXPANSION_LIMIT {
                return unsupported(format!(
                    "target expansion exceeds {} nodes",
                    crate::TARGET_EXPANSION_LIMIT
                ));
            }
            visited += 1;
            if depth >= 40 {
                return unsupported("expression or operator nesting exceeds 40");
            }
            let children = analysis_children(Node::Expression(&value));
            match &value {
                I::Tuple { .. } => pending.extend(children.into_iter().rev().filter_map(|edge| {
                    if let Node::Expression(value) = edge.node {
                        Some((value.clone(), frame, depth + 1))
                    } else {
                        None
                    }
                })),
                I::Read { next: false, .. } => reads.push(value),
                I::Call { definition, .. } => {
                    let mut ancestor = frame;
                    while let Some(index) = ancestor {
                        if frames[index].definition == Some(*definition) {
                            return unsupported("recursive operator definitions");
                        }
                        ancestor = frames[index].parent;
                    }
                    self.lower_definition(*definition)?;
                    let next = frames.len();
                    frames.push(Frame {
                        definition: Some(*definition),
                        arguments: children
                            .iter()
                            .filter(|edge| edge.descriptor.role == "call-actual")
                            .filter_map(|edge| {
                                if let Node::Expression(value) = edge.node {
                                    Some(value.clone())
                                } else {
                                    None
                                }
                            })
                            .collect(),
                        captures: children
                            .iter()
                            .filter(|edge| edge.descriptor.role == "call-capture")
                            .filter_map(|edge| {
                                if let Node::Expression(value) = edge.node {
                                    Some(value.clone())
                                } else {
                                    None
                                }
                            })
                            .collect(),
                        parent: frame,
                        depth,
                    });
                    let ir::DefinitionBody::Expression(body) =
                        &self.shared[*definition].definition.as_ref().unwrap().body
                    else {
                        return unsupported("generative UNCHANGED requires state variables");
                    };
                    pending.push((body.clone(), Some(next), depth + 1));
                }
                I::Frame { .. } => {
                    let next = frames.len();
                    frames.push(Frame {
                        definition: None,
                        arguments: children
                            .iter()
                            .filter(|edge| edge.descriptor.role == "frame-actual")
                            .filter_map(|edge| {
                                if let Node::Expression(value) = edge.node {
                                    Some(value.clone())
                                } else {
                                    None
                                }
                            })
                            .collect(),
                        captures: children
                            .iter()
                            .filter(|edge| edge.descriptor.role == "frame-capture")
                            .filter_map(|edge| {
                                if let Node::Expression(value) = edge.node {
                                    Some(value.clone())
                                } else {
                                    None
                                }
                            })
                            .collect(),
                        parent: frame,
                        depth,
                    });
                    for edge in children
                        .into_iter()
                        .filter(|edge| edge.descriptor.role == "frame-body")
                    {
                        if let Node::Expression(value) = edge.node {
                            pending.push((value.clone(), Some(next), depth + 1));
                        }
                    }
                }
                I::Parameter { slot } | I::Capture { slot } => {
                    let frame =
                        frame
                            .and_then(|id| frames.get(id))
                            .ok_or_else(|| CompileError {
                                message: message.into(),
                            })?;
                    let actuals = if matches!(value, I::Parameter { .. }) {
                        &frame.arguments
                    } else {
                        &frame.captures
                    };
                    let actual = actuals.get(*slot).ok_or_else(|| CompileError {
                        message: message.into(),
                    })?;
                    pending.push((actual.clone(), frame.parent, frame.depth + 1));
                }
                _ => return unsupported(message),
            }
        }
        self.target_nesting -= 1;
        Ok(reads)
    }
}

use crate::{
    AnonymousFrame, CompileError, Compiler, Context, DefinitionKind, E, Expression, Phase, Result,
    unsupported,
};
use crate::{
    analysis::{Node, NodeMut, analysis_children},
    typed,
};
use rtlc::ir::{self, Expression as I, Step, TemporalFormula as T};
use std::collections::HashSet;

fn branch(name: &str, steps: Vec<Step>) -> ir::Branch {
    ir::Branch {
        name: name.into(),
        steps,
    }
}
fn guard(expression: I) -> Step {
    Step::Guard { expression }
}
fn not(argument: I) -> I {
    I::Not {
        argument: Box::new(argument),
    }
}
fn atom(expression: I) -> T {
    T::Atom { expression }
}
fn atom_parts(mut formula: T) -> std::result::Result<I, T> {
    if let T::Atom { expression } = &mut formula {
        Ok(std::mem::replace(expression, I::Old))
    } else {
        typed::atom_expression(&formula).ok_or(formula)
    }
}
fn negate(formula: T) -> T {
    match atom_parts(formula) {
        Ok(expression) => atom(not(expression)),
        Err(formula) => T::Not {
            formula: Box::new(formula),
        },
    }
}
fn connective(and: bool, left: I, right: I) -> I {
    if and {
        I::And {
            left: Box::new(left),
            right: Box::new(right),
        }
    } else {
        I::Or {
            left: Box::new(left),
            right: Box::new(right),
        }
    }
}
fn structural(and: bool, left: T, right: T) -> T {
    if and {
        T::And {
            left: Box::new(left),
            right: Box::new(right),
        }
    } else {
        T::Or {
            left: Box::new(left),
            right: Box::new(right),
        }
    }
}
fn combine(and: bool, left: T, right: T) -> T {
    match typed::atom_expression(&right) {
        Some(right_expression) => match atom_parts(left) {
            Ok(left_expression) => atom(connective(and, left_expression, right_expression)),
            Err(left) => structural(and, left, right),
        },
        None => structural(and, left, right),
    }
}
fn frame_actuals(frame: &AnonymousFrame) -> Result<(Vec<I>, Vec<I>)> {
    for value in frame.arguments.iter().chain(&frame.captures) {
        typed::check_depth_from(Node::Expression(value), 1)?;
    }
    Ok((frame.arguments.clone(), frame.captures.clone()))
}
fn frame_step(frame: &AnonymousFrame, branches: Vec<ir::Branch>) -> Result<Step> {
    for branch in &branches {
        typed::check_depth_from(Node::Branch(branch), 1)?;
    }
    let (arguments, captures) = frame_actuals(frame)?;
    let mut step = Step::Frame {
        parameter_count: arguments.len(),
        capture_count: captures.len(),
        local_scope: 0,
        arguments,
        captures,
        branches,
    };
    typed::compact_anonymous(NodeMut::Step(&mut step));
    Ok(step)
}
fn frame_expression(frame: &AnonymousFrame, body: I) -> Result<I> {
    typed::check_depth_from(Node::Expression(&body), 1)?;
    let (arguments, captures) = frame_actuals(frame)?;
    let mut expression = I::Frame {
        parameter_count: arguments.len(),
        capture_count: captures.len(),
        local_scope: typed::local_scope(Node::Expression(&body)),
        arguments,
        captures,
        body: Box::new(body),
    };
    typed::compact_anonymous(NodeMut::Expression(&mut expression));
    Ok(expression)
}
fn frame_formula(frame: &AnonymousFrame, formula: T) -> Result<T> {
    typed::check_depth_from(Node::Temporal(&formula), 1)?;
    let (arguments, captures) = frame_actuals(frame)?;
    let mut formula = T::Frame {
        parameter_count: arguments.len(),
        capture_count: captures.len(),
        local_scope: 0,
        arguments,
        captures,
        formula: Box::new(formula),
    };
    typed::compact_anonymous(NodeMut::Temporal(&mut formula));
    Ok(formula)
}
fn unchanged(value: I) -> Result<Vec<Step>> {
    let children = analysis_children(Node::Expression(&value));
    match &value {
        I::Tuple { .. } => children.into_iter().try_fold(vec![], |mut steps, edge| {
            if let Node::Expression(value) = edge.node {
                steps.extend(unchanged(value.clone())?);
            }
            Ok(steps)
        }),
        I::Read { slot, next: false } => Ok(vec![Step::Assign { slot: *slot, value }]),
        _ => unsupported("generative UNCHANGED requires state variables"),
    }
}
impl Compiler<'_> {
    fn target_reads_ir(&mut self, value: &Expression, context: &Context) -> Result<Vec<I>> {
        let target = Self::target_ir(&self.resolve_target_within(value, context, 256)?)?;
        self.variable_reads_ir(target, "generative UNCHANGED requires state variables", 0)
    }
    pub(super) fn action_ir(
        &mut self,
        value: &Expression,
        context: &Context,
        name: &str,
    ) -> Result<Vec<ir::Branch>> {
        let child = context.nested()?;
        match &value.node {
            E::BoxAction { action, subscript } | E::AngleAction { action, subscript }
                if context.phase == Phase::Next =>
            {
                let target = Self::target_ir(&self.resolve_target(subscript, context)?)?;
                let mut branches = self.action_ir(action, &child, name)?;
                if matches!(value.node, E::BoxAction { .. }) {
                    let mut steps = vec![];
                    for read in self.variable_reads_ir(
                        target,
                        "generative UNCHANGED requires state variables",
                        0,
                    )? {
                        steps.extend(unchanged(read)?);
                    }
                    branches.push(branch(name, steps));
                } else {
                    let next = self.prime_ir(target.clone())?;
                    let expression = I::Ne {
                        left: Box::new(target),
                        right: Box::new(next),
                    };
                    for branch in &mut branches {
                        branch.steps.push(guard(expression.clone()));
                    }
                }
                typed::limited(branches)
            }
            E::Identifier { name } if self.has(context, name) => {
                self.action_call_ir(name, &[], context)
            }
            E::Apply { operator, args } if self.has(context, operator) => {
                self.action_call_ir(operator, args, context)
            }
            E::Let { definitions, body } => {
                let expanded = self.let_context(definitions, context)?;
                self.action_ir(body, &expanded, name)
            }
            E::Label { body, .. } => self.action_ir(body, &child, name),
            E::Exists { bounds, body } => {
                let (bindings, bound) = self.bind_ir(bounds, &child)?;
                let prefix: Vec<_> = bindings
                    .into_iter()
                    .map(|binding| Step::Bind {
                        slot: binding.slot,
                        tuple_size: binding.tuple_size,
                        domain: binding.domain,
                    })
                    .collect();
                let mut branches = self.action_ir(body, &bound, name)?;
                for branch in &mut branches {
                    branch.steps.splice(0..0, prefix.clone());
                }
                typed::limited(branches)
            }
            E::Or { operands, .. } => {
                let mut result = vec![];
                for operand in operands {
                    result.extend(self.action_ir(operand, &child, name)?);
                    result = typed::limited(result)?;
                }
                Ok(result)
            }
            E::And { operands, .. } => {
                let mut result = vec![branch(name, vec![])];
                for operand in operands {
                    let mut next = vec![];
                    for branch in &result {
                        let bound = context.bound
                            + branch
                                .steps
                                .iter()
                                .filter(|step| matches!(step, Step::Bind { .. }))
                                .count();
                        for mut addition in self.action_ir(
                            operand,
                            &Context {
                                bound,
                                ..child.clone()
                            },
                            name,
                        )? {
                            addition.steps.splice(0..0, branch.steps.clone());
                            next.push(addition);
                            if next.len() > 4096 {
                                return unsupported("action expansion exceeds 4096 branches");
                            }
                        }
                    }
                    result = typed::limited(next)?;
                }
                Ok(result)
            }
            E::If {
                condition,
                consequent,
                alternative,
            } => {
                let condition = self.expression_ir(condition, &child)?;
                let mut result = vec![];
                for (body, condition) in [
                    (consequent, condition.clone()),
                    (alternative, not(condition)),
                ] {
                    for mut branch in self.action_ir(body, &child, name)? {
                        branch.steps.insert(0, guard(condition.clone()));
                        result.push(branch);
                    }
                }
                typed::limited(result)
            }
            E::Case { arms, other } if !arms.is_empty() => {
                let mut result = vec![];
                let mut previous: Vec<I> = vec![];
                for arm in arms {
                    let condition = self.expression_ir(&arm.condition, &child)?;
                    let mut guards: Vec<_> = previous.iter().cloned().map(not).map(guard).collect();
                    guards.push(guard(condition.clone()));
                    for mut branch in self.action_ir(&arm.body, &child, name)? {
                        branch.steps.splice(0..0, guards.clone());
                        result.push(branch);
                    }
                    previous.push(condition);
                    result = typed::limited(result)?;
                }
                let guards: Vec<_> = previous.into_iter().map(not).map(guard).collect();
                if let Some(other) = other {
                    for mut branch in self.action_ir(other, &child, name)? {
                        branch.steps.splice(0..0, guards.clone());
                        result.push(branch);
                    }
                } else {
                    let mut steps = guards;
                    steps.push(guard(I::UnmatchedCase {
                        location: format!(
                            "line {}, column {}",
                            value.location.line, value.location.column
                        ),
                    }));
                    result.push(branch(name, steps));
                }
                typed::limited(result)
            }
            E::Unchanged { expression } if context.phase == Phase::Next => {
                let mut steps = vec![];
                for read in self.target_reads_ir(expression, &child)? {
                    steps.extend(unchanged(read)?);
                }
                Ok(vec![branch(name, steps)])
            }
            E::Apply { operator, args } if args.len() == 2 => {
                let equality = operator == "=" || operator == ":=" && self.extends("Apalache");
                if let Some(slot) = self.target(&args[0], context) {
                    if equality {
                        return Ok(vec![branch(
                            name,
                            vec![Step::Assign {
                                slot,
                                value: self.expression_ir(&args[1], &child)?,
                            }],
                        )]);
                    }
                    if operator == "\\in" {
                        return Ok(vec![branch(
                            name,
                            vec![Step::Choose {
                                slot,
                                domain: self.domain_ir(&args[1], &child, true)?,
                            }],
                        )]);
                    }
                }
                if equality && let Some(slot) = self.target(&args[1], context) {
                    return Ok(vec![branch(
                        name,
                        vec![Step::Assign {
                            slot,
                            value: self.expression_ir(&args[0], &child)?,
                        }],
                    )]);
                }
                Ok(vec![branch(
                    name,
                    vec![guard(self.expression_ir(value, context)?)],
                )])
            }
            _ => Ok(vec![branch(
                name,
                vec![guard(self.expression_ir(value, context)?)],
            )]),
        }
    }
    fn template_expression<'a>(&'a self, mut formula: &'a T, mut always: bool) -> Option<I> {
        let mut frames = vec![];
        loop {
            if frames.len() > 128 {
                return None;
            }
            match formula {
                T::Call {
                    definition,
                    arguments,
                    captures,
                } => {
                    let definition = self.shared.get(*definition)?.definition.as_ref()?;
                    let ir::DefinitionBody::Temporal(body) = &definition.body else {
                        return None;
                    };
                    frames.push((
                        arguments.clone(),
                        captures.clone(),
                        definition.parameter_count,
                        definition.capture_count,
                        definition.local_scope,
                    ));
                    formula = body;
                }
                T::Frame {
                    arguments,
                    captures,
                    parameter_count,
                    capture_count,
                    local_scope,
                    formula: body,
                } => {
                    frames.push((
                        arguments.clone(),
                        captures.clone(),
                        *parameter_count,
                        *capture_count,
                        *local_scope,
                    ));
                    formula = body;
                }
                T::Always { formula: body } if always => {
                    always = false;
                    formula = body;
                }
                T::Atom { expression } if !always => {
                    let mut expression = expression.clone();
                    for (arguments, captures, parameter_count, capture_count, local_scope) in
                        frames.into_iter().rev()
                    {
                        expression = I::Frame {
                            arguments,
                            captures,
                            parameter_count,
                            capture_count,
                            local_scope,
                            body: Box::new(expression),
                        };
                    }
                    return Some(expression);
                }
                _ => return None,
            }
        }
    }
    fn template_frame(&self, name: &str, context: &Context) -> bool {
        let entry = &self.scopes[context.scope][name];
        context.bound > 0
            || !entry.projection.is_empty()
            || matches!(&entry.definition.head, DefinitionKind::Operator { params } if !params.is_empty())
    }
    fn template_call(
        &mut self,
        name: &str,
        args: &[Expression],
        context: &Context,
        kind: ir::BodyKind,
    ) -> Result<I> {
        let child = context.nested()?;
        let position = self.scopes[context.scope][name].id;
        let demanded = self.membership_demands(name, context, false)?;
        let mut arguments = vec![];
        for (slot, value) in args.iter().enumerate() {
            let binding = self.binding_id(position, 0, slot);
            arguments.push(if demanded.contains(&binding) {
                self.membership_ir(value, &child)?
            } else {
                self.expression_ir(value, &child)?
            });
        }
        let targets =
            self.call_targets_purpose(name, args, context, kind == ir::BodyKind::Action)?;
        self.shared_body_ir(name, arguments, context, false, targets, kind)
    }
    fn action_call_ir(
        &mut self,
        name: &str,
        args: &[Expression],
        context: &Context,
    ) -> Result<Vec<ir::Branch>> {
        if !self.generative_call(name, context, &mut HashSet::new())? {
            return Ok(vec![branch(
                name,
                vec![guard(self.shared_ir(name, args, context)?)],
            )]);
        }
        if self.scopes[context.scope][name].definition.is_recursive
            || self.template_frame(name, context)
        {
            let mut call = self.template_call(name, args, context, ir::BodyKind::Action)?;
            let I::Call {
                definition,
                arguments,
                captures,
            } = &mut call
            else {
                unreachable!()
            };
            let step = Step::Call {
                definition: *definition,
                arguments: std::mem::take(arguments),
                captures: std::mem::take(captures),
            };
            return Ok(vec![branch(name, vec![step])]);
        }
        let (body, expanded) = self.call(name, args, context)?;
        let branches = self.action_ir(&body, &expanded, name)?;
        if let Some(frame) = &expanded.frame {
            typed::limited(vec![branch(name, vec![frame_step(frame, branches)?])])
        } else {
            Ok(branches)
        }
    }
    pub(super) fn temporal_ir(&mut self, value: &Expression, context: &Context) -> Result<T> {
        let child = context.nested()?;
        match &value.node {
            E::Forall { bounds, body } | E::Exists { bounds, body } => {
                let (bindings, bound) = self.bind_ir(bounds, &child)?;
                let formula = self.temporal_ir(body, &bound)?;
                if typed::atom_expression(&formula).is_some() {
                    return Ok(atom(self.expression_ir(value, &child)?));
                }
                self.lower_pending()?;
                let bounds = bindings;
                if bounds.iter().any(|bound| {
                    typed::level_summary(Node::Domain(&bound.domain), &self.level_cache.borrow())
                        .base
                        > 0
                }) {
                    return unsupported("temporal quantification requires constant finite domains");
                }
                Ok(if matches!(value.node, E::Forall { .. }) {
                    T::Forall {
                        bounds,
                        formula: Box::new(formula),
                    }
                } else {
                    T::Exists {
                        bounds,
                        formula: Box::new(formula),
                    }
                })
            }
            E::Identifier { name } if self.has(context, name) => {
                self.temporal_call_ir(name, &[], context)
            }
            E::Apply { operator, args } if self.has(context, operator) => {
                self.temporal_call_ir(operator, args, context)
            }
            E::Let { definitions, body } => {
                let expanded = self.let_context(definitions, context)?;
                self.temporal_ir(body, &expanded)
            }
            E::Always { expression } | E::Eventually { expression } => {
                let formula = self.temporal_ir(expression, &child)?;
                self.lower_pending()?;
                let always = matches!(value.node, E::Always { .. });
                if always && let Some(mut body) = typed::atom_expression(&formula) {
                    for frame in context.temporal_frames.iter().rev() {
                        body = frame_expression(frame, body)?;
                    }
                    if typed::level_summary(Node::Expression(&body), &self.level_cache.borrow())
                        .base
                        > 1
                        && !self.boxed_action(expression, &child)?
                    {
                        return unsupported("[] action must have the form [A]_v");
                    }
                }
                Ok(if always {
                    T::Always {
                        formula: Box::new(formula),
                    }
                } else {
                    T::Eventually {
                        formula: Box::new(formula),
                    }
                })
            }
            E::And { operands, .. } | E::Or { operands, .. } => {
                let and = matches!(value.node, E::And { .. });
                let mut result = atom(I::Literal {
                    value: ir::Scalar::Bool(and),
                });
                for operand in operands {
                    result = combine(and, result, self.temporal_ir(operand, &child)?);
                }
                Ok(result)
            }
            E::Apply { operator, args }
                if args.len() == 1 && ["~", "\\lnot"].contains(&operator.as_str()) =>
            {
                Ok(negate(self.temporal_ir(&args[0], &child)?))
            }
            E::Apply { operator, args }
                if args.len() == 2 && ["=>", "~>"].contains(&operator.as_str()) =>
            {
                let right = self.temporal_ir(&args[1], &child)?;
                let result = combine(
                    false,
                    negate(self.temporal_ir(&args[0], &child)?),
                    if operator == "~>" {
                        T::Eventually {
                            formula: Box::new(right),
                        }
                    } else {
                        right
                    },
                );
                Ok(if operator == "~>" {
                    T::Always {
                        formula: Box::new(result),
                    }
                } else {
                    result
                })
            }
            E::WeakFairness { action, subscript } | E::StrongFairness { action, subscript } => {
                let subscript = self.expression_ir(subscript, &child)?;
                let enabled = atom(I::Enabled {
                    branches: self.action_ir(action, &child, "fairness")?,
                    subscript: Some(Box::new(subscript.clone())),
                });
                let disabled = T::Not {
                    formula: Box::new(enabled),
                };
                let primed = self.prime_ir(subscript.clone())?;
                let taken = atom(I::And {
                    left: Box::new(self.expression_ir(action, &child)?),
                    right: Box::new(I::Ne {
                        left: Box::new(subscript),
                        right: Box::new(primed),
                    }),
                });
                Ok(if matches!(value.node, E::WeakFairness { .. }) {
                    T::Always {
                        formula: Box::new(T::Eventually {
                            formula: Box::new(T::Or {
                                left: Box::new(disabled),
                                right: Box::new(taken),
                            }),
                        }),
                    }
                } else {
                    T::Or {
                        left: Box::new(T::Eventually {
                            formula: Box::new(T::Always {
                                formula: Box::new(disabled),
                            }),
                        }),
                        right: Box::new(T::Always {
                            formula: Box::new(T::Eventually {
                                formula: Box::new(taken),
                            }),
                        }),
                    }
                })
            }
            _ => Ok(atom(self.expression_ir(value, context)?)),
        }
    }
    fn temporal_call_ir(
        &mut self,
        name: &str,
        args: &[Expression],
        context: &Context,
    ) -> Result<T> {
        if self.scopes[context.scope][name].definition.is_recursive {
            return Ok(atom(self.shared_ir(name, args, context)?));
        }
        if self
            .temporal_ids
            .contains(&self.scopes[context.scope][name].id)
            && self.template_frame(name, context)
        {
            let mut call = self.template_call(name, args, context, ir::BodyKind::Temporal)?;
            let I::Call {
                definition,
                arguments,
                captures,
            } = &mut call
            else {
                unreachable!()
            };
            return Ok(T::Call {
                definition: *definition,
                arguments: std::mem::take(arguments),
                captures: std::mem::take(captures),
            });
        }
        let (body, expanded) = self.call(name, args, context)?;
        let formula = self.temporal_ir(&body, &expanded)?;
        if let Some(frame) = &expanded.frame {
            frame_formula(frame, formula)
        } else {
            Ok(formula)
        }
    }
}

impl Compiler<'_> {
    fn parts_ir(
        &mut self,
        value: &Expression,
        context: &Context,
        initial: &mut Option<Vec<ir::Branch>>,
        next: &mut Option<Vec<ir::Branch>>,
        fairness: &mut Vec<T>,
    ) -> Result<()> {
        if matches!(value.node, E::Forall { .. } | E::Exists { .. }) {
            let formula = self.temporal_ir(value, context)?;
            if !matches!(formula, T::Atom { .. }) {
                fairness.push(formula);
                return Ok(());
            }
        }
        match &value.node {
            E::Identifier { name } if self.has(context, name) => {
                let (body, expanded) = self.call(name, &[], context)?;
                self.parts_ir(&body, &expanded, initial, next, fairness)
            }
            E::Apply { operator, args } if self.has(context, operator) => {
                for argument in args {
                    let mut expression = self.expression_ir(argument, context)?;
                    for frame in context.temporal_frames.iter().rev() {
                        expression = frame_expression(frame, expression)?;
                    }
                    self.lower_pending()?;
                    if typed::level_summary(
                        Node::Expression(&expression),
                        &self.level_cache.borrow(),
                    )
                    .base
                        > 0
                    {
                        return unsupported("SPECIFICATION operator arguments must be constant");
                    }
                }
                let (body, expanded) = self.call(operator, args, context)?;
                let mut local_initial = None;
                let mut local_next = None;
                let mut local_fairness = vec![];
                self.parts_ir(
                    &body,
                    &expanded,
                    &mut local_initial,
                    &mut local_next,
                    &mut local_fairness,
                )?;
                if let Some(frame) = &expanded.frame {
                    if let Some(branches) = local_initial.take() {
                        local_initial =
                            Some(vec![branch("Init", vec![frame_step(frame, branches)?])]);
                    }
                    if let Some(branches) = local_next.take() {
                        local_next = Some(vec![branch("Next", vec![frame_step(frame, branches)?])]);
                    }
                    local_fairness = local_fairness
                        .into_iter()
                        .map(|formula| frame_formula(frame, formula))
                        .collect::<Result<_>>()?;
                }
                if let Some(branches) = local_initial {
                    *initial = Some(if let Some(previous) = initial.take() {
                        let mut joined = vec![];
                        for before in &previous {
                            for after in &branches {
                                let mut branch = after.clone();
                                branch.steps.splice(0..0, before.steps.clone());
                                joined.push(branch);
                            }
                        }
                        typed::limited(joined)?
                    } else {
                        branches
                    });
                }
                if let Some(branches) = local_next {
                    if next.is_some() {
                        return unsupported("multiple NEXT conjuncts");
                    }
                    *next = Some(branches);
                }
                fairness.extend(local_fairness);
                Ok(())
            }
            E::And { .. } => {
                for edge in analysis_children(Node::Source(value))
                    .into_iter()
                    .filter(|edge| edge.descriptor.action == "inherit")
                {
                    if let Node::Source(operand) = edge.node {
                        self.parts_ir(operand, &context.nested()?, initial, next, fairness)?;
                    }
                }
                Ok(())
            }
            E::Always { expression } if matches!(expression.node, E::BoxAction { .. }) => {
                if next.is_some() {
                    return unsupported("multiple NEXT conjuncts");
                }
                let children = analysis_children(Node::Source(expression));
                let action = children
                    .iter()
                    .find_map(|edge| {
                        if edge.descriptor.role == "action-body" {
                            if let Node::Source(value) = edge.node {
                                Some(value)
                            } else {
                                None
                            }
                        } else {
                            None
                        }
                    })
                    .ok_or_else(|| CompileError {
                        message: "SPECIFICATION action".into(),
                    })?;
                let subscript = children
                    .iter()
                    .find_map(|edge| {
                        if edge.descriptor.role == "subscript" {
                            if let Node::Source(value) = edge.node {
                                Some(value)
                            } else {
                                None
                            }
                        } else {
                            None
                        }
                    })
                    .ok_or_else(|| CompileError {
                        message: "SPECIFICATION subscript".into(),
                    })?;
                let subscript = self.expression_ir(subscript, context)?;
                let mut reads = HashSet::new();
                for value in self.variable_reads_ir(
                    subscript,
                    "SPECIFICATION subscript must list state variables",
                    context.depth,
                )? {
                    read_slots(&value, &mut reads)?;
                }
                if reads.len() != self.slots.len() {
                    return unsupported("SPECIFICATION subscript must cover every state variable");
                }
                *next = Some(self.action_ir(action, context, "Next")?);
                Ok(())
            }
            E::WeakFairness { .. } | E::StrongFairness { .. } => {
                fairness.push(self.temporal_ir(value, context)?);
                Ok(())
            }
            _ => {
                let additions = self.action_ir(
                    value,
                    &Context {
                        phase: Phase::Initial,
                        ..context.clone()
                    },
                    "Init",
                )?;
                *initial = Some(if let Some(previous) = initial.take() {
                    let mut result = vec![];
                    for branch in &previous {
                        for addition in &additions {
                            let mut joined = addition.clone();
                            joined.steps.splice(0..0, branch.steps.clone());
                            result.push(joined);
                            if result.len() > 4096 {
                                return unsupported("action expansion exceeds 4096 branches");
                            }
                        }
                    }
                    typed::limited(result)?
                } else {
                    additions
                });
                Ok(())
            }
        }
    }
    pub(super) fn program_ir(&mut self) -> Result<ir::SafetyProgram> {
        let mut initial = None;
        let mut next = None;
        let mut fairness = vec![];
        if let Some(name) = self.config.specification.clone() {
            let (body, context) = self.operator(&name, Phase::Next)?;
            self.parts_ir(&body, &context, &mut initial, &mut next, &mut fairness)?;
        } else {
            for (phase, name) in [
                (Phase::Initial, self.config.init.clone()),
                (Phase::Next, self.config.next.clone()),
            ] {
                let name = name.ok_or_else(|| CompileError {
                    message: "INIT / NEXT".into(),
                })?;
                let branches = if self.scopes[0][&name].definition.is_recursive {
                    self.action_call_ir(&name, &[], &self.root(phase))?
                } else {
                    let (body, context) = self.operator(&name, phase)?;
                    self.action_ir(&body, &context, &name)?
                };
                if phase == Phase::Initial {
                    initial = Some(branches);
                } else {
                    next = Some(branches);
                }
            }
        }
        let initial = initial.ok_or_else(|| CompileError {
            message: "initial predicate required".into(),
        })?;
        let next = next.ok_or_else(|| CompileError {
            message: "NEXT required".into(),
        })?;
        self.lower_pending()?;
        if !next.iter().any(|branch| {
            analysis_children(Node::Branch(branch))
                .into_iter()
                .any(|edge| {
                    if let Node::Step(step) = edge.node {
                        if let Step::Guard { expression } = step {
                            typed::level_summary(
                                Node::Expression(expression),
                                &self.level_cache.borrow(),
                            )
                            .base
                                > 0
                        } else {
                            true
                        }
                    } else {
                        false
                    }
                })
        }) {
            return unsupported("NEXT cannot be constant");
        }
        let mut program = ir::SafetyProgram {
            format: "modelt.safety-program".into(),
            version: 2,
            name: self.module.name.clone(),
            variables: self
                .module
                .variables
                .iter()
                .map(|value| value.name.clone())
                .collect(),
            initial,
            next,
            invariants: vec![],
            assumptions: vec![],
            check_deadlock: self.config.check_deadlock,
            symmetry: None,
            initial_properties: vec![],
            action_properties: vec![],
            properties: vec![],
            fairness: vec![],
            constraints: vec![],
            action_constraints: vec![],
            definitions: Some(vec![]),
        };
        for name in self.config.invariants.clone() {
            program.invariants.push(ir::Predicate {
                expression: self.shared_ir(&name, &[], &self.root(Phase::State))?,
                name,
            });
        }
        for name in self.config.properties.clone() {
            let (body, context) = self.operator(&name, Phase::Next)?;
            let formula = self.temporal_ir(&body, &context)?;
            typed::check_depth(Node::Temporal(&formula))?;
            self.lower_pending()?;
            let initial_expression = self.template_expression(&formula, false);
            let always_expression = self.template_expression(&formula, true);
            typed::validate_temporal(
                &formula,
                &[],
                always_expression.is_some(),
                &[],
                &self.level_cache.borrow(),
                &self
                    .shared
                    .iter()
                    .filter_map(|entry| entry.definition.as_ref())
                    .collect::<Vec<_>>(),
            )?;
            if let Some(expression) = initial_expression {
                if typed::level_summary(Node::Expression(&expression), &self.level_cache.borrow())
                    .base
                    > 1
                {
                    return unsupported("initial PROPERTY must be a state predicate");
                }
                program
                    .initial_properties
                    .push(ir::Predicate { name, expression });
            } else if let Some(expression) = always_expression {
                let target = if typed::level_summary(
                    Node::Expression(&expression),
                    &self.level_cache.borrow(),
                )
                .base
                    > 1
                {
                    &mut program.action_properties
                } else {
                    &mut program.invariants
                };
                target.push(ir::Predicate { name, expression });
            } else {
                program
                    .properties
                    .push(ir::TemporalProperty { name, formula });
            }
        }
        for (index, assumption) in self.module.assumptions.iter().enumerate() {
            program.assumptions.push(ir::Predicate {
                name: assumption
                    .name
                    .clone()
                    .unwrap_or_else(|| format!("ASSUME {}", index + 1)),
                expression: self
                    .expression_ir(&assumption.expression, &self.root(Phase::Constant))?,
            });
        }
        for (names, phase) in [
            (self.config.constraints.clone(), Phase::State),
            (self.config.action_constraints.clone(), Phase::Next),
        ] {
            for name in names {
                let predicate = ir::Predicate {
                    expression: self.shared_ir(&name, &[], &self.root(phase))?,
                    name,
                };
                if phase == Phase::State {
                    program.constraints.push(predicate);
                } else {
                    program.action_constraints.push(predicate);
                }
            }
        }
        if !program.properties.is_empty() {
            program.fairness = fairness;
        }
        self.finish_shared(program)
    }
}
fn read_slots(value: &I, slots: &mut HashSet<usize>) -> Result<()> {
    let children = analysis_children(Node::Expression(value));
    match value {
        I::Tuple { .. } => {
            for edge in children {
                if let Node::Expression(value) = edge.node {
                    read_slots(value, slots)?;
                }
            }
            Ok(())
        }
        I::Read { slot, next: false } => {
            slots.insert(*slot);
            Ok(())
        }
        _ => unsupported("SPECIFICATION subscript must list state variables"),
    }
}

use crate::analysis::{Node, analysis_children};
use crate::rewrite::{Rewriter, identifier};
use crate::{Result, functions, select, source, unsupported};
use rtla::ast::{Definition, DefinitionKind, Expression, ExpressionKind as E, Module};
use std::collections::{BTreeMap, BTreeSet};

fn higher(definition: &Definition) -> bool {
    matches!(&definition.head, DefinitionKind::Operator { params } if params.iter().any(|param| param.arity != 0))
}

pub(crate) fn needed(module: &Module) -> bool {
    if !module.modules.is_empty() || !module.recursive.is_empty() {
        return true;
    }
    let mut pending: Vec<_> = module
        .definitions
        .iter()
        .map(Node::SourceDefinition)
        .chain(
            module
                .assumptions
                .iter()
                .map(|assumption| Node::Source(&assumption.expression)),
        )
        .collect();
    while let Some(node) = pending.pop() {
        if matches!(node, Node::SourceDefinition(definition) if higher(definition) || functions::recursive(definition))
            || matches!(node, Node::Source(value) if matches!(value.node, E::Lambda { .. } | E::Selection { .. } | E::LetModule { .. }) || matches!(&value.node, E::Identifier { name } | E::Apply { operator: name, .. } if name.contains('!')))
        {
            return true;
        }
        if let Node::Source(value) = node
            && matches!(&value.node, E::Let { definitions, .. } if definitions.iter().any(|definition| crate::free_old(&crate::definition_body(definition))))
            && crate::old::needed(
                value,
                &module
                    .definitions
                    .iter()
                    .cloned()
                    .map(|definition| (definition.name.clone(), definition))
                    .collect(),
            )
        {
            return true;
        }
        pending.extend(analysis_children(node).into_iter().map(|edge| edge.node));
    }
    false
}

struct Elaborator {
    rewrite: Rewriter,
    active: BTreeMap<(String, Vec<String>), String>,
    depth: usize,
    generated: usize,
    names: BTreeMap<String, String>,
    actions: BTreeMap<String, String>,
    functions: BTreeMap<String, functions::Function>,
}

impl Elaborator {
    fn fresh(&mut self) -> Result<String> {
        self.generated += 1;
        if self.generated > 4096 {
            return unsupported("operator specialization exceeds 4096 definitions");
        }
        Ok(format!("$special{}", self.generated))
    }

    fn arity(
        &self,
        expression: &Expression,
        definitions: &BTreeMap<String, Definition>,
    ) -> Result<usize> {
        match &expression.node {
            E::Lambda { params, .. } => Ok(params.len()),
            E::Identifier { name } => {
                if let Some(definition) = definitions.get(name) {
                    return Ok(match &definition.head {
                        DefinitionKind::Operator { params } => params.len(),
                        DefinitionKind::Function { .. } => 0,
                    });
                }
                crate::symbols::standard_arity(name).ok_or_else(|| crate::CompileError {
                    message: format!("unknown operator argument {name}"),
                })
            }
            _ => unsupported("operator argument must be a named operator or LAMBDA"),
        }
    }

    fn expression(
        &mut self,
        value: &mut Expression,
        definitions: &BTreeMap<String, Definition>,
    ) -> Result<()> {
        if self.depth >= 64 {
            return unsupported("operator elaboration depth exceeds 64");
        }
        self.depth += 1;
        let result = self.expression_inner(value, definitions);
        self.depth -= 1;
        result
    }

    fn expression_inner(
        &mut self,
        value: &mut Expression,
        definitions: &BTreeMap<String, Definition>,
    ) -> Result<()> {
        if crate::old::needed(value, definitions) {
            let helper = self.fresh()?;
            let parameter = self.fresh()?;
            crate::old::capture(value, helper, parameter);
            return self.expression(value, definitions);
        }
        if functions::rewrite(value, &self.functions) {
            return self.expression(value, definitions);
        }
        if let E::Selection {
            expression,
            selectors,
        } = &value.node
        {
            let helper = self.fresh()?;
            if let E::Identifier { name } | E::Apply { operator: name, .. } = &expression.node {
                self.actions.insert(
                    helper.clone(),
                    self.actions
                        .get(name)
                        .or_else(|| self.names.get(name))
                        .unwrap_or(name)
                        .clone(),
                );
            }
            *value = select::resolve(expression, selectors, definitions, &self.names, helper)?;
            return self.expression(value, definitions);
        }
        if let E::Apply { operator, args } = &mut value.node {
            let callback = match operator.as_str() {
                "SelectSeq" | "SortSeq" => Some(1),
                "ApaFoldSet" | "ApaFoldSeqLeft" => Some(0),
                _ => None,
            };
            if !definitions.contains_key(operator)
                && let Some(actual) = callback.and_then(|index| args.get_mut(index))
            {
                self.expression(actual, definitions)?;
                if let E::Lambda { params, body } = &actual.node {
                    let name = self.fresh()?;
                    let lambda = Definition {
                        name: name.clone(),
                        head: DefinitionKind::Operator {
                            params: params.clone(),
                        },
                        body: *body.clone(),
                        is_local: false,
                        is_recursive: false,
                        location: actual.location,
                    };
                    *actual = identifier(&name, actual.location);
                    let call = value.clone();
                    value.node = E::Let {
                        definitions: vec![lambda],
                        body: Box::new(call),
                    };
                    return self.expression(value, definitions);
                }
            }
        }
        if let E::Let {
            definitions: local,
            body,
        } = &mut value.node
        {
            let functions = functions::expand(local, &mut || self.fresh())?;
            self.functions.extend(functions);
            let mut scope = definitions.clone();
            scope.extend(
                local
                    .iter()
                    .cloned()
                    .map(|definition| (definition.name.clone(), definition)),
            );
            for definition in local.iter_mut().filter(|definition| !higher(definition)) {
                self.expression(&mut definition.body, &scope)?;
            }
            return self.expression(body, &scope);
        }
        if let E::Apply { operator, args } = &mut value.node
            && let Some(definition) = definitions
                .get(operator)
                .filter(|definition| higher(definition))
        {
            let DefinitionKind::Operator { params } = &definition.head else {
                unreachable!()
            };
            if params.len() != args.len() {
                return unsupported(format!(
                    "operator {operator} expects {} arguments",
                    params.len()
                ));
            }
            let mut mapping = BTreeMap::new();
            let mut data_params = vec![];
            let mut data_args = vec![];
            let mut generated = vec![];
            let mut scope = definitions.clone();
            let mut targets = vec![];
            for (param, actual) in params.iter().zip(args) {
                self.expression(actual, definitions)?;
                if param.arity == 0 {
                    data_params.push(param.clone());
                    data_args.push(actual.clone());
                    continue;
                }
                if self.arity(actual, definitions)? != param.arity {
                    return unsupported(format!(
                        "operator parameter {} expects arity {}",
                        param.name, param.arity
                    ));
                }
                let target = if let E::Lambda { params, body } = &actual.node {
                    let name = self.fresh()?;
                    let lambda = Definition {
                        name: name.clone(),
                        head: DefinitionKind::Operator {
                            params: params.clone(),
                        },
                        body: *body.clone(),
                        is_local: false,
                        is_recursive: false,
                        location: actual.location,
                    };
                    scope.insert(name.clone(), lambda.clone());
                    generated.push(lambda);
                    name
                } else if let E::Identifier { name } = &actual.node {
                    name.clone()
                } else {
                    return unsupported("unresolved operator argument");
                };
                mapping.insert(param.name.clone(), identifier(&target, actual.location));
                targets.push(target);
            }
            let key = (operator.clone(), targets);
            if let Some(name) = self.active.get(&key) {
                value.node = E::Apply {
                    operator: name.clone(),
                    args: data_args,
                };
                return Ok(());
            }
            let name = self.fresh()?;
            self.actions.insert(
                name.clone(),
                self.actions
                    .get(operator)
                    .or_else(|| self.names.get(operator))
                    .unwrap_or(operator)
                    .clone(),
            );
            self.active.insert(key.clone(), name.clone());
            let mut special = definition.clone();
            special.name = name.clone();
            special.head = DefinitionKind::Operator {
                params: data_params,
            };
            self.rewrite.expression(&mut special.body, &mapping)?;
            self.expression(&mut special.body, &scope)?;
            self.active.remove(&key);
            generated.push(special);
            value.node = E::Let {
                definitions: generated,
                body: Box::new(Expression {
                    node: E::Apply {
                        operator: name,
                        args: data_args,
                    },
                    location: value.location,
                }),
            };
            return Ok(());
        }
        for child in source::children_mut(value) {
            self.expression(child, definitions)?;
        }
        if let E::Apply { operator, args } = &value.node {
            let node = match (operator.as_str(), args.as_slice()) {
                ("/\\", [_, _]) => Some(E::And {
                    operands: args.clone(),
                    is_bulleted: false,
                }),
                ("\\/", [_, _]) => Some(E::Or {
                    operands: args.clone(),
                    is_bulleted: false,
                }),
                ("UNCHANGED", [expression]) => Some(E::Unchanged {
                    expression: Box::new(expression.clone()),
                }),
                ("ENABLED", [expression]) => Some(E::Enabled {
                    expression: Box::new(expression.clone()),
                }),
                _ => None,
            };
            if let Some(node) = node {
                value.node = node;
            }
        }
        Ok(())
    }
}

pub(crate) fn module(input: &Module, names: &mut BTreeMap<String, String>) -> Result<Module> {
    let mut module = input.clone();
    let mut elaborator = Elaborator {
        rewrite: Rewriter {
            next: 1_000_000,
            strict: false,
            imports: BTreeSet::new(),
            labels: BTreeMap::new(),
            depth: 0,
            namespaces: BTreeMap::new(),
            translated: BTreeSet::new(),
        },
        active: BTreeMap::new(),
        depth: 0,
        generated: 0,
        names: names.clone(),
        actions: BTreeMap::new(),
        functions: BTreeMap::new(),
    };
    elaborator.functions = functions::expand(&mut module.definitions, &mut || elaborator.fresh())?;
    let definitions = module
        .definitions
        .iter()
        .cloned()
        .map(|definition| (definition.name.clone(), definition))
        .collect();
    for definition in module
        .definitions
        .iter_mut()
        .filter(|definition| !higher(definition))
    {
        elaborator.expression(&mut definition.body, &definitions)?;
    }
    for assumption in &mut module.assumptions {
        elaborator.expression(&mut assumption.expression, &definitions)?;
    }
    names.extend(elaborator.actions);
    Ok(module)
}

use crate::analysis::{Node, analysis_children};
use crate::rewrite::identifier;
use crate::{CompileError, Result, definition_body, unsupported};
use rtla::ast::{
    self, Declaration, Definition, DefinitionKind, Expression, ExpressionKind as E, Selector,
};
use std::collections::BTreeMap;

fn index(selector: &Selector, arity: usize) -> Result<usize> {
    let number = match selector {
        Selector::Index { index } => usize::try_from(*index).ok(),
        Selector::Left if arity > 0 => Some(1),
        Selector::Right if arity == 2 => Some(2),
        _ => None,
    };
    number
        .filter(|number| *number > 0 && *number <= arity)
        .map(|number| number - 1)
        .ok_or_else(|| CompileError {
            message: format!("invalid subexpression selector for {arity} operands"),
        })
}

fn label(value: &Expression, name: &str) -> Result<(Expression, Vec<String>)> {
    let mut pending = vec![value];
    let mut found = None;
    while let Some(value) = pending.pop() {
        if let E::Label {
            name: candidate,
            params,
            body,
        } = &value.node
        {
            if candidate == name {
                if found.is_some() {
                    return unsupported(format!("duplicate label {name}"));
                }
                found = Some((*body.clone(), params.clone()));
            }
            continue;
        }
        pending.extend(
            analysis_children(Node::Source(value))
                .into_iter()
                .filter_map(|edge| {
                    if let Node::Source(value) = edge.node {
                        Some(value)
                    } else {
                        None
                    }
                }),
        );
    }
    found.ok_or_else(|| CompileError {
        message: format!("unknown subexpression label {name}"),
    })
}

fn bound_body(value: &Expression) -> Option<(Expression, Vec<Declaration>)> {
    let (body, patterns) = match &value.node {
        E::Forall { bounds, body }
        | E::Exists { bounds, body }
        | E::FunctionConstruction { bounds, body }
        | E::SetMap {
            bounds,
            expression: body,
        } => (
            body.as_ref(),
            bounds
                .iter()
                .map(|bound| &bound.pattern)
                .collect::<Vec<_>>(),
        ),
        E::Choose { pattern, body, .. } => (body.as_ref(), vec![pattern]),
        E::SetFilter { bound, predicate } => (predicate.as_ref(), vec![&bound.pattern]),
        E::UnboundedQuantifier { names, body, .. } => {
            return Some((
                *body.clone(),
                names
                    .iter()
                    .map(|name| Declaration {
                        name: name.clone(),
                        arity: 0,
                        location: value.location,
                    })
                    .collect(),
            ));
        }
        _ => return None,
    };
    let params = patterns
        .into_iter()
        .flat_map(|pattern| match pattern {
            ast::Pattern::Name { name } => std::slice::from_ref(name),
            ast::Pattern::Tuple { names } => names.as_slice(),
        })
        .map(|name| Declaration {
            name: name.clone(),
            arity: 0,
            location: value.location,
        })
        .collect();
    Some((body.clone(), params))
}

fn operands(value: &Expression) -> Result<Vec<Expression>> {
    Ok(match &value.node {
        E::Apply { args, .. } | E::Bracket { args } => args.clone(),
        E::And { operands, .. } | E::Or { operands, .. } => operands.clone(),
        E::Tuple { elements } | E::SetEnumeration { elements } => elements.clone(),
        E::Product { factors } => factors.clone(),
        E::Prime { expression }
        | E::Unchanged { expression }
        | E::Enabled { expression }
        | E::Always { expression }
        | E::Eventually { expression } => vec![*expression.clone()],
        E::If {
            condition,
            consequent,
            alternative,
        } => vec![
            *condition.clone(),
            *consequent.clone(),
            *alternative.clone(),
        ],
        E::Record { fields } | E::RecordSet { fields } => {
            fields.iter().map(|field| field.value.clone()).collect()
        }
        E::FunctionSet { domain, range } => vec![*domain.clone(), *range.clone()],
        E::Forall { bounds, .. }
        | E::Exists { bounds, .. }
        | E::FunctionConstruction { bounds, .. }
        | E::SetMap { bounds, .. } => bounds.iter().map(|bound| bound.set.clone()).collect(),
        E::SetFilter { bound, .. } => vec![bound.set.clone()],
        E::Choose { set, .. } => set.iter().map(|set| *set.clone()).collect(),
        E::FieldAccess { record, field } => vec![
            *record.clone(),
            Expression {
                node: E::String {
                    value: field.clone(),
                },
                location: value.location,
            },
        ],
        E::FunctionApplication { function, args } => vec![
            *function.clone(),
            if args.len() == 1 {
                args[0].clone()
            } else {
                Expression {
                    node: E::Tuple {
                        elements: args.clone(),
                    },
                    location: value.location,
                }
            },
        ],
        E::BoxAction { action, subscript } | E::AngleAction { action, subscript } => {
            vec![*action.clone(), *subscript.clone()]
        }
        E::WeakFairness { action, subscript } | E::StrongFairness { action, subscript } => {
            vec![*subscript.clone(), *action.clone()]
        }
        E::Except { function, .. } => vec![*function.clone()],
        _ => return unsupported("selected expression has no selectable operands"),
    })
}

struct Parameters {
    params: Vec<Declaration>,
    arguments: Vec<Expression>,
    missing: Vec<Declaration>,
}

impl Parameters {
    fn add(&mut self, params: &[Declaration], args: Option<&[Expression]>) -> Result<()> {
        if let Some(args) = args
            && args.len() != params.len()
        {
            return unsupported(format!(
                "subexpression expects {} arguments, received {}",
                params.len(),
                args.len()
            ));
        }
        for (index, param) in params.iter().enumerate() {
            if self
                .params
                .iter()
                .any(|previous| previous.name == param.name)
            {
                return unsupported("repeated subexpression parameter");
            }
            self.params.push(param.clone());
            self.arguments.push(args.map_or_else(
                || identifier(&param.name, param.location),
                |args| args[index].clone(),
            ));
            if args.is_none() {
                self.missing.push(param.clone());
            }
        }
        Ok(())
    }
}

pub(crate) fn resolve(
    base: &Expression,
    selectors: &[Selector],
    definitions: &BTreeMap<String, Definition>,
    names: &BTreeMap<String, String>,
    helper: String,
) -> Result<Expression> {
    let (name, args) = match &base.node {
        E::Identifier { name } => (name, None),
        E::Apply { operator, args } => (operator, Some(args.as_slice())),
        _ => return unsupported("subexpression selector requires an operator name"),
    };
    let definition = definitions.get(name).ok_or_else(|| CompileError {
        message: format!("unknown subexpression operator {name}"),
    })?;
    let mut parameters = Parameters {
        params: vec![],
        arguments: vec![],
        missing: vec![],
    };
    if let DefinitionKind::Operator { params } = &definition.head {
        parameters.add(params, args)?;
    } else if args.is_some_and(|args| !args.is_empty()) {
        return unsupported("function definition has no operator parameters");
    }
    let mut current = definition_body(definition);
    let mut scopes = vec![];
    let mut named = true;
    let mut operator = true;
    let mut lookup = false;
    let mut cursor = 0;
    while let Some(selector) = selectors.get(cursor) {
        match selector {
            Selector::Body => {
                if !named
                    || !(cursor + 1 == selectors.len() && operator
                        || matches!(selectors.get(cursor + 1), Some(Selector::Name { .. })))
                {
                    return unsupported(
                        "!: must follow a name and precede a LET operator, or end an operator reference",
                    );
                }
                lookup = true;
            }
            Selector::Name { name, args } if lookup => {
                let E::Let { definitions, .. } = &current.node else {
                    return unsupported("!: name selection requires a LET expression");
                };
                let local = definitions
                    .iter()
                    .find(|definition| {
                        definition.name == *name || names.get(&definition.name) == Some(name)
                    })
                    .ok_or_else(|| CompileError {
                        message: format!("unknown LET subexpression operator {name}"),
                    })?;
                if let DefinitionKind::Operator { params } = &local.head {
                    parameters.add(
                        params,
                        (!args.is_empty() || params.is_empty()).then_some(args.as_slice()),
                    )?;
                }
                scopes.push(definitions.clone());
                current = definition_body(local);
                lookup = false;
                named = true;
                operator = true;
            }
            Selector::Name { name, args } => {
                if !named {
                    return unsupported("label selection must follow an operator or label name");
                }
                let (body, params) = label(&current, name)?;
                let params: Vec<_> = params
                    .into_iter()
                    .map(|name| Declaration {
                        name,
                        arity: 0,
                        location: current.location,
                    })
                    .collect();
                parameters.add(
                    &params,
                    (!args.is_empty() || params.is_empty()).then_some(args.as_slice()),
                )?;
                current = body;
                operator = false;
            }
            Selector::Arguments { .. } | Selector::Bound => {
                let (body, params) = bound_body(&current).ok_or_else(|| CompileError {
                    message: "!@ or !(...) requires an expression with bound names".into(),
                })?;
                parameters.add(
                    &params,
                    if let Selector::Arguments { args } = selector {
                        Some(args)
                    } else {
                        None
                    },
                )?;
                current = body;
                named = false;
            }
            _ => {
                if let E::Let { definitions, body } = &current.node {
                    index(selector, 1)?;
                    scopes.push(definitions.clone());
                    current = *body.clone();
                } else if let E::Case { arms, other } = &current.node {
                    let arm = index(selector, arms.len() + usize::from(other.is_some()))?;
                    cursor += 1;
                    let component = index(
                        selectors.get(cursor).ok_or_else(|| CompileError {
                            message: "CASE selection requires an arm and a condition/body index"
                                .into(),
                        })?,
                        2,
                    )?;
                    current = if let Some(arm) = arms.get(arm) {
                        if component == 0 {
                            arm.condition.clone()
                        } else {
                            arm.body.clone()
                        }
                    } else if component == 1 {
                        *other.clone().unwrap()
                    } else {
                        return unsupported("OTHER has no selectable condition");
                    };
                } else {
                    let operands = operands(&current)?;
                    current = operands[index(selector, operands.len())?].clone();
                }
                named = false;
                lookup = false;
            }
        }
        cursor += 1;
    }
    for scope in scopes.into_iter().rev() {
        current = Expression {
            location: current.location,
            node: E::Let {
                definitions: scope,
                body: Box::new(current),
            },
        };
    }
    let definition = Definition {
        name: helper.clone(),
        head: DefinitionKind::Operator {
            params: parameters.params,
        },
        body: current,
        is_local: false,
        is_recursive: false,
        location: base.location,
    };
    let mut result = Expression {
        location: base.location,
        node: E::Let {
            definitions: vec![definition],
            body: Box::new(Expression {
                location: base.location,
                node: E::Apply {
                    operator: helper,
                    args: parameters.arguments,
                },
            }),
        },
    };
    if !parameters.missing.is_empty() {
        result = Expression {
            location: base.location,
            node: E::Lambda {
                params: parameters.missing,
                body: Box::new(result),
            },
        };
    }
    Ok(result)
}

use crate::analysis::{Node, analysis_children};
use crate::{Result, unsupported};
use rtla::ast::{self, DefinitionKind, Expression, ExpressionKind as E, Module};
use std::collections::{BTreeMap, BTreeSet, HashMap, VecDeque};

#[derive(Clone, Default, PartialEq, Eq)]
struct Value {
    base: u8,
    parameters: BTreeSet<usize>,
}

#[derive(Clone, Default, PartialEq, Eq)]
struct Summary {
    value: Value,
    limits: BTreeMap<usize, u8>,
}

impl Summary {
    fn merge(&mut self, other: Self) {
        self.value.base = self.value.base.max(other.value.base);
        self.value.parameters.extend(other.value.parameters);
        for (parameter, maximum) in other.limits {
            self.limits
                .entry(parameter)
                .and_modify(|old| *old = (*old).min(maximum))
                .or_insert(maximum);
        }
    }

    fn constrain(&mut self, maximum: u8, expression: &Expression) -> Result<()> {
        if self.value.base > maximum {
            return unsupported(format!(
                "level error at line {}, column {}: level {} exceeds {}",
                expression.location.line, expression.location.column, self.value.base, maximum
            ));
        }
        for parameter in &self.value.parameters {
            self.limits
                .entry(*parameter)
                .and_modify(|old| *old = (*old).min(maximum))
                .or_insert(maximum);
        }
        Ok(())
    }
}

#[derive(Clone, Copy)]
enum Symbol {
    Constant,
    Variable,
    Parameter(usize),
    Definition(usize),
}

struct Scope {
    parent: Option<usize>,
    symbols: BTreeMap<String, Symbol>,
}

struct Definition<'a> {
    syntax: &'a ast::Definition,
    parameters: Vec<usize>,
}

struct Analysis<'a> {
    scopes: Vec<Scope>,
    definitions: Vec<Definition<'a>>,
    expression_scopes: HashMap<*const Expression, usize>,
    nested_definitions: HashMap<*const Expression, Vec<usize>>,
    next_parameter: usize,
    summaries: Vec<Summary>,
}

fn children(expression: &Expression) -> Vec<&Expression> {
    let mut pending = analysis_children(Node::Source(expression));
    let mut result = vec![];
    while let Some(edge) = pending.pop() {
        match edge.node {
            Node::Source(child) => result.push(child),
            Node::SourceDefinition(_) => {}
            node => pending.extend(analysis_children(node)),
        }
    }
    result.reverse();
    result
}

impl<'a> Analysis<'a> {
    fn scope(&mut self, parent: usize) -> usize {
        let id = self.scopes.len();
        self.scopes.push(Scope {
            parent: Some(parent),
            symbols: BTreeMap::new(),
        });
        id
    }

    fn symbol(&self, mut scope: usize, name: &str) -> Option<Symbol> {
        loop {
            if let Some(symbol) = self.scopes[scope].symbols.get(name) {
                return Some(*symbol);
            }
            scope = self.scopes[scope].parent?;
        }
    }

    fn register(
        &mut self,
        definitions: &'a [ast::Definition],
        scope: usize,
        depth: usize,
    ) -> Result<()> {
        let first = self.definitions.len();
        for definition in definitions {
            let id = self.definitions.len();
            self.scopes[scope]
                .symbols
                .insert(definition.name.clone(), Symbol::Definition(id));
            self.definitions.push(Definition {
                syntax: definition,
                parameters: vec![],
            });
        }
        for (offset, definition) in definitions.iter().enumerate() {
            let mut local = self.scope(scope);
            match &definition.head {
                DefinitionKind::Operator { params } => {
                    for parameter in params {
                        let id = self.next_parameter;
                        self.next_parameter += 1;
                        self.scopes[local]
                            .symbols
                            .insert(parameter.name.clone(), Symbol::Parameter(id));
                        self.definitions[first + offset].parameters.push(id);
                    }
                }
                DefinitionKind::Function { bounds } => local = self.bounds(bounds, local, depth)?,
            }
            self.collect(&definition.body, local, depth)?;
        }
        Ok(())
    }

    fn bounds(
        &mut self,
        bounds: &'a [ast::Bound],
        mut scope: usize,
        depth: usize,
    ) -> Result<usize> {
        for bound in bounds {
            self.collect(&bound.set, scope, depth + 1)?;
            scope = self.scope(scope);
            match &bound.pattern {
                ast::Pattern::Name { name } => {
                    self.scopes[scope]
                        .symbols
                        .insert(name.clone(), Symbol::Constant);
                }
                ast::Pattern::Tuple { names } => {
                    for name in names {
                        self.scopes[scope]
                            .symbols
                            .insert(name.clone(), Symbol::Constant);
                    }
                }
            }
        }
        Ok(scope)
    }

    fn collect(&mut self, expression: &'a Expression, scope: usize, depth: usize) -> Result<()> {
        if depth > 64 {
            return unsupported("source level analysis nesting exceeds 64");
        }
        self.expression_scopes.insert(expression, scope);
        match &expression.node {
            E::Let { definitions, body }
            | E::LetModule {
                definitions, body, ..
            } => {
                let local = self.scope(scope);
                let first = self.definitions.len();
                self.register(definitions, local, depth + 1)?;
                self.nested_definitions
                    .insert(expression, (first..first + definitions.len()).collect());
                self.collect(body, local, depth + 1)?;
            }
            E::Forall { bounds, body }
            | E::Exists { bounds, body }
            | E::FunctionConstruction { bounds, body }
            | E::SetMap {
                bounds,
                expression: body,
            } => {
                let local = self.scope(scope);
                let local = self.bounds(bounds, local, depth)?;
                self.collect(body, local, depth + 1)?;
            }
            E::SetFilter { bound, predicate } => {
                let local = self.scope(scope);
                let local = self.bounds(std::slice::from_ref(bound), local, depth)?;
                self.collect(predicate, local, depth + 1)?;
            }
            E::Choose { pattern, set, body } => {
                let local = self.scope(scope);
                if let Some(set) = set {
                    self.collect(set, scope, depth + 1)?;
                }
                let names = match pattern {
                    ast::Pattern::Name { name } => std::slice::from_ref(name),
                    ast::Pattern::Tuple { names } => names,
                };
                for name in names {
                    self.scopes[local]
                        .symbols
                        .insert(name.clone(), Symbol::Constant);
                }
                self.collect(body, local, depth + 1)?;
            }
            _ => {
                for child in children(expression) {
                    self.collect(child, scope, depth + 1)?;
                }
            }
        }
        Ok(())
    }

    fn referenced(&self, expression: &Expression, name: &str) -> Option<Symbol> {
        self.symbol(
            self.expression_scopes[&(expression as *const Expression)],
            name,
        )
    }

    fn apply(
        &self,
        expression: &Expression,
        symbol: Symbol,
        actuals: Vec<Summary>,
    ) -> Result<Summary> {
        match symbol {
            Symbol::Definition(id) => {
                let definition = &self.definitions[id];
                if definition.parameters.len() != actuals.len() {
                    return unsupported(format!(
                        "source level arity error for {}",
                        definition.syntax.name
                    ));
                }
                let summary = &self.summaries[id];
                let mut result = Summary::default();
                result.value.base = summary.value.base;
                result.value.parameters = summary
                    .value
                    .parameters
                    .difference(&definition.parameters.iter().copied().collect())
                    .copied()
                    .collect();
                for (parameter, maximum) in &summary.limits {
                    if !definition.parameters.contains(parameter) {
                        result.limits.insert(*parameter, *maximum);
                    }
                }
                for (parameter, mut actual) in definition.parameters.iter().zip(actuals) {
                    if let Some(maximum) = summary.limits.get(parameter) {
                        actual.constrain(*maximum, expression)?;
                    }
                    if !summary.value.parameters.contains(parameter) {
                        actual.value = Value::default();
                    }
                    result.merge(actual);
                }
                Ok(result)
            }
            Symbol::Parameter(id) => {
                let mut result = Summary::default();
                result.value.parameters.insert(id);
                for actual in actuals {
                    result.merge(actual);
                }
                Ok(result)
            }
            Symbol::Variable | Symbol::Constant => {
                let mut result = Summary::default();
                result.value.base = u8::from(matches!(symbol, Symbol::Variable));
                for actual in actuals {
                    result.merge(actual);
                }
                Ok(result)
            }
        }
    }

    fn operator(
        &self,
        expression: &Expression,
        children: Vec<(&Expression, u8)>,
        base: u8,
        weighted: bool,
    ) -> Result<Summary> {
        let mut result = Summary::default();
        for (child, maximum) in children {
            let mut summary = self.expression(child)?;
            summary.constrain(maximum, expression)?;
            result.merge(summary);
        }
        if weighted {
            result.value.base = result.value.base.max(base);
        } else {
            result.value = Value {
                base,
                parameters: BTreeSet::new(),
            };
        }
        Ok(result)
    }

    fn expression(&self, expression: &Expression) -> Result<Summary> {
        match &expression.node {
            E::Identifier { name } => {
                if let Some(Symbol::Definition(id)) = self.referenced(expression, name)
                    && !self.definitions[id].parameters.is_empty()
                {
                    let mut summary = self.summaries[id].clone();
                    for parameter in &self.definitions[id].parameters {
                        summary.value.parameters.remove(parameter);
                        summary.limits.remove(parameter);
                    }
                    return Ok(summary);
                }
                self.referenced(expression, name)
                    .map_or(Ok(Summary::default()), |symbol| {
                        self.apply(expression, symbol, vec![])
                    })
            }
            E::Apply { operator, args } => {
                if let Some(symbol) = self.referenced(expression, operator) {
                    return self.apply(
                        expression,
                        symbol,
                        args.iter()
                            .map(|argument| self.expression(argument))
                            .collect::<Result<_>>()?,
                    );
                }
                let (base, maximum, weighted) = match operator.as_str() {
                    "[]" | "<>" | "~>" | "-+->" => (3, 3, false),
                    "ENABLED" => (1, 2, false),
                    "UNCHANGED" => (2, 1, false),
                    "/\\" | "\\/" | "=>" | "<=>" | "~" | "\\lnot" => (0, 3, true),
                    _ => (0, 2, true),
                };
                self.operator(
                    expression,
                    args.iter().map(|argument| (argument, maximum)).collect(),
                    base,
                    weighted,
                )
            }
            E::Prime { expression: child } => self.operator(expression, vec![(child, 1)], 2, false),
            E::Unchanged { expression: child } => {
                self.operator(expression, vec![(child, 1)], 2, false)
            }
            E::Enabled { expression: child } => {
                self.operator(expression, vec![(child, 2)], 1, false)
            }
            E::Always { expression: child } | E::Eventually { expression: child } => {
                self.operator(expression, vec![(child, 3)], 3, false)
            }
            E::BoxAction { action, subscript } | E::AngleAction { action, subscript } => {
                self.operator(expression, vec![(action, 2), (subscript, 1)], 2, false)
            }
            E::WeakFairness { action, subscript } | E::StrongFairness { action, subscript } => {
                self.operator(expression, vec![(subscript, 1), (action, 2)], 3, false)
            }
            E::Let { body, .. } | E::LetModule { body, .. } => {
                let mut result = self.expression(body)?;
                for id in &self.nested_definitions[&(expression as *const Expression)] {
                    for (parameter, maximum) in &self.summaries[*id].limits {
                        if !self.definitions[*id].parameters.contains(parameter) {
                            result
                                .limits
                                .entry(*parameter)
                                .and_modify(|old| *old = (*old).min(*maximum))
                                .or_insert(*maximum);
                        }
                    }
                }
                Ok(result)
            }
            E::Forall { bounds, body }
            | E::Exists { bounds, body }
            | E::FunctionConstruction { bounds, body } => self.operator(
                expression,
                bounds
                    .iter()
                    .map(|bound| (&bound.set, 2))
                    .chain(std::iter::once((body.as_ref(), 3)))
                    .collect(),
                0,
                true,
            ),
            E::And { .. }
            | E::Or { .. }
            | E::If { .. }
            | E::Case { .. }
            | E::Record { .. }
            | E::Label { .. } => self.operator(
                expression,
                children(expression)
                    .into_iter()
                    .map(|child| (child, 3))
                    .collect(),
                0,
                true,
            ),
            E::AssumeProve { .. } => Ok(Summary::default()),
            _ => self.operator(
                expression,
                children(expression)
                    .into_iter()
                    .map(|child| (child, 2))
                    .collect(),
                0,
                true,
            ),
        }
    }
}

pub(crate) fn validate(module: &Module) -> Result<BTreeMap<(usize, String), u8>> {
    let mut analysis = Analysis {
        scopes: vec![Scope {
            parent: None,
            symbols: BTreeMap::new(),
        }],
        definitions: vec![],
        expression_scopes: HashMap::new(),
        nested_definitions: HashMap::new(),
        next_parameter: 0,
        summaries: vec![],
    };
    for declaration in &module.variables {
        analysis.scopes[0]
            .symbols
            .insert(declaration.name.clone(), Symbol::Variable);
    }
    for declaration in &module.constants {
        analysis.scopes[0]
            .symbols
            .insert(declaration.name.clone(), Symbol::Constant);
    }
    analysis.register(&module.definitions, 0, 0)?;
    for assumption in &module.assumptions {
        analysis.collect(&assumption.expression, 0, 0)?;
    }
    analysis
        .summaries
        .resize(analysis.definitions.len(), Summary::default());
    let mut dependencies = vec![BTreeSet::new(); analysis.definitions.len()];
    let mut callers = vec![vec![]; analysis.definitions.len()];
    for (id, definition) in analysis.definitions.iter().enumerate() {
        let mut pending = vec![&definition.syntax.body];
        if let DefinitionKind::Function { bounds } = &definition.syntax.head {
            pending.extend(bounds.iter().map(|bound| &bound.set));
        }
        while let Some(expression) = pending.pop() {
            if let E::Identifier { name } | E::Apply { operator: name, .. } = &expression.node
                && let Some(Symbol::Definition(dependency)) = analysis.referenced(expression, name)
            {
                dependencies[id].insert(dependency);
            }
            if let Some(nested) = analysis
                .nested_definitions
                .get(&(expression as *const Expression))
            {
                dependencies[id].extend(nested);
            }
            pending.extend(children(expression));
        }
        for dependency in &dependencies[id] {
            callers[*dependency].push(id);
        }
    }
    let mut seen = vec![false; dependencies.len()];
    let mut order = vec![];
    for root in 0..seen.len() {
        let mut pending = vec![(root, false)];
        while let Some((id, finish)) = pending.pop() {
            if finish {
                order.push(id);
            } else if !seen[id] {
                seen[id] = true;
                pending.push((id, true));
                pending.extend(
                    dependencies[id]
                        .iter()
                        .map(|dependency| (*dependency, false)),
                );
            }
        }
    }
    let mut queue: VecDeque<_> = order.into();
    let mut queued = vec![true; analysis.definitions.len()];
    while let Some(id) = queue.pop_front() {
        queued[id] = false;
        let definition = &analysis.definitions[id];
        let mut summary = analysis.expression(&definition.syntax.body)?;
        if let DefinitionKind::Function { bounds } = &definition.syntax.head {
            for bound in bounds {
                let mut domain = analysis.expression(&bound.set)?;
                domain.constrain(2, &bound.set)?;
                summary.merge(domain);
            }
        }
        if definition.syntax.is_recursive {
            summary.constrain(2, &definition.syntax.body)?;
            for parameter in &definition.parameters {
                if summary
                    .limits
                    .get(parameter)
                    .is_some_and(|maximum| *maximum < 2)
                {
                    return unsupported(
                        "level error: recursive operator parameters cannot be primed",
                    );
                }
                summary
                    .limits
                    .entry(*parameter)
                    .and_modify(|maximum| *maximum = (*maximum).min(2))
                    .or_insert(2);
            }
        }
        if analysis.summaries[id] != summary {
            analysis.summaries[id] = summary;
            for caller in &callers[id] {
                if !queued[*caller] {
                    queue.push_back(*caller);
                    queued[*caller] = true;
                }
            }
        }
    }
    for assumption in &module.assumptions {
        analysis
            .expression(&assumption.expression)?
            .constrain(0, &assumption.expression)?;
    }
    Ok(analysis
        .definitions
        .iter()
        .enumerate()
        .map(|(id, definition)| {
            (
                (
                    definition.syntax.location.start,
                    definition.syntax.name.clone(),
                ),
                analysis.summaries[id].value.base,
            )
        })
        .collect())
}

use crate::Result;
use crate::analysis::{Node, analysis_children};
use crate::rewrite::identifier;
use rtla::ast::{
    self, Declaration, Definition, DefinitionKind, Expression, ExpressionKind as E, Pattern,
};
use std::collections::BTreeMap;

pub(crate) struct Function {
    pub helper: String,
    pub domain: Expression,
}

pub(crate) fn recursive(definition: &Definition) -> bool {
    if !matches!(definition.head, DefinitionKind::Function { .. }) {
        return false;
    }
    if definition.is_recursive {
        return true;
    }
    let mut pending = vec![Node::Source(&definition.body)];
    while let Some(node) = pending.pop() {
        if matches!(node, Node::Source(Expression { node: E::Identifier { name } | E::Apply { operator: name, .. }, .. }) if *name == definition.name)
        {
            return true;
        }
        pending.extend(analysis_children(node).into_iter().map(|edge| edge.node));
    }
    false
}

fn pattern_value(pattern: &Pattern, location: ast::Location) -> Expression {
    match pattern {
        Pattern::Name { name } => identifier(name, location),
        Pattern::Tuple { names } => Expression {
            location,
            node: E::Tuple {
                elements: names
                    .iter()
                    .map(|name| identifier(name, location))
                    .collect(),
            },
        },
    }
}

fn component(value: Expression, index: usize) -> Expression {
    Expression {
        location: value.location,
        node: E::FunctionApplication {
            function: Box::new(value.clone()),
            args: vec![Expression {
                location: value.location,
                node: E::Number {
                    value: index as u64 + 1,
                },
            }],
        },
    }
}

pub(crate) fn expand(
    definitions: &mut Vec<Definition>,
    fresh: &mut impl FnMut() -> Result<String>,
) -> Result<BTreeMap<String, Function>> {
    let mut functions = BTreeMap::new();
    let mut generated = vec![];
    for definition in definitions
        .iter_mut()
        .filter(|definition| recursive(definition))
    {
        let DefinitionKind::Function { bounds } = &definition.head else {
            unreachable!()
        };
        let key = fresh()?;
        let helper = fresh()?;
        let location = definition.location;
        let components: Vec<_> = bounds
            .iter()
            .map(|bound| pattern_value(&bound.pattern, location))
            .collect();
        let construction_key = if components.len() == 1 {
            components[0].clone()
        } else {
            Expression {
                location,
                node: E::Tuple {
                    elements: components,
                },
            }
        };
        let domain = if bounds.len() == 1 {
            bounds[0].set.clone()
        } else {
            Expression {
                location,
                node: E::SetMap {
                    expression: Box::new(construction_key.clone()),
                    bounds: bounds.clone(),
                },
            }
        };
        let mut bindings = vec![];
        for (index, bound) in bounds.iter().enumerate() {
            let value = if bounds.len() == 1 {
                identifier(&key, location)
            } else {
                component(identifier(&key, location), index)
            };
            let names = match &bound.pattern {
                Pattern::Name { name } => std::slice::from_ref(name),
                Pattern::Tuple { names } => names.as_slice(),
            };
            for (index, name) in names.iter().enumerate() {
                bindings.push(Definition {
                    name: name.clone(),
                    head: DefinitionKind::Operator { params: vec![] },
                    body: if matches!(bound.pattern, Pattern::Tuple { .. }) {
                        component(value.clone(), index)
                    } else {
                        value.clone()
                    },
                    is_local: false,
                    is_recursive: false,
                    location,
                });
            }
        }
        let body = Expression {
            location,
            node: E::Let {
                definitions: bindings,
                body: Box::new(definition.body.clone()),
            },
        };
        let condition = Expression {
            location,
            node: E::Apply {
                operator: "\\in".into(),
                args: vec![identifier(&key, location), domain.clone()],
            },
        };
        generated.push(Definition {
            name: helper.clone(),
            head: DefinitionKind::Operator {
                params: vec![Declaration {
                    name: key,
                    arity: 0,
                    location,
                }],
            },
            body: Expression {
                location,
                node: E::Case {
                    arms: vec![ast::CaseArm { condition, body }],
                    other: None,
                },
            },
            is_local: false,
            is_recursive: true,
            location,
        });
        let body = Expression {
            location,
            node: E::Apply {
                operator: helper.clone(),
                args: vec![construction_key],
            },
        };
        definition.body = Expression {
            location,
            node: E::FunctionConstruction {
                bounds: bounds.clone(),
                body: Box::new(body),
            },
        };
        definition.head = DefinitionKind::Operator { params: vec![] };
        definition.is_recursive = false;
        functions.insert(definition.name.clone(), Function { helper, domain });
    }
    definitions.extend(generated);
    Ok(functions)
}

pub(crate) fn rewrite(value: &mut Expression, functions: &BTreeMap<String, Function>) -> bool {
    if let E::FunctionApplication { function, args } = &value.node
        && let E::Identifier { name } = &function.node
        && let Some(function) = functions.get(name)
    {
        let key = if args.len() == 1 {
            args[0].clone()
        } else {
            Expression {
                location: value.location,
                node: E::Tuple {
                    elements: args.clone(),
                },
            }
        };
        value.node = E::Apply {
            operator: function.helper.clone(),
            args: vec![key],
        };
        return true;
    }
    if let E::Apply { operator, args } = &value.node
        && operator == "DOMAIN"
        && args.len() == 1
        && let E::Identifier { name } = &args[0].node
        && let Some(function) = functions.get(name)
    {
        *value = function.domain.clone();
        return true;
    }
    false
}

pub(crate) fn rewrite_tree(
    value: &mut Expression,
    functions: &BTreeMap<String, Function>,
    depth: usize,
) -> Result<()> {
    if depth >= 64 {
        return crate::unsupported("recursive function normalization depth exceeds 64");
    }
    rewrite(value, functions);
    for child in crate::source::children_mut(value) {
        rewrite_tree(child, functions, depth + 1)?;
    }
    Ok(())
}

use crate::analysis::{Node, analysis_children};
use rtla::ast::{Declaration, Definition, DefinitionKind, Expression, ExpressionKind as E};
use std::collections::{BTreeMap, BTreeSet};

fn zero_arity(definition: &Definition) -> bool {
    !matches!(&definition.head, DefinitionKind::Operator { params } if !params.is_empty())
}

fn contains_except(value: &Expression, definitions: &BTreeMap<String, Definition>) -> bool {
    let mut pending = vec![Node::Source(value)];
    let mut visited = BTreeSet::new();
    while let Some(node) = pending.pop() {
        if matches!(
            node,
            Node::Source(Expression {
                node: E::Except { .. },
                ..
            })
        ) {
            return true;
        }
        if let Node::Source(Expression {
            node: E::Identifier { name } | E::Apply { operator: name, .. },
            ..
        }) = node
            && let Some(definition) = definitions.get(name)
            && visited.insert(name)
        {
            pending.push(Node::SourceDefinition(definition));
        }
        pending.extend(analysis_children(node).into_iter().map(|edge| edge.node));
    }
    false
}

pub(crate) fn needed(value: &Expression, definitions: &BTreeMap<String, Definition>) -> bool {
    let E::Let {
        definitions: local,
        body,
    } = &value.node
    else {
        return false;
    };
    if !local.iter().any(|definition| {
        zero_arity(definition) && crate::free_old(&crate::definition_body(definition))
    }) {
        return false;
    }
    let mut environment = definitions.clone();
    environment.extend(
        local
            .iter()
            .cloned()
            .map(|definition| (definition.name.clone(), definition)),
    );
    contains_except(body, &environment)
}

fn replace(value: &mut Expression, name: &str) {
    match &mut value.node {
        E::ExceptAt => value.node = E::Identifier { name: name.into() },
        E::Except { function, updates } => {
            replace(function, name);
            for update in updates {
                for path in &mut update.path {
                    if let rtla::ast::ExceptPath::Index { args } = path {
                        for argument in args {
                            replace(argument, name);
                        }
                    }
                }
            }
        }
        E::Let { definitions, body } => {
            for definition in definitions
                .iter_mut()
                .filter(|definition| zero_arity(definition))
            {
                replace_definition(definition, name);
            }
            replace(body, name);
        }
        _ => {
            for child in crate::source::children_mut(value) {
                replace(child, name);
            }
        }
    }
}

fn replace_definition(definition: &mut Definition, name: &str) {
    if let DefinitionKind::Function { bounds } = &mut definition.head {
        for bound in bounds {
            replace(&mut bound.set, name);
        }
    }
    replace(&mut definition.body, name);
}

pub(crate) fn capture(value: &mut Expression, helper: String, parameter: String) {
    let location = value.location;
    let mut body = value.clone();
    let E::Let { definitions, .. } = &mut body.node else {
        unreachable!()
    };
    for definition in definitions
        .iter_mut()
        .filter(|definition| zero_arity(definition))
    {
        replace_definition(definition, &parameter);
    }
    value.node = E::Let {
        definitions: vec![Definition {
            name: helper.clone(),
            head: DefinitionKind::Operator {
                params: vec![Declaration {
                    name: parameter,
                    arity: 0,
                    location,
                }],
            },
            body,
            is_local: false,
            is_recursive: false,
            location,
        }],
        body: Box::new(Expression {
            node: E::Apply {
                operator: helper,
                args: vec![Expression {
                    node: E::ExceptAt,
                    location,
                }],
            },
            location,
        }),
    };
}

use crate::analysis::{Node, analysis_children};
use crate::{Result, unsupported};
use rtla::ast::{Definition, DefinitionKind, Expression, ExpressionKind as E, Module, Pattern};
use std::collections::BTreeSet;

fn names(pattern: &Pattern) -> &[String] {
    match pattern {
        Pattern::Name { name } => std::slice::from_ref(name),
        Pattern::Tuple { names } => names,
    }
}

#[derive(Default)]
struct Scope {
    parameters: BTreeSet<String>,
    labels: BTreeSet<String>,
    allowed: bool,
    old: bool,
}

fn definition(value: &Definition, outer: &mut Scope, depth: usize) -> Result<()> {
    let mut scope = Scope {
        allowed: true,
        old: outer.old,
        ..Scope::default()
    };
    if let DefinitionKind::Function { bounds } = &value.head {
        for bound in bounds {
            expression(&bound.set, outer, depth + 1)?;
            scope
                .parameters
                .extend(names(&bound.pattern).iter().cloned());
        }
    }
    expression(&value.body, &mut scope, depth + 1)
}

fn expression(value: &Expression, scope: &mut Scope, depth: usize) -> Result<()> {
    if depth > 64 {
        return unsupported("label scope nesting exceeds 64");
    }
    match &value.node {
        E::Label { name, params, body } => {
            if !scope.allowed {
                return unsupported("label outside an operator, assumption or theorem body");
            }
            if scope.old {
                return unsupported("labels inside EXCEPT replacements are not supported by TLC");
            }
            let parameters: BTreeSet<_> = params.iter().cloned().collect();
            if parameters.len() != params.len() || parameters != scope.parameters {
                return unsupported(format!(
                    "label {name} must list exactly the bound names in its labeling scope"
                ));
            }
            if !scope.labels.insert(name.clone()) {
                return unsupported(format!("duplicate label {name}"));
            }
            expression(
                body,
                &mut Scope {
                    allowed: true,
                    ..Scope::default()
                },
                depth + 1,
            )?;
        }
        E::Let { definitions, body }
        | E::LetModule {
            definitions, body, ..
        } => {
            for entry in definitions {
                definition(entry, scope, depth + 1)?;
            }
            if let E::LetModule { instances, .. } = &value.node {
                for instance in instances {
                    for substitution in &instance.substitutions {
                        expression(&substitution.expression, scope, depth + 1)?;
                    }
                }
            }
            expression(body, scope, depth + 1)?;
        }
        E::Forall { bounds, body }
        | E::Exists { bounds, body }
        | E::FunctionConstruction { bounds, body }
        | E::SetMap {
            bounds,
            expression: body,
        } => {
            let previous = scope.parameters.clone();
            for bound in bounds {
                expression(&bound.set, scope, depth + 1)?;
            }
            for bound in bounds {
                scope
                    .parameters
                    .extend(names(&bound.pattern).iter().cloned());
            }
            expression(body, scope, depth + 1)?;
            scope.parameters = previous;
        }
        E::Lambda { params, body } => {
            let previous = scope.parameters.clone();
            scope
                .parameters
                .extend(params.iter().map(|param| param.name.clone()));
            expression(body, scope, depth + 1)?;
            scope.parameters = previous;
        }
        E::Choose { pattern, set, body } => {
            if let Some(set) = set {
                expression(set, scope, depth + 1)?;
            }
            let previous = scope.parameters.clone();
            scope.parameters.extend(names(pattern).iter().cloned());
            expression(body, scope, depth + 1)?;
            scope.parameters = previous;
        }
        E::SetFilter { bound, predicate } => {
            expression(&bound.set, scope, depth + 1)?;
            let previous = scope.parameters.clone();
            scope
                .parameters
                .extend(names(&bound.pattern).iter().cloned());
            expression(predicate, scope, depth + 1)?;
            scope.parameters = previous;
        }
        E::UnboundedQuantifier { names, body, .. } => {
            let previous = scope.parameters.clone();
            scope.parameters.extend(names.iter().cloned());
            expression(body, scope, depth + 1)?;
            scope.parameters = previous;
        }
        E::Except { function, updates } => {
            expression(function, scope, depth + 1)?;
            for update in updates {
                for path in &update.path {
                    if let rtla::ast::ExceptPath::Index { args } = path {
                        for argument in args {
                            expression(argument, scope, depth + 1)?;
                        }
                    }
                }
                let previous = scope.old;
                scope.old = true;
                expression(&update.value, scope, depth + 1)?;
                scope.old = previous;
            }
        }
        _ => {
            for edge in analysis_children(Node::Source(value)) {
                if let Node::Source(child) = edge.node {
                    expression(child, scope, depth + 1)?;
                }
            }
        }
    }
    Ok(())
}

pub(crate) fn validate(module: &Module) -> Result<()> {
    for entry in &module.definitions {
        definition(entry, &mut Scope::default(), 0)?;
    }
    for assumption in &module.assumptions {
        expression(
            &assumption.expression,
            &mut Scope {
                allowed: true,
                ..Scope::default()
            },
            0,
        )?;
    }
    Ok(())
}

use super::{Kind, Linked, Linker, Symbol};
use crate::rewrite::identifier;
use crate::{Result, source, unsupported};
use rtla::ast::{self, Definition, DefinitionKind, Expression, ExpressionKind as E, Pattern};
use std::collections::{BTreeMap, BTreeSet};

fn bind(pattern: &Pattern, names: &mut BTreeMap<String, usize>) {
    match pattern {
        Pattern::Name { name } => {
            names.insert(name.clone(), 0);
        }
        Pattern::Tuple { names: entries } => {
            for name in entries {
                names.insert(name.clone(), 0);
            }
        }
    }
}

impl Linker<'_> {
    pub(super) fn expand_local_definition(
        &mut self,
        definition: &mut Definition,
        outer: &Linked,
        visible: &BTreeMap<String, usize>,
        imports: &BTreeSet<String>,
        extra: &mut BTreeSet<String>,
        depth: usize,
    ) -> Result<()> {
        let mut names = visible.clone();
        match &mut definition.head {
            DefinitionKind::Operator { params } => {
                for param in params {
                    names.insert(param.name.clone(), param.arity);
                }
            }
            DefinitionKind::Function { bounds } => {
                for bound in bounds {
                    self.expand_local_expression(
                        &mut bound.set,
                        outer,
                        visible,
                        imports,
                        extra,
                        depth + 1,
                    )?;
                    bind(&bound.pattern, &mut names);
                }
            }
        }
        self.expand_local_expression(
            &mut definition.body,
            outer,
            &names,
            imports,
            extra,
            depth + 1,
        )
    }

    pub(super) fn expand_local_expression(
        &mut self,
        value: &mut Expression,
        outer: &Linked,
        visible: &BTreeMap<String, usize>,
        imports: &BTreeSet<String>,
        extra: &mut BTreeSet<String>,
        depth: usize,
    ) -> Result<()> {
        if depth > 64 {
            return unsupported("module AST depth exceeds 64");
        }
        match &mut value.node {
            E::Let { definitions, .. } | E::LetModule { definitions, .. } => {
                let mut names = visible.clone();
                for definition in definitions.iter() {
                    names.insert(
                        definition.name.clone(),
                        match &definition.head {
                            DefinitionKind::Operator { params } => params.len(),
                            DefinitionKind::Function { .. } => 0,
                        },
                    );
                }
                let count = definitions.len();
                if let E::LetModule {
                    definitions,
                    instances,
                    ..
                } = &mut value.node
                {
                    let mut sandbox = outer.clone();
                    for (name, arity) in &names {
                        sandbox.symbols.insert(
                            name.clone(),
                            Symbol {
                                captured: false,
                                id: name.clone(),
                                kind: Kind::Lexical,
                                arity: *arity,
                                local: true,
                            },
                        );
                    }
                    let previous: BTreeSet<_> = sandbox.definitions.keys().cloned().collect();
                    let symbols: BTreeSet<_> = sandbox.symbols.keys().cloned().collect();
                    let namespaces: BTreeSet<_> = sandbox.namespaces.keys().cloned().collect();
                    let mut local_imports = imports.clone();
                    for instance in instances.iter() {
                        self.instantiate(instance, &mut sandbox, &mut local_imports)?;
                    }
                    for (name, definition) in &sandbox.definitions {
                        if previous.contains(name) {
                            continue;
                        }
                        self.rewrite.translated.insert(name.clone());
                        definitions.push(definition.clone());
                    }
                    for (name, symbol) in &sandbox.symbols {
                        if symbols.contains(name) || symbol.kind != Kind::Definition {
                            continue;
                        }
                        let mut definition = sandbox.definitions[&symbol.id].clone();
                        definition.name = name.clone();
                        definition.body = match &definition.head {
                            DefinitionKind::Operator { params } => Expression {
                                location: value.location,
                                node: E::Apply {
                                    operator: symbol.id.clone(),
                                    args: params
                                        .iter()
                                        .map(|param| identifier(&param.name, param.location))
                                        .collect(),
                                },
                            },
                            DefinitionKind::Function { .. } => {
                                identifier(&symbol.id, value.location)
                            }
                        };
                        if matches!(definition.head, DefinitionKind::Function { .. }) {
                            definition.head = DefinitionKind::Operator { params: vec![] };
                        }
                        definitions.push(definition);
                        names.insert(name.clone(), symbol.arity);
                    }
                    *instances = sandbox
                        .namespaces
                        .iter()
                        .filter(|(name, _)| !namespaces.contains(*name))
                        .map(|(name, namespace)| ast::Instance {
                            name: Some(name.clone()),
                            module: "$linked".into(),
                            params: (0..namespace.arity)
                                .map(|index| ast::Declaration {
                                    name: format!("$argument{index}"),
                                    arity: 0,
                                    location: value.location,
                                })
                                .collect(),
                            substitutions: vec![],
                            is_local: namespace.local,
                            location: value.location,
                        })
                        .collect();
                    extra.extend(sandbox.extends);
                }
                let (definitions, body) = match &mut value.node {
                    E::Let { definitions, body }
                    | E::LetModule {
                        definitions, body, ..
                    } => (definitions, body),
                    _ => unreachable!(),
                };
                for definition in &mut definitions[..count] {
                    self.expand_local_definition(
                        definition,
                        outer,
                        &names,
                        imports,
                        extra,
                        depth + 1,
                    )?;
                }
                self.expand_local_expression(body, outer, &names, imports, extra, depth + 1)?;
            }
            E::Forall { bounds, body }
            | E::Exists { bounds, body }
            | E::FunctionConstruction { bounds, body }
            | E::SetMap {
                bounds,
                expression: body,
            } => {
                let mut names = visible.clone();
                for bound in bounds {
                    self.expand_local_expression(
                        &mut bound.set,
                        outer,
                        visible,
                        imports,
                        extra,
                        depth + 1,
                    )?;
                    bind(&bound.pattern, &mut names);
                }
                self.expand_local_expression(body, outer, &names, imports, extra, depth + 1)?;
            }
            E::SetFilter { bound, predicate } => {
                self.expand_local_expression(
                    &mut bound.set,
                    outer,
                    visible,
                    imports,
                    extra,
                    depth + 1,
                )?;
                let mut names = visible.clone();
                bind(&bound.pattern, &mut names);
                self.expand_local_expression(predicate, outer, &names, imports, extra, depth + 1)?;
            }
            E::Choose { pattern, set, body } => {
                if let Some(set) = set {
                    self.expand_local_expression(set, outer, visible, imports, extra, depth + 1)?;
                }
                let mut names = visible.clone();
                bind(pattern, &mut names);
                self.expand_local_expression(body, outer, &names, imports, extra, depth + 1)?;
            }
            E::Lambda { params, body } => {
                let mut names = visible.clone();
                for param in params {
                    names.insert(param.name.clone(), param.arity);
                }
                self.expand_local_expression(body, outer, &names, imports, extra, depth + 1)?;
            }
            _ => {
                for child in source::children_mut(value) {
                    self.expand_local_expression(child, outer, visible, imports, extra, depth + 1)?;
                }
            }
        }
        Ok(())
    }
}

use crate::{Result, source, unsupported};
use rtla::ast::{DefinitionKind, Expression, ExpressionKind as E, Instance, Module};
use std::collections::{BTreeMap, BTreeSet};

type Modules = BTreeMap<String, (String, usize)>;

#[derive(Clone, Default)]
pub(super) struct Scope {
    pub parent: Option<String>,
    pub declarations: BTreeMap<String, (String, String)>,
    pub instances: Vec<(String, usize)>,
}

#[derive(Default)]
pub(super) struct Sources {
    pub modules: Vec<Module>,
    pub scopes: BTreeMap<String, Scope>,
}

fn reference(name: &mut String, position: usize, modules: &Modules) -> Result<()> {
    if let Some((target, declared)) = modules.get(name) {
        if *declared >= position {
            return unsupported(format!("nested module {name} is not yet in scope"));
        }
        *name = target.clone();
    }
    Ok(())
}

fn instance(instance: &mut Instance, modules: &Modules) -> Result<()> {
    reference(&mut instance.module, instance.location.start, modules)
}

fn expression(value: &mut Expression, modules: &Modules, depth: usize) -> Result<()> {
    if depth > 64 {
        return unsupported("nested module AST depth exceeds 64");
    }
    if let E::LetModule { instances, .. } = &mut value.node {
        for entry in instances {
            instance(entry, modules)?;
        }
    }
    for child in source::children_mut(value) {
        expression(child, modules, depth + 1)?;
    }
    Ok(())
}

fn visit(
    input: &Module,
    name: String,
    inherited: &Modules,
    scope: Scope,
    inherited_extends: &[String],
    result: &mut Sources,
    depth: usize,
) -> Result<()> {
    if depth > 40 || result.modules.len() >= 257 {
        return unsupported("nested module expansion exceeds 40 levels or 257 modules");
    }
    let mut module = input.clone();
    module.name = name.clone();
    module.extends.extend(inherited_extends.iter().cloned());
    module.extends.sort();
    module.extends.dedup();
    let mut modules = inherited.clone();
    let mut declared = BTreeSet::new();
    for child in &input.modules {
        if !declared.insert(&child.name) {
            return unsupported(format!("duplicate nested module {}", child.name));
        }
        modules.insert(
            child.name.clone(),
            (format!("{name}!{}", child.name), child.location.start),
        );
    }
    for dependency in &mut module.extends {
        reference(dependency, module.location.start, &modules)?;
    }
    for entry in &mut module.instances {
        instance(entry, &modules)?;
    }
    for definition in &mut module.definitions {
        if let DefinitionKind::Function { bounds } = &mut definition.head {
            for bound in bounds {
                expression(&mut bound.set, &modules, 0)?;
            }
        }
        expression(&mut definition.body, &modules, 0)?;
    }
    for assumption in &mut module.assumptions {
        expression(&mut assumption.expression, &modules, 0)?;
    }
    for child in &input.modules {
        let mut child_scope = Scope {
            parent: Some(name.clone()),
            ..scope.clone()
        };
        for (symbol, location) in module
            .constants
            .iter()
            .chain(&module.variables)
            .map(|entry| (&entry.name, entry.location))
            .chain(
                module
                    .definitions
                    .iter()
                    .map(|entry| (&entry.name, entry.location)),
            )
        {
            if location.start < child.location.start {
                child_scope
                    .declarations
                    .insert(symbol.clone(), (name.clone(), symbol.clone()));
            }
        }
        child_scope.instances.extend(
            module
                .instances
                .iter()
                .enumerate()
                .filter(|(_, entry)| entry.location.start < child.location.start)
                .map(|(index, _)| (name.clone(), index)),
        );
        visit(
            child,
            format!("{name}!{}", child.name),
            &modules,
            child_scope,
            &module.extends,
            result,
            depth + 1,
        )?;
    }
    module.modules.clear();
    if result.modules.len() >= 257 {
        return unsupported("nested module expansion exceeds 257 modules");
    }
    result.scopes.insert(name, scope);
    result.modules.push(module);
    Ok(())
}

pub(super) fn flatten(root: &Module, dependencies: &[Module]) -> Result<Sources> {
    let mut sources = Sources::default();
    for module in std::iter::once(root).chain(dependencies) {
        visit(
            module,
            module.name.clone(),
            &BTreeMap::new(),
            Scope::default(),
            &[],
            &mut sources,
            0,
        )?;
    }
    Ok(sources)
}
